window.LAW_SEARCH_IDX = window.LAW_SEARCH_IDX || {};
window.LAW_SEARCH_IDX["国家药监局"] = {"hulianwangyaopinxinxifuwuguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强药品监督管理，规范互联网药品信息服务活动，保证互联网药品信息的真实、准确，根据《中华人民共和国药品管理法》《互联网信息服务管理办法》，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内提供互联网药品信息服务活动，适用本办法。 本办法所称互联网药品信息服务，是指通过互联网向上网用户提供药品（含医疗器械）信息的服务活动。"},{"i":3,"n":"第三条","txt":"互联网药品信息服务分为经营性和非经营性两类。 经营性互联网药品信息服务是指通过互联网向上网用户有偿提供药品信息等服务的活动。 非经营性互联网药品信息服务是指通过互联网向上网用户无偿提供公开的、共享性药品信息等服务的活动。"},{"i":4,"n":"第四条","txt":"国家食品药品监督管理总局对全国提供互联网药品信息服务活动的网站实施监督管理。 省、自治区、直辖市食品药品监督管理部门对本行政区域内提供互联网药品信息服务活动的网站实施监督管理。"},{"i":5,"n":"第五条","txt":"拟提供互联网药品信息服务的网站，应当在向国务院信息产业主管部门或者省级电信管理机构申请办理经营许可证或者办理备案手续之前，按照属地监督管理的原则，向该网站主办单位所在地省、自治区、直辖市食品药品监督管理部门提出申请，经审核同意后取得提供互联网药品信息服务的资格。"},{"i":6,"n":"第六条","txt":"各省、自治区、直辖市食品药品监督管理部门对本辖区内申请提供互联网药品信息服务的互联网站进行审核，符合条件的核发《互联网药品信息服务资格证书》。"},{"i":7,"n":"第七条","txt":"《互联网药品信息服务资格证书》的格式由国家食品药品监督管理总局统一制定。"},{"i":8,"n":"第八条","txt":"提供互联网药品信息服务的网站，应当在其网站主页显著位置标注《互联网药品信息服务资格证书》的证书编号。"},{"i":9,"n":"第九条","txt":"提供互联网药品信息服务网站所登载的药品信息必须科学、准确，必须符合国家的法律、法规和国家有关药品、医疗器械管理的相关规定。 提供互联网药品信息服务的网站不得发布麻醉药品、精神药品、医疗用毒性药品、放射性药品、戒毒药品和医疗机构制剂的产品信息。"},{"i":10,"n":"第十条","txt":"提供互联网药品信息服务的网站发布的药品（含医疗器械）广告，必须经过食品药品监督管理部门审查批准。 提供互联网药品信息服务的网站发布的药品（含医疗器械）广告要注明广告审查批准文号。"},{"i":11,"n":"第十一条","txt":"申请提供互联网药品信息服务，除应当符合《互联网信息服务管理办法》规定的要求外，还应当具备下列条件： （一）互联网药品信息服务的提供者应当为依法设立的企事业单位或者其他组织； （二）具有与开展互联网药品信息服务活动相适应的专业人员、设施及相关制度； （三）有两名以上熟悉药品、医疗器械管理法律、法规和药品、医疗器械专业知识，或者依法经资格认定的药学、医疗器械技术人员。"},{"i":12,"n":"第十二条","txt":"提供互联网药品信息服务的申请应当以一个网站为基本单元。"},{"i":13,"n":"第十三条","txt":"申请提供互联网药品信息服务，应当填写国家食品药品监督管理总局统一制发的《互联网药品信息服务申请表》，向网站主办单位所在地省、自治区、直辖市食品药品监督管理部门提出申请，同时提交以下材料： （一）企业营业执照复印件。 （二）网站域名注册的相关证书或者证明文件。从事互联网药品信息服务网站的中文名称，除与主办单位名称相同的以外，不得以“中国”“中华”“全国”等冠名；除取得药品招标代理机构资格证书的单位开办的互联网站外，其他提供互联网药品信息服务的网站名称中不得出现“电子商务”“药品招商”“药品招标”等内容。 （三）网站栏目设置说明（申请经营性互联网药品信息服务的网站需提供收费栏目及收费方式的说明）。 （四）网站对历史发布信息进行备份和查阅的相关管理制度及执行情况说明。 （五）食品药品监督管理部门在线浏览网站上所有栏目、内容的方法及操作说明。 （六）药品及医疗器械相关专业技术人员学历证明或者其"},{"i":14,"n":"第十四条","txt":"省、自治区、直辖市食品药品监督管理部门在收到申请材料之日起5日内做出受理与否的决定，受理的，发给受理通知书；不受理的，书面通知申请人并说明理由，同时告知申请人享有依法申请行政复议或者提起行政诉讼的权利。"},{"i":15,"n":"第十五条","txt":"对于申请材料不规范、不完整的，省、自治区、直辖市食品药品监督管理部门自申请之日起5日内一次告知申请人需要补正的全部内容；逾期不告知的，自收到材料之日起即为受理。"},{"i":16,"n":"第十六条","txt":"省、自治区、直辖市食品药品监督管理部门自受理之日起20日内对申请提供互联网药品信息服务的材料进行审核，并作出同意或者不同意的决定。同意的，由省、自治区、直辖市食品药品监督管理部门核发《互联网药品信息服务资格证书》，同时报国家食品药品监督管理总局备案并发布公告；不同意的，应当书面通知申请人并说明理由，同时告知申请人享有依法申请行政复议或者提起行政诉讼的权利。 国家食品药品监督管理总局对各省、自治区、直辖市食品药品监督管理部门的审核工作进行监督。"},{"i":17,"n":"第十七条","txt":"《互联网药品信息服务资格证书》有效期为5年。有效期届满，需要继续提供互联网药品信息服务的，持证单位应当在有效期届满前6个月内，向原发证机关申请换发《互联网药品信息服务资格证书》。原发证机关进行审核后，认为符合条件的，予以换发新证；认为不符合条件的，发给不予换发新证的通知并说明理由，原《互联网药品信息服务资格证书》由原发证机关收回并公告注销。 省、自治区、直辖市食品药品监督管理部门根据申请人的申请，应当在《互联网药品信息服务资格证书》有效期届满前作出是否准予其换证的决定。逾期未作出决定的，视为准予换证。"},{"i":18,"n":"第十八条","txt":"《互联网药品信息服务资格证书》可以根据互联网药品信息服务提供者的书面申请，由原发证机关收回，原发证机关应当报国家食品药品监督管理总局备案并发布公告。被收回《互联网药品信息服务资格证书》的网站不得继续从事互联网药品信息服务。"},{"i":19,"n":"第十九条","txt":"互联网药品信息服务提供者变更下列事项之一的，应当向原发证机关申请办理变更手续，填写《互联网药品信息服务项目变更申请表》，同时提供下列相关证明文件： （一）《互联网药品信息服务资格证书》中审核批准的项目（互联网药品信息服务提供者单位名称、网站名称、IP地址等）； （二）互联网药品信息服务提供者的基本项目（地址、法定代表人、企业负责人等）； （三）网站提供互联网药品信息服务的基本情况（服务方式、服务项目等）。"},{"i":20,"n":"第二十条","txt":"省、自治区、直辖市食品药品监督管理部门自受理变更申请之日起20个工作日内作出是否同意变更的审核决定。同意变更的，将变更结果予以公告并报国家食品药品监督管理总局备案；不同意变更的，以书面形式通知申请人并说明理由。"},{"i":21,"n":"第二十一条","txt":"省、自治区、直辖市食品药品监督管理部门对申请人的申请进行审查时，应当公示审批过程和审批结果。申请人和利害关系人可以对直接关系其重大利益的事项提交书面意见进行陈述和申辩。依法应当听证的，按照法定程序举行听证。"},{"i":22,"n":"第二十二条","txt":"未取得或者超出有效期使用《互联网药品信息服务资格证书》从事互联网药品信息服务的，由国家食品药品监督管理总局或者省、自治区、直辖市食品药品监督管理部门给予警告，并责令其停止从事互联网药品信息服务；情节严重的，移送相关部门，依照有关法律、法规给予处罚。"},{"i":23,"n":"第二十三条","txt":"提供互联网药品信息服务的网站不在其网站主页的显著位置标注《互联网药品信息服务资格证书》的证书编号的，国家食品药品监督管理总局或者省、自治区、直辖市食品药品监督管理部门给予警告，责令限期改正；在限定期限内拒不改正的，对提供非经营性互联网药品信息服务的网站处以500元以下罚款，对提供经营性互联网药品信息服务的网站处以5000元以上1万元以下罚款。"},{"i":24,"n":"第二十四条","txt":"互联网药品信息服务提供者违反本办法，有下列情形之一的，由国家食品药品监督管理总局或者省、自治区、直辖市食品药品监督管理部门给予警告，责令限期改正；情节严重的，对提供非经营性互联网药品信息服务的网站处以1000元以下罚款，对提供经营性互联网药品信息服务的网站处以1万元以上3万元以下罚款；构成犯罪的，移送司法部门追究刑事责任： （一）已经获得《互联网药品信息服务资格证书》，但提供的药品信息直接撮合药品网上交易的； （二）已经获得《互联网药品信息服务资格证书》，但超出审核同意的范围提供互联网药品信息服务的； （三）提供不真实互联网药品信息服务并造成不良社会影响的； （四）擅自变更互联网药品信息服务项目的。"},{"i":25,"n":"第二十五条","txt":"互联网药品信息服务提供者在其业务活动中，违法使用《互联网药品信息服务资格证书》的，由国家食品药品监督管理总局或者省、自治区、直辖市食品药品监督管理部门依照有关法律、法规的规定处罚。"},{"i":26,"n":"第二十六条","txt":"省、自治区、直辖市食品药品监督管理部门违法对互联网药品信息服务申请作出审核批准的，原发证机关应当撤销原批准的《互联网药品信息服务资格证书》，由此给申请人的合法权益造成损害的，由原发证机关依照国家赔偿法的规定给予赔偿；对直接负责的主管人员和其他直接责任人员，由其所在单位或者上级机关依法给予行政处分。"},{"i":27,"n":"第二十七条","txt":"省、自治区、直辖市食品药品监督管理部门应当对提供互联网药品信息服务的网站进行监督检查，并将检查情况向社会公告。"},{"i":28,"n":"第二十八条","txt":"本办法由国家食品药品监督管理总局负责解释。"},{"i":29,"n":"第二十九条","txt":"本办法自公布之日起施行。《互联网药品信息服务管理暂行规定》（国家药品监督管理局令第26号）同时废止。"}],"baojianshipinzhuceyubeianguanlibanfa-2":[{"i":1,"n":"第一条","txt":"为规范保健食品的注册与备案，根据《中华人民共和国食品安全法》，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内保健食品的注册与备案及其监督管理适用本办法。"},{"i":3,"n":"第三条","txt":"保健食品注册，是指市场监督管理部门根据注册申请人申请，依照法定程序、条件和要求，对申请注册的保健食品的安全性、保健功能和质量可控性等相关申请材料进行系统评价和审评，并决定是否准予其注册的审批过程。 保健食品备案，是指保健食品生产企业依照法定程序、条件和要求，将表明产品安全性、保健功能和质量可控性的材料提交市场监督管理部门进行存档、公开、备查的过程。"},{"i":4,"n":"第四条","txt":"保健食品的注册与备案及其监督管理应当遵循科学、公开、公正、便民、高效的原则。"},{"i":5,"n":"第五条","txt":"国家市场监督管理总局负责保健食品注册管理，以及首次进口的属于补充维生素、矿物质等营养物质的保健食品备案管理，并指导监督省、自治区、直辖市市场监督管理部门承担的保健食品注册与备案相关工作。 省、自治区、直辖市市场监督管理部门负责本行政区域内保健食品备案管理，并配合国家市场监督管理总局开展保健食品注册现场核查等工作。 市、县级市场监督管理部门负责本行政区域内注册和备案保健食品的监督管理，承担上级市场监督管理部门委托的其他工作。"},{"i":6,"n":"第六条","txt":"国家市场监督管理总局行政受理机构（以下简称受理机构）负责受理保健食品注册和接收相关进口保健食品备案材料。 省、自治区、直辖市市场监督管理部门负责接收相关保健食品备案材料。 国家市场监督管理总局保健食品审评机构（以下简称审评机构）负责组织保健食品审评，管理审评专家，并依法承担相关保健食品备案工作。 国家市场监督管理总局审核查验机构（以下简称查验机构）负责保健食品注册现场核查工作。"},{"i":7,"n":"第七条","txt":"保健食品注册申请人或者备案人应当具有相应的专业知识，熟悉保健食品注册管理的法律、法规、规章和技术要求。 保健食品注册申请人或者备案人应当对所提交材料的真实性、完整性、可溯源性负责，并对提交材料的真实性承担法律责任。 保健食品注册申请人或者备案人应当协助市场监督管理部门开展与注册或者备案相关的现场核查、样品抽样、复核检验和监督管理等工作。"},{"i":8,"n":"第八条","txt":"省级以上市场监督管理部门应当加强信息化建设，提高保健食品注册与备案管理信息化水平，逐步实现电子化注册与备案。"},{"i":9,"n":"第九条","txt":"生产和进口下列产品应当申请保健食品注册： （一）使用保健食品原料目录以外原料（以下简称目录外原料）的保健食品； （二）首次进口的保健食品（属于补充维生素、矿物质等营养物质的保健食品除外）。 首次进口的保健食品，是指非同一国家、同一企业、同一配方申请中国境内上市销售的保健食品。"},{"i":10,"n":"第十条","txt":"产品声称的保健功能应当已经列入保健食品功能目录。"},{"i":11,"n":"第十一条","txt":"国产保健食品注册申请人应当是在中国境内登记的法人或者其他组织；进口保健食品注册申请人应当是上市保健食品的境外生产厂商。 申请进口保健食品注册的，应当由其常驻中国代表机构或者由其委托中国境内的代理机构办理。 境外生产厂商，是指产品符合所在国（地区）上市要求的法人或者其他组织。"},{"i":12,"n":"第十二条","txt":"申请保健食品注册应当提交下列材料： （一）保健食品注册申请表，以及申请人对申请材料真实性负责的法律责任承诺书； （二）注册申请人主体登记证明文件复印件； （三）产品研发报告，包括研发人、研发时间、研制过程、中试规模以上的验证数据，目录外原料及产品安全性、保健功能、质量可控性的论证报告和相关科学依据，以及根据研发结果综合确定的产品技术要求等； （四）产品配方材料，包括原料和辅料的名称及用量、生产工艺、质量标准，必要时还应当按照规定提供原料使用依据、使用部位的说明、检验合格证明、品种鉴定报告等； （五）产品生产工艺材料，包括生产工艺流程简图及说明，关键工艺控制点及说明； （六）安全性和保健功能评价材料，包括目录外原料及产品的安全性、保健功能试验评价材料，人群食用评价材料；功效成分或者标志性成分、卫生学、稳定性、菌种鉴定、菌种毒力等试验报告，以及涉及兴奋剂、违禁药物成分等检测报告； （七）直"},{"i":13,"n":"第十三条","txt":"申请首次进口保健食品注册，除提交本办法第十二条规定的材料外，还应当提交下列材料： （一）产品生产国（地区）政府主管部门或者法律服务机构出具的注册申请人为上市保健食品境外生产厂商的资质证明文件； （二）产品生产国（地区）政府主管部门或者法律服务机构出具的保健食品上市销售一年以上的证明文件，或者产品境外销售以及人群食用情况的安全性报告； （三）产品生产国（地区）或者国际组织与保健食品相关的技术法规或者标准； （四）产品在生产国（地区）上市的包装、标签、说明书实样。 由境外注册申请人常驻中国代表机构办理注册事务的，应当提交《外国企业常驻中国代表机构登记证》及其复印件；境外注册申请人委托境内的代理机构办理注册事项的，应当提交经过公证的委托书原件以及受委托的代理机构营业执照复印件。"},{"i":14,"n":"第十四条","txt":"受理机构收到申请材料后，应当根据下列情况分别作出处理： （一）申请事项依法不需要取得注册的，应当即时告知注册申请人不受理； （二）申请事项依法不属于国家市场监督管理总局职权范围的，应当即时作出不予受理的决定，并告知注册申请人向有关行政机关申请； （三）申请材料存在可以当场更正的错误的，应当允许注册申请人当场更正； （四）申请材料不齐全或者不符合法定形式的，应当当场或者在5个工作日内一次告知注册申请人需要补正的全部内容，逾期不告知的，自收到申请材料之日起即为受理； （五）申请事项属于国家市场监督管理总局职权范围，申请材料齐全、符合法定形式，注册申请人按照要求提交全部补正申请材料的，应当受理注册申请。 受理或者不予受理注册申请，应当出具加盖国家市场监督管理总局行政许可受理专用章和注明日期的书面凭证。"},{"i":15,"n":"第十五条","txt":"受理机构应当在受理后3个工作日内将申请材料一并送交审评机构。"},{"i":16,"n":"第十六条","txt":"审评机构应当组织审评专家对申请材料进行审查，并根据实际需要组织查验机构开展现场核查，组织检验机构开展复核检验，在60个工作日内完成审评工作，并向国家市场监督管理总局提交综合审评结论和建议。 特殊情况下需要延长审评时间的，经审评机构负责人同意，可以延长20个工作日，延长决定应当及时书面告知申请人。"},{"i":17,"n":"第十七条","txt":"审评机构应当组织对申请材料中的下列内容进行审评，并根据科学依据的充足程度明确产品保健功能声称的限定用语： （一）产品研发报告的完整性、合理性和科学性； （二）产品配方的科学性，及产品安全性和保健功能； （三）目录外原料及产品的生产工艺合理性、可行性和质量可控性； （四）产品技术要求和检验方法的科学性和复现性； （五）标签、说明书样稿主要内容以及产品名称的规范性。"},{"i":18,"n":"第十八条","txt":"审评机构在审评过程中可以调阅原始资料。 审评机构认为申请材料不真实、产品存在安全性或者质量可控性问题，或者不具备声称的保健功能的，应当终止审评，提出不予注册的建议。"},{"i":19,"n":"第十九条","txt":"审评机构认为需要注册申请人补正材料的，应当一次告知需要补正的全部内容。注册申请人应当在3个月内按照补正通知的要求一次提供补充材料；审评机构收到补充材料后，审评时间重新计算。 注册申请人逾期未提交补充材料或者未完成补正，不足以证明产品安全性、保健功能和质量可控性的，审评机构应当终止审评，提出不予注册的建议。"},{"i":20,"n":"第二十条","txt":"审评机构认为需要开展现场核查的，应当及时通知查验机构按照申请材料中的产品研发报告、配方、生产工艺等技术要求进行现场核查，并对下线产品封样送复核检验机构检验。 查验机构应当自接到通知之日起30个工作日内完成现场核查，并将核查报告送交审评机构。 核查报告认为申请材料不真实、无法溯源复现或者存在重大缺陷的，审评机构应当终止审评，提出不予注册的建议。"},{"i":21,"n":"第二十一条","txt":"复核检验机构应当严格按照申请材料中的测定方法以及相关说明进行操作，对测定方法的科学性、复现性、适用性进行验证，对产品质量可控性进行复核检验，并应当自接受委托之日起60个工作日内完成复核检验，将复核检验报告送交审评机构。 复核检验结论认为测定方法不科学、无法复现、不适用或者产品质量不可控的，审评机构应当终止审评，提出不予注册的建议。"},{"i":22,"n":"第二十二条","txt":"首次进口的保健食品境外现场核查和复核检验时限，根据境外生产厂商的实际情况确定。"},{"i":23,"n":"第二十三条","txt":"保健食品审评涉及的试验和检验工作应当由国家市场监督管理总局选择的符合条件的食品检验机构承担。"},{"i":24,"n":"第二十四条","txt":"审评机构认为申请材料真实，产品科学、安全、具有声称的保健功能，生产工艺合理、可行和质量可控，技术要求和检验方法科学、合理的，应当提出予以注册的建议。 审评机构提出不予注册建议的，应当同时向注册申请人发出拟不予注册的书面通知。注册申请人对通知有异议的，应当自收到通知之日起20个工作日内向审评机构提出书面复审申请并说明复审理由。复审的内容仅限于原申请事项及申请材料。 审评机构应当自受理复审申请之日起30个工作日内作出复审决定。改变不予注册建议的，应当书面通知注册申请人。"},{"i":25,"n":"第二十五条","txt":"审评机构作出综合审评结论及建议后，应当在5个工作日内报送国家市场监督管理总局。"},{"i":26,"n":"第二十六条","txt":"国家市场监督管理总局应当自受理之日起20个工作日内对审评程序和结论的合法性、规范性以及完整性进行审查，并作出准予注册或者不予注册的决定。"},{"i":27,"n":"第二十七条","txt":"现场核查、复核检验、复审所需时间不计算在审评和注册决定的期限内。"},{"i":28,"n":"第二十八条","txt":"国家市场监督管理总局作出准予注册或者不予注册的决定后，应当自作出决定之日起10个工作日内，由受理机构向注册申请人发出保健食品注册证书或者不予注册决定。"},{"i":29,"n":"第二十九条","txt":"注册申请人对国家市场监督管理总局作出不予注册的决定有异议的，可以向国家市场监督管理总局提出书面行政复议申请或者向法院提出行政诉讼。"},{"i":30,"n":"第三十条","txt":"保健食品注册人转让技术的，受让方应当在转让方的指导下重新提出产品注册申请，产品技术要求等应当与原申请材料一致。 审评机构按照相关规定简化审评程序。符合要求的，国家市场监督管理总局应当为受让方核发新的保健食品注册证书，并对转让方保健食品注册予以注销。 受让方除提交本办法规定的注册申请材料外，还应当提交经公证的转让合同。"},{"i":31,"n":"第三十一条","txt":"保健食品注册证书及其附件所载明内容变更的，应当由保健食品注册人申请变更并提交书面变更的理由和依据。 注册人名称变更的，应当由变更后的注册申请人申请变更。"},{"i":32,"n":"第三十二条","txt":"已经生产销售的保健食品注册证书有效期届满需要延续的，保健食品注册人应当在有效期届满6个月前申请延续。 获得注册的保健食品原料已经列入保健食品原料目录，并符合相关技术要求，保健食品注册人申请变更注册，或者期满申请延续注册的，应当按照备案程序办理。"},{"i":33,"n":"第三十三条","txt":"申请变更国产保健食品注册的，除提交保健食品注册变更申请表（包括申请人对申请材料真实性负责的法律责任承诺书）、注册申请人主体登记证明文件复印件、保健食品注册证书及其附件的复印件外，还应当按照下列情形分别提交材料： （一）改变注册人名称、地址的变更申请，还应当提供该注册人名称、地址变更的证明材料； （二）改变产品名称的变更申请，还应当提供拟变更后的产品通用名与已经注册的药品名称不重名的检索材料； （三）增加保健食品功能项目的变更申请，还应当提供所增加功能项目的功能学试验报告； （四）改变产品规格、保质期、生产工艺等涉及产品技术要求的变更申请，还应当提供证明变更后产品的安全性、保健功能和质量可控性与原注册内容实质等同的材料、依据及变更后3批样品符合产品技术要求的全项目检验报告； （五）改变产品标签、说明书的变更申请，还应当提供拟变更的保健食品标签、说明书样稿。"},{"i":34,"n":"第三十四条","txt":"申请延续国产保健食品注册的，应当提交下列材料： （一）保健食品延续注册申请表，以及申请人对申请材料真实性负责的法律责任承诺书； （二）注册申请人主体登记证明文件复印件； （三）保健食品注册证书及其附件的复印件； （四）经省级市场监督管理部门核实的注册证书有效期内保健食品的生产销售情况； （五）人群食用情况分析报告、生产质量管理体系运行情况的自查报告以及符合产品技术要求的检验报告。"},{"i":35,"n":"第三十五条","txt":"申请进口保健食品变更注册或者延续注册的，除分别提交本办法第三十三条、第三十四条规定的材料外，还应当提交本办法第十三条第一款（一）、（二）、（三）、（四）项和第二款规定的相关材料。"},{"i":36,"n":"第三十六条","txt":"变更申请的理由依据充分合理，不影响产品安全性、保健功能和质量可控性的，予以变更注册；变更申请的理由依据不充分、不合理，或者拟变更事项影响产品安全性、保健功能和质量可控性的，不予变更注册。"},{"i":37,"n":"第三十七条","txt":"申请延续注册的保健食品的安全性、保健功能和质量可控性符合要求的，予以延续注册。 申请延续注册的保健食品的安全性、保健功能和质量可控性依据不足或者不再符合要求，在注册证书有效期内未进行生产销售的，以及注册人未在规定时限内提交延续申请的，不予延续注册。"},{"i":38,"n":"第三十八条","txt":"接到保健食品延续注册申请的市场监督管理部门应当在保健食品注册证书有效期届满前作出是否准予延续的决定。逾期未作出决定的，视为准予延续注册。"},{"i":39,"n":"第三十九条","txt":"准予变更注册或者延续注册的，颁发新的保健食品注册证书，同时注销原保健食品注册证书。"},{"i":40,"n":"第四十条","txt":"保健食品变更注册与延续注册的程序未作规定的，可以适用本办法关于保健食品注册的相关规定。"},{"i":41,"n":"第四十一条","txt":"保健食品注册证书应当载明产品名称、注册人名称和地址、注册号、颁发日期及有效期、保健功能、功效成分或者标志性成分及含量、产品规格、保质期、适宜人群、不适宜人群、注意事项。 保健食品注册证书附件应当载明产品标签、说明书主要内容和产品技术要求等。 产品技术要求应当包括产品名称、配方、生产工艺、感官要求、鉴别、理化指标、微生物指标、功效成分或者标志性成分含量及检测方法、装量或者重量差异指标（净含量及允许负偏差指标）、原辅料质量要求等内容。"},{"i":42,"n":"第四十二条","txt":"保健食品注册证书有效期为5年。变更注册的保健食品注册证书有效期与原保健食品注册证书有效期相同。"},{"i":43,"n":"第四十三条","txt":"国产保健食品注册号格式为：国食健注G+4位年代号+4位顺序号；进口保健食品注册号格式为：国食健注J+4位年代号+4位顺序号。"},{"i":44,"n":"第四十四条","txt":"保健食品注册有效期内，保健食品注册证书遗失或者损坏的，保健食品注册人应当向受理机构提出书面申请并说明理由。因遗失申请补发的，应当在省、自治区、直辖市市场监督管理部门网站上发布遗失声明；因损坏申请补发的，应当交回保健食品注册证书原件。 国家市场监督管理总局应当在受理后20个工作日内予以补发。补发的保健食品注册证书应当标注原批准日期，并注明“补发”字样。"},{"i":45,"n":"第四十五条","txt":"生产和进口下列保健食品应当依法备案： （一）使用的原料已经列入保健食品原料目录的保健食品； （二）首次进口的属于补充维生素、矿物质等营养物质的保健食品。 首次进口的属于补充维生素、矿物质等营养物质的保健食品，其营养物质应当是列入保健食品原料目录的物质。"},{"i":46,"n":"第四十六条","txt":"国产保健食品的备案人应当是保健食品生产企业，原注册人可以作为备案人；进口保健食品的备案人，应当是上市保健食品境外生产厂商。"},{"i":47,"n":"第四十七条","txt":"备案的产品配方、原辅料名称及用量、功效、生产工艺等应当符合法律、法规、规章、强制性标准以及保健食品原料目录技术要求的规定。"},{"i":48,"n":"第四十八条","txt":"申请保健食品备案，除应当提交本办法第十二条第（四）、（五）、（六）、（七）、（八）项规定的材料外，还应当提交下列材料： （一）保健食品备案登记表，以及备案人对提交材料真实性负责的法律责任承诺书； （二）备案人主体登记证明文件复印件； （三）产品技术要求材料； （四）具有合法资质的检验机构出具的符合产品技术要求全项目检验报告； （五）其他表明产品安全性和保健功能的材料。"},{"i":49,"n":"第四十九条","txt":"申请进口保健食品备案的，除提交本办法第四十八条规定的材料外，还应当提交本办法第十三条第一款（一）、（二）、（三）、（四）项和第二款规定的相关材料。"},{"i":50,"n":"第五十条","txt":"市场监督管理部门收到备案材料后，备案材料符合要求的，当场备案；不符合要求的，应当一次告知备案人补正相关材料。"},{"i":51,"n":"第五十一条","txt":"市场监督管理部门应当完成备案信息的存档备查工作，并发放备案号。对备案的保健食品，市场监督管理部门应当按照相关要求的格式制作备案凭证，并将备案信息表中登载的信息在其网站上公布。 国产保健食品备案号格式为：食健备G+4位年代号+2位省级行政区域代码+6位顺序编号；进口保健食品备案号格式为：食健备J+4位年代号+00+6位顺序编号。"},{"i":52,"n":"第五十二条","txt":"已经备案的保健食品，需要变更备案材料的，备案人应当向原备案机关提交变更说明及相关证明文件。备案材料符合要求的，市场监督管理部门应当将变更情况登载于变更信息中，将备案材料存档备查。"},{"i":53,"n":"第五十三条","txt":"保健食品备案信息应当包括产品名称、备案人名称和地址、备案登记号、登记日期以及产品标签、说明书和技术要求。"},{"i":54,"n":"第五十四条","txt":"申请保健食品注册或者备案的，产品标签、说明书样稿应当包括产品名称、原料、辅料、功效成分或者标志性成分及含量、适宜人群、不适宜人群、保健功能、食用量及食用方法、规格、贮藏方法、保质期、注意事项等内容及相关制定依据和说明等。"},{"i":55,"n":"第五十五条","txt":"保健食品的标签、说明书主要内容不得涉及疾病预防、治疗功能，并声明“本品不能代替药物”。"},{"i":56,"n":"第五十六条","txt":"保健食品的名称由商标名、通用名和属性名组成。 商标名，是指保健食品使用依法注册的商标名称或者符合《商标法》规定的未注册的商标名称，用以表明其产品是独有的、区别于其他同类产品。 通用名，是指表明产品主要原料等特性的名称。 属性名，是指表明产品剂型或者食品分类属性等的名称。"},{"i":57,"n":"第五十七条","txt":"保健食品名称不得含有下列内容： （一）虚假、夸大或者绝对化的词语； （二）明示或者暗示预防、治疗功能的词语； （三）庸俗或者带有封建迷信色彩的词语； （四）人体组织器官等词语； （五）除“”之外的符号； （六）其他误导消费者的词语。 保健食品名称不得含有人名、地名、汉语拼音、字母及数字等，但注册商标作为商标名、通用名中含有符合国家规定的含字母及数字的原料名除外。"},{"i":58,"n":"第五十八条","txt":"通用名不得含有下列内容： （一）已经注册的药品通用名，但以原料名称命名或者保健食品注册批准在先的除外； （二）保健功能名称或者与表述产品保健功能相关的文字； （三）易产生误导的原料简写名称； （四）营养素补充剂产品配方中部分维生素或者矿物质； （五）法律法规规定禁止使用的其他词语。"},{"i":59,"n":"第五十九条","txt":"备案保健食品通用名应当以规范的原料名称命名。"},{"i":60,"n":"第六十条","txt":"同一企业不得使用同一配方注册或者备案不同名称的保健食品；不得使用同一名称注册或者备案不同配方的保健食品。"},{"i":61,"n":"第六十一条","txt":"国家市场监督管理总局应当及时制定并公布保健食品注册申请服务指南和审查细则，方便注册申请人申报。"},{"i":62,"n":"第六十二条","txt":"承担保健食品审评、核查、检验的机构和人员应当对出具的审评意见、核查报告、检验报告负责。 保健食品审评、核查、检验机构和人员应当依照有关法律、法规、规章的规定，恪守职业道德，按照食品安全标准、技术规范等对保健食品进行审评、核查和检验，保证相关工作科学、客观和公正。"},{"i":63,"n":"第六十三条","txt":"参与保健食品注册与备案管理工作的单位和个人，应当保守在注册或者备案中获知的商业秘密。 属于商业秘密的，注册申请人和备案人在申请注册或者备案时应当在提交的资料中明确相关内容和依据。"},{"i":64,"n":"第六十四条","txt":"市场监督管理部门接到有关单位或者个人举报的保健食品注册受理、审评、核查、检验、审批等工作中的违法违规行为后，应当及时核实处理。"},{"i":65,"n":"第六十五条","txt":"除涉及国家秘密、商业秘密外，市场监督管理部门应当自完成注册或者备案工作之日起20个工作日内根据相关职责在网站公布已经注册或者备案的保健食品目录及相关信息。"},{"i":66,"n":"第六十六条","txt":"有下列情形之一的，国家市场监督管理总局根据利害关系人的请求或者依据职权，可以撤销保健食品注册证书： （一）行政机关工作人员滥用职权、玩忽职守作出准予注册决定的； （二）超越法定职权或者违反法定程序作出准予注册决定的； （三）对不具备申请资格或者不符合法定条件的注册申请人准予注册的； （四）依法可以撤销保健食品注册证书的其他情形。 注册人以欺骗、贿赂等不正当手段取得保健食品注册的，国家市场监督管理总局应当予以撤销。"},{"i":67,"n":"第六十七条","txt":"有下列情形之一的，国家市场监督管理总局应当依法办理保健食品注册注销手续： （一）保健食品注册有效期届满，注册人未申请延续或者国家食品药品监管总局不予延续的； （二）保健食品注册人申请注销的； （三）保健食品注册人依法终止的； （四）保健食品注册依法被撤销，或者保健食品注册证书依法被吊销的； （五）根据科学研究的发展，有证据表明保健食品可能存在安全隐患，依法被撤回的； （六）法律、法规规定的应当注销保健食品注册的其他情形。"},{"i":68,"n":"第六十八条","txt":"有下列情形之一的，市场监督管理部门取消保健食品备案： （一）备案材料虚假的； （二）备案产品生产工艺、产品配方等存在安全性问题的； （三）保健食品生产企业的生产许可被依法吊销、注销的； （四）备案人申请取消备案的； （五）依法应当取消备案的其他情形。"},{"i":69,"n":"第六十九条","txt":"保健食品注册与备案违法行为，食品安全法等法律法规已有规定的，依照其规定。"},{"i":70,"n":"第七十条","txt":"注册申请人隐瞒真实情况或者提供虚假材料申请注册的，国家市场监督管理总局不予受理或者不予注册，并给予警告；申请人在1年内不得再次申请注册该保健食品；构成犯罪的，依法追究刑事责任。"},{"i":71,"n":"第七十一条","txt":"注册申请人以欺骗、贿赂等不正当手段取得保健食品注册证书的，由国家市场监督管理总局撤销保健食品注册证书，并处1万元以上3万元以下罚款。被许可人在3年内不得再次申请注册；构成犯罪的，依法追究刑事责任。"},{"i":72,"n":"第七十二条","txt":"有下列情形之一的，由县级以上人民政府市场监督管理部门处以1万元以上3万元以下罚款；构成犯罪的，依法追究刑事责任。 （一）擅自转让保健食品注册证书的； （二）伪造、涂改、倒卖、出租、出借保健食品注册证书的。"},{"i":73,"n":"第七十三条","txt":"市场监督管理部门及其工作人员对不符合条件的申请人准予注册，或者超越法定职权准予注册的，依照食品安全法第一百四十四条的规定予以处理。 市场监督管理部门及其工作人员在注册审评过程中滥用职权、玩忽职守、徇私舞弊的，依照食品安全法第一百四十五条的规定予以处理。"},{"i":74,"n":"第七十四条","txt":"申请首次进口保健食品注册和办理进口保健食品备案及其变更的，应当提交中文材料，外文材料附后。中文译本应当由境内公证机构进行公证，确保与原文内容一致；申请注册的产品质量标准（中文本），必须符合中国保健食品质量标准的格式。境外机构出具的证明文件应当经生产国（地区）的公证机构公证和中国驻所在国使领馆确认。"},{"i":75,"n":"第七十五条","txt":"本办法自2016年7月1日起施行。2005年4月30日公布的《保健食品注册管理办法（试行）》（原国家食品药品监督管理局令第19号）同时废止。"}],"baojianshipinzhuceyubeianguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范保健食品的注册与备案，根据《中华人民共和国食品安全法》，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内保健食品的注册与备案及其监督管理适用本办法。"},{"i":3,"n":"第三条","txt":"保健食品注册，是指市场监督管理部门根据注册申请人申请，依照法定程序、条件和要求，对申请注册的保健食品的安全性、保健功能和质量可控性等相关申请材料进行系统评价和审评，并决定是否准予其注册的审批过程。 保健食品备案，是指保健食品生产企业依照法定程序、条件和要求，将表明产品安全性、保健功能和质量可控性的材料提交市场监督管理部门进行存档、公开、备查的过程。"},{"i":4,"n":"第四条","txt":"保健食品的注册与备案及其监督管理应当遵循科学、公开、公正、便民、高效的原则。"},{"i":5,"n":"第五条","txt":"国家市场监督管理总局负责保健食品注册管理，以及首次进口的属于补充维生素、矿物质等营养物质的保健食品备案管理，并指导监督省、自治区、直辖市市场监督管理部门承担的保健食品注册与备案相关工作。 省、自治区、直辖市市场监督管理部门负责本行政区域内保健食品备案管理，并配合国家市场监督管理总局开展保健食品注册现场核查等工作。 市、县级市场监督管理部门负责本行政区域内注册和备案保健食品的监督管理，承担上级市场监督管理部门委托的其他工作。"},{"i":6,"n":"第六条","txt":"国家市场监督管理总局行政受理机构（以下简称受理机构）负责受理保健食品注册和接收相关进口保健食品备案材料。 省、自治区、直辖市市场监督管理部门负责接收相关保健食品备案材料。 国家市场监督管理总局保健食品审评机构（以下简称审评机构）负责组织保健食品审评，管理审评专家，并依法承担相关保健食品备案工作。 国家市场监督管理总局审核查验机构（以下简称查验机构）负责保健食品注册现场核查工作。"},{"i":7,"n":"第七条","txt":"保健食品注册申请人或者备案人应当具有相应的专业知识，熟悉保健食品注册管理的法律、法规、规章和技术要求。 保健食品注册申请人或者备案人应当对所提交材料的真实性、完整性、可溯源性负责，并对提交材料的真实性承担法律责任。 保健食品注册申请人或者备案人应当协助市场监督管理部门开展与注册或者备案相关的现场核查、样品抽样、复核检验和监督管理等工作。"},{"i":8,"n":"第八条","txt":"省级以上市场监督管理部门应当加强信息化建设，提高保健食品注册与备案管理信息化水平，逐步实现电子化注册与备案。"},{"i":9,"n":"第九条","txt":"生产和进口下列产品应当申请保健食品注册： （一）使用保健食品原料目录以外原料（以下简称目录外原料）的保健食品； （二）首次进口的保健食品（属于补充维生素、矿物质等营养物质的保健食品除外）。 首次进口的保健食品，是指非同一国家、同一企业、同一配方申请中国境内上市销售的保健食品。"},{"i":10,"n":"第十条","txt":"产品声称的保健功能应当已经列入保健食品功能目录。"},{"i":11,"n":"第十一条","txt":"国产保健食品注册申请人应当是在中国境内登记的法人或者其他组织；进口保健食品注册申请人应当是上市保健食品的境外生产厂商。 申请进口保健食品注册的，应当由其常驻中国代表机构或者由其委托中国境内的代理机构办理。 境外生产厂商，是指产品符合所在国（地区）上市要求的法人或者其他组织。"},{"i":12,"n":"第十二条","txt":"申请保健食品注册应当提交下列材料： （一）保健食品注册申请表，以及申请人对申请材料真实性负责的法律责任承诺书； （二）注册申请人主体登记证明文件复印件； （三）产品研发报告，包括研发人、研发时间、研制过程、中试规模以上的验证数据，目录外原料及产品安全性、保健功能、质量可控性的论证报告和相关科学依据，以及根据研发结果综合确定的产品技术要求等； （四）产品配方材料，包括原料和辅料的名称及用量、生产工艺、质量标准，必要时还应当按照规定提供原料使用依据、使用部位的说明、检验合格证明、品种鉴定报告等； （五）产品生产工艺材料，包括生产工艺流程简图及说明，关键工艺控制点及说明； （六）安全性和保健功能评价材料，包括目录外原料及产品的安全性、保健功能试验评价材料，人群食用评价材料；功效成分或者标志性成分、卫生学、稳定性、菌种鉴定、菌种毒力等试验报告，以及涉及兴奋剂、违禁药物成分等检测报告； （七）直"},{"i":13,"n":"第十三条","txt":"申请首次进口保健食品注册，除提交本办法第十二条规定的材料外，还应当提交下列材料： （一）产品生产国（地区）政府主管部门或者法律服务机构出具的注册申请人为上市保健食品境外生产厂商的资质证明文件； （二）产品生产国（地区）政府主管部门或者法律服务机构出具的保健食品上市销售一年以上的证明文件，或者产品境外销售以及人群食用情况的安全性报告； （三）产品生产国（地区）或者国际组织与保健食品相关的技术法规或者标准； （四）产品在生产国（地区）上市的包装、标签、说明书实样。 由境外注册申请人常驻中国代表机构办理注册事务的，应当提交《外国企业常驻中国代表机构登记证》及其复印件；境外注册申请人委托境内的代理机构办理注册事项的，应当提交经过公证的委托书原件以及受委托的代理机构营业执照复印件。"},{"i":14,"n":"第十四条","txt":"受理机构收到申请材料后，应当根据下列情况分别作出处理： （一）申请事项依法不需要取得注册的，应当即时告知注册申请人不受理； （二）申请事项依法不属于国家市场监督管理总局职权范围的，应当即时作出不予受理的决定，并告知注册申请人向有关行政机关申请； （三）申请材料存在可以当场更正的错误的，应当允许注册申请人当场更正； （四）申请材料不齐全或者不符合法定形式的，应当当场或者在5个工作日内一次告知注册申请人需要补正的全部内容，逾期不告知的，自收到申请材料之日起即为受理； （五）申请事项属于国家市场监督管理总局职权范围，申请材料齐全、符合法定形式，注册申请人按照要求提交全部补正申请材料的，应当受理注册申请。 受理或者不予受理注册申请，应当出具加盖国家市场监督管理总局行政许可受理专用章和注明日期的书面凭证。"},{"i":15,"n":"第十五条","txt":"受理机构应当在受理后3个工作日内将申请材料一并送交审评机构。"},{"i":16,"n":"第十六条","txt":"审评机构应当组织审评专家对申请材料进行审查，并根据实际需要组织查验机构开展现场核查，组织检验机构开展复核检验，在60个工作日内完成审评工作，并向国家市场监督管理总局提交综合审评结论和建议。 特殊情况下需要延长审评时间的，经审评机构负责人同意，可以延长20个工作日，延长决定应当及时书面告知申请人。"},{"i":17,"n":"第十七条","txt":"审评机构应当组织对申请材料中的下列内容进行审评，并根据科学依据的充足程度明确产品保健功能声称的限定用语： （一）产品研发报告的完整性、合理性和科学性； （二）产品配方的科学性，及产品安全性和保健功能； （三）目录外原料及产品的生产工艺合理性、可行性和质量可控性； （四）产品技术要求和检验方法的科学性和复现性； （五）标签、说明书样稿主要内容以及产品名称的规范性。"},{"i":18,"n":"第十八条","txt":"审评机构在审评过程中可以调阅原始资料。 审评机构认为申请材料不真实、产品存在安全性或者质量可控性问题，或者不具备声称的保健功能的，应当终止审评，提出不予注册的建议。"},{"i":19,"n":"第十九条","txt":"审评机构认为需要注册申请人补正材料的，应当一次告知需要补正的全部内容。注册申请人应当在3个月内按照补正通知的要求一次提供补充材料；审评机构收到补充材料后，审评时间重新计算。 注册申请人逾期未提交补充材料或者未完成补正，不足以证明产品安全性、保健功能和质量可控性的，审评机构应当终止审评，提出不予注册的建议。"},{"i":20,"n":"第二十条","txt":"审评机构认为需要开展现场核查的，应当及时通知查验机构按照申请材料中的产品研发报告、配方、生产工艺等技术要求进行现场核查，并对下线产品封样送复核检验机构检验。 查验机构应当自接到通知之日起30个工作日内完成现场核查，并将核查报告送交审评机构。 核查报告认为申请材料不真实、无法溯源复现或者存在重大缺陷的，审评机构应当终止审评，提出不予注册的建议。"},{"i":21,"n":"第二十一条","txt":"复核检验机构应当严格按照申请材料中的测定方法以及相关说明进行操作，对测定方法的科学性、复现性、适用性进行验证，对产品质量可控性进行复核检验，并应当自接受委托之日起60个工作日内完成复核检验，将复核检验报告送交审评机构。 复核检验结论认为测定方法不科学、无法复现、不适用或者产品质量不可控的，审评机构应当终止审评，提出不予注册的建议。"},{"i":22,"n":"第二十二条","txt":"首次进口的保健食品境外现场核查和复核检验时限，根据境外生产厂商的实际情况确定。"},{"i":23,"n":"第二十三条","txt":"保健食品审评涉及的试验和检验工作应当由国家市场监督管理总局选择的符合条件的食品检验机构承担。"},{"i":24,"n":"第二十四条","txt":"审评机构认为申请材料真实，产品科学、安全、具有声称的保健功能，生产工艺合理、可行和质量可控，技术要求和检验方法科学、合理的，应当提出予以注册的建议。 审评机构提出不予注册建议的，应当同时向注册申请人发出拟不予注册的书面通知。注册申请人对通知有异议的，应当自收到通知之日起20个工作日内向审评机构提出书面复审申请并说明复审理由。复审的内容仅限于原申请事项及申请材料。 审评机构应当自受理复审申请之日起30个工作日内作出复审决定。改变不予注册建议的，应当书面通知注册申请人。"},{"i":25,"n":"第二十五条","txt":"审评机构作出综合审评结论及建议后，应当在5个工作日内报送国家市场监督管理总局。"},{"i":26,"n":"第二十六条","txt":"国家市场监督管理总局应当自受理之日起20个工作日内对审评程序和结论的合法性、规范性以及完整性进行审查，并作出准予注册或者不予注册的决定。"},{"i":27,"n":"第二十七条","txt":"现场核查、复核检验、复审所需时间不计算在审评和注册决定的期限内。"},{"i":28,"n":"第二十八条","txt":"国家市场监督管理总局作出准予注册或者不予注册的决定后，应当自作出决定之日起10个工作日内，由受理机构向注册申请人发出保健食品注册证书或者不予注册决定。"},{"i":29,"n":"第二十九条","txt":"注册申请人对国家市场监督管理总局作出不予注册的决定有异议的，可以向国家市场监督管理总局提出书面行政复议申请或者向法院提出行政诉讼。"},{"i":30,"n":"第三十条","txt":"保健食品注册人转让技术的，受让方应当在转让方的指导下重新提出产品注册申请，产品技术要求等应当与原申请材料一致。 审评机构按照相关规定简化审评程序。符合要求的，国家市场监督管理总局应当为受让方核发新的保健食品注册证书，并对转让方保健食品注册予以注销。 受让方除提交本办法规定的注册申请材料外，还应当提交经公证的转让合同。"},{"i":31,"n":"第三十一条","txt":"保健食品注册证书及其附件所载明内容变更的，应当由保健食品注册人申请变更并提交书面变更的理由和依据。 注册人名称变更的，应当由变更后的注册申请人申请变更。"},{"i":32,"n":"第三十二条","txt":"已经生产销售的保健食品注册证书有效期届满需要延续的，保健食品注册人应当在有效期届满6个月前申请延续。 获得注册的保健食品原料已经列入保健食品原料目录，并符合相关技术要求，保健食品注册人申请变更注册，或者期满申请延续注册的，应当按照备案程序办理。"},{"i":33,"n":"第三十三条","txt":"申请变更国产保健食品注册的，除提交保健食品注册变更申请表（包括申请人对申请材料真实性负责的法律责任承诺书）、注册申请人主体登记证明文件复印件、保健食品注册证书及其附件的复印件外，还应当按照下列情形分别提交材料： （一）改变注册人名称、地址的变更申请，还应当提供该注册人名称、地址变更的证明材料； （二）改变产品名称的变更申请，还应当提供拟变更后的产品通用名与已经注册的药品名称不重名的检索材料； （三）增加保健食品功能项目的变更申请，还应当提供所增加功能项目的功能学试验报告； （四）改变产品规格、保质期、生产工艺等涉及产品技术要求的变更申请，还应当提供证明变更后产品的安全性、保健功能和质量可控性与原注册内容实质等同的材料、依据及变更后3批样品符合产品技术要求的全项目检验报告； （五）改变产品标签、说明书的变更申请，还应当提供拟变更的保健食品标签、说明书样稿。"},{"i":34,"n":"第三十四条","txt":"申请延续国产保健食品注册的，应当提交下列材料： （一）保健食品延续注册申请表，以及申请人对申请材料真实性负责的法律责任承诺书； （二）注册申请人主体登记证明文件复印件； （三）保健食品注册证书及其附件的复印件； （四）经省级市场监督管理部门核实的注册证书有效期内保健食品的生产销售情况； （五）人群食用情况分析报告、生产质量管理体系运行情况的自查报告以及符合产品技术要求的检验报告。"},{"i":35,"n":"第三十五条","txt":"申请进口保健食品变更注册或者延续注册的，除分别提交本办法第三十三条、第三十四条规定的材料外，还应当提交本办法第十三条第一款（一）、（二）、（三）、（四）项和第二款规定的相关材料。"},{"i":36,"n":"第三十六条","txt":"变更申请的理由依据充分合理，不影响产品安全性、保健功能和质量可控性的，予以变更注册；变更申请的理由依据不充分、不合理，或者拟变更事项影响产品安全性、保健功能和质量可控性的，不予变更注册。"},{"i":37,"n":"第三十七条","txt":"申请延续注册的保健食品的安全性、保健功能和质量可控性符合要求的，予以延续注册。 申请延续注册的保健食品的安全性、保健功能和质量可控性依据不足或者不再符合要求，在注册证书有效期内未进行生产销售的，以及注册人未在规定时限内提交延续申请的，不予延续注册。"},{"i":38,"n":"第三十八条","txt":"接到保健食品延续注册申请的市场监督管理部门应当在保健食品注册证书有效期届满前作出是否准予延续的决定。逾期未作出决定的，视为准予延续注册。"},{"i":39,"n":"第三十九条","txt":"准予变更注册或者延续注册的，颁发新的保健食品注册证书，同时注销原保健食品注册证书。"},{"i":40,"n":"第四十条","txt":"保健食品变更注册与延续注册的程序未作规定的，可以适用本办法关于保健食品注册的相关规定。"},{"i":41,"n":"第四十一条","txt":"保健食品注册证书应当载明产品名称、注册人名称和地址、注册号、颁发日期及有效期、保健功能、功效成分或者标志性成分及含量、产品规格、保质期、适宜人群、不适宜人群、注意事项。 保健食品注册证书附件应当载明产品标签、说明书主要内容和产品技术要求等。 产品技术要求应当包括产品名称、配方、生产工艺、感官要求、鉴别、理化指标、微生物指标、功效成分或者标志性成分含量及检测方法、装量或者重量差异指标（净含量及允许负偏差指标）、原辅料质量要求等内容。"},{"i":42,"n":"第四十二条","txt":"保健食品注册证书有效期为5年。变更注册的保健食品注册证书有效期与原保健食品注册证书有效期相同。"},{"i":43,"n":"第四十三条","txt":"国产保健食品注册号格式为：国食健注G+4位年代号+4位顺序号；进口保健食品注册号格式为：国食健注J+4位年代号+4位顺序号。"},{"i":44,"n":"第四十四条","txt":"保健食品注册有效期内，保健食品注册证书遗失或者损坏的，保健食品注册人应当向受理机构提出书面申请并说明理由。因遗失申请补发的，应当在省、自治区、直辖市市场监督管理部门网站上发布遗失声明；因损坏申请补发的，应当交回保健食品注册证书原件。 国家市场监督管理总局应当在受理后20个工作日内予以补发。补发的保健食品注册证书应当标注原批准日期，并注明“补发”字样。"},{"i":45,"n":"第四十五条","txt":"生产和进口下列保健食品应当依法备案： （一）使用的原料已经列入保健食品原料目录的保健食品； （二）首次进口的属于补充维生素、矿物质等营养物质的保健食品。 首次进口的属于补充维生素、矿物质等营养物质的保健食品，其营养物质应当是列入保健食品原料目录的物质。"},{"i":46,"n":"第四十六条","txt":"国产保健食品的备案人应当是保健食品生产企业，原注册人可以作为备案人；进口保健食品的备案人，应当是上市保健食品境外生产厂商。"},{"i":47,"n":"第四十七条","txt":"备案的产品配方、原辅料名称及用量、功效、生产工艺等应当符合法律、法规、规章、强制性标准以及保健食品原料目录技术要求的规定。"},{"i":48,"n":"第四十八条","txt":"申请保健食品备案，除应当提交本办法第十二条第（四）、（五）、（六）、（七）、（八）项规定的材料外，还应当提交下列材料： （一）保健食品备案登记表，以及备案人对提交材料真实性负责的法律责任承诺书； （二）备案人主体登记证明文件复印件； （三）产品技术要求材料； （四）具有合法资质的检验机构出具的符合产品技术要求全项目检验报告； （五）其他表明产品安全性和保健功能的材料。"},{"i":49,"n":"第四十九条","txt":"申请进口保健食品备案的，除提交本办法第四十八条规定的材料外，还应当提交本办法第十三条第一款（一）、（二）、（三）、（四）项和第二款规定的相关材料。"},{"i":50,"n":"第五十条","txt":"市场监督管理部门收到备案材料后，备案材料符合要求的，当场备案；不符合要求的，应当一次告知备案人补正相关材料。"},{"i":51,"n":"第五十一条","txt":"市场监督管理部门应当完成备案信息的存档备查工作，并发放备案号。对备案的保健食品，市场监督管理部门应当按照相关要求的格式制作备案凭证，并将备案信息表中登载的信息在其网站上公布。 国产保健食品备案号格式为：食健备G+4位年代号+2位省级行政区域代码+6位顺序编号；进口保健食品备案号格式为：食健备J+4位年代号+00+6位顺序编号。"},{"i":52,"n":"第五十二条","txt":"已经备案的保健食品，需要变更备案材料的，备案人应当向原备案机关提交变更说明及相关证明文件。备案材料符合要求的，市场监督管理部门应当将变更情况登载于变更信息中，将备案材料存档备查。"},{"i":53,"n":"第五十三条","txt":"保健食品备案信息应当包括产品名称、备案人名称和地址、备案登记号、登记日期以及产品标签、说明书和技术要求。"},{"i":54,"n":"第五十四条","txt":"申请保健食品注册或者备案的，产品标签、说明书样稿应当包括产品名称、原料、辅料、功效成分或者标志性成分及含量、适宜人群、不适宜人群、保健功能、食用量及食用方法、规格、贮藏方法、保质期、注意事项等内容及相关制定依据和说明等。"},{"i":55,"n":"第五十五条","txt":"保健食品的标签、说明书主要内容不得涉及疾病预防、治疗功能，并声明“本品不能代替药物”。"},{"i":56,"n":"第五十六条","txt":"保健食品的名称由商标名、通用名和属性名组成。 商标名，是指保健食品使用依法注册的商标名称或者符合《商标法》规定的未注册的商标名称，用以表明其产品是独有的、区别于其他同类产品。 通用名，是指表明产品主要原料等特性的名称。 属性名，是指表明产品剂型或者食品分类属性等的名称。"},{"i":57,"n":"第五十七条","txt":"保健食品名称不得含有下列内容： （一）虚假、夸大或者绝对化的词语； （二）明示或者暗示预防、治疗功能的词语； （三）庸俗或者带有封建迷信色彩的词语； （四）人体组织器官等词语； （五）除“”之外的符号； （六）其他误导消费者的词语。 保健食品名称不得含有人名、地名、汉语拼音、字母及数字等，但注册商标作为商标名、通用名中含有符合国家规定的含字母及数字的原料名除外。"},{"i":58,"n":"第五十八条","txt":"通用名不得含有下列内容： （一）已经注册的药品通用名，但以原料名称命名或者保健食品注册批准在先的除外； （二）保健功能名称或者与表述产品保健功能相关的文字； （三）易产生误导的原料简写名称； （四）营养素补充剂产品配方中部分维生素或者矿物质； （五）法律法规规定禁止使用的其他词语。"},{"i":59,"n":"第五十九条","txt":"备案保健食品通用名应当以规范的原料名称命名。"},{"i":60,"n":"第六十条","txt":"同一企业不得使用同一配方注册或者备案不同名称的保健食品；不得使用同一名称注册或者备案不同配方的保健食品。"},{"i":61,"n":"第六十一条","txt":"国家市场监督管理总局应当及时制定并公布保健食品注册申请服务指南和审查细则，方便注册申请人申报。"},{"i":62,"n":"第六十二条","txt":"承担保健食品审评、核查、检验的机构和人员应当对出具的审评意见、核查报告、检验报告负责。 保健食品审评、核查、检验机构和人员应当依照有关法律、法规、规章的规定，恪守职业道德，按照食品安全标准、技术规范等对保健食品进行审评、核查和检验，保证相关工作科学、客观和公正。"},{"i":63,"n":"第六十三条","txt":"参与保健食品注册与备案管理工作的单位和个人，应当保守在注册或者备案中获知的商业秘密。 属于商业秘密的，注册申请人和备案人在申请注册或者备案时应当在提交的资料中明确相关内容和依据。"},{"i":64,"n":"第六十四条","txt":"市场监督管理部门接到有关单位或者个人举报的保健食品注册受理、审评、核查、检验、审批等工作中的违法违规行为后，应当及时核实处理。"},{"i":65,"n":"第六十五条","txt":"除涉及国家秘密、商业秘密外，市场监督管理部门应当自完成注册或者备案工作之日起20个工作日内根据相关职责在网站公布已经注册或者备案的保健食品目录及相关信息。"},{"i":66,"n":"第六十六条","txt":"有下列情形之一的，国家市场监督管理总局根据利害关系人的请求或者依据职权，可以撤销保健食品注册证书： （一）行政机关工作人员滥用职权、玩忽职守作出准予注册决定的； （二）超越法定职权或者违反法定程序作出准予注册决定的； （三）对不具备申请资格或者不符合法定条件的注册申请人准予注册的； （四）依法可以撤销保健食品注册证书的其他情形。 注册人以欺骗、贿赂等不正当手段取得保健食品注册的，国家市场监督管理总局应当予以撤销。"},{"i":67,"n":"第六十七条","txt":"有下列情形之一的，国家市场监督管理总局应当依法办理保健食品注册注销手续： （一）保健食品注册有效期届满，注册人未申请延续或者国家食品药品监管总局不予延续的； （二）保健食品注册人申请注销的； （三）保健食品注册人依法终止的； （四）保健食品注册依法被撤销，或者保健食品注册证书依法被吊销的； （五）根据科学研究的发展，有证据表明保健食品可能存在安全隐患，依法被撤回的； （六）法律、法规规定的应当注销保健食品注册的其他情形。"},{"i":68,"n":"第六十八条","txt":"有下列情形之一的，市场监督管理部门取消保健食品备案： （一）备案材料虚假的； （二）备案产品生产工艺、产品配方等存在安全性问题的； （三）保健食品生产企业的生产许可被依法吊销、注销的； （四）备案人申请取消备案的； （五）依法应当取消备案的其他情形。"},{"i":69,"n":"第六十九条","txt":"保健食品注册与备案违法行为，食品安全法等法律法规已有规定的，依照其规定。"},{"i":70,"n":"第七十条","txt":"注册申请人隐瞒真实情况或者提供虚假材料申请注册的，国家市场监督管理总局不予受理或者不予注册，并给予警告；申请人在1年内不得再次申请注册该保健食品；构成犯罪的，依法追究刑事责任。"},{"i":71,"n":"第七十一条","txt":"注册申请人以欺骗、贿赂等不正当手段取得保健食品注册证书的，由国家市场监督管理总局撤销保健食品注册证书，并处1万元以上3万元以下罚款。被许可人在3年内不得再次申请注册；构成犯罪的，依法追究刑事责任。"},{"i":72,"n":"第七十二条","txt":"有下列情形之一的，由县级以上人民政府市场监督管理部门处以1万元以上3万元以下罚款；构成犯罪的，依法追究刑事责任。 （一）擅自转让保健食品注册证书的； （二）伪造、涂改、倒卖、出租、出借保健食品注册证书的。"},{"i":73,"n":"第七十三条","txt":"市场监督管理部门及其工作人员对不符合条件的申请人准予注册，或者超越法定职权准予注册的，依照食品安全法第一百四十四条的规定予以处理。 市场监督管理部门及其工作人员在注册审评过程中滥用职权、玩忽职守、徇私舞弊的，依照食品安全法第一百四十五条的规定予以处理。"},{"i":74,"n":"第七十四条","txt":"申请首次进口保健食品注册和办理进口保健食品备案及其变更的，应当提交中文材料，外文材料附后。中文译本应当由境内公证机构进行公证，确保与原文内容一致；申请注册的产品质量标准（中文本），必须符合中国保健食品质量标准的格式。境外机构出具的证明文件应当经生产国（地区）的公证机构公证和中国驻所在国使领馆确认。"},{"i":75,"n":"第七十五条","txt":"本办法自2016年7月1日起施行。2005年4月30日公布的《保健食品注册管理办法（试行）》（原国家食品药品监督管理局令第19号）同时废止。"}],"yiliaoqixieshiyongzhiliangjianduguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强医疗器械使用质量监督管理，保证医疗器械使用安全、有效，根据《医疗器械监督管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"使用环节的医疗器械质量管理及其监督管理，应当遵守本办法。"},{"i":3,"n":"第三条","txt":"国家食品药品监督管理总局负责全国医疗器械使用质量监督管理工作。县级以上地方食品药品监督管理部门负责本行政区域的医疗器械使用质量监督管理工作。 上级食品药品监督管理部门负责指导和监督下级食品药品监督管理部门开展医疗器械使用质量监督管理工作。"},{"i":4,"n":"第四条","txt":"医疗器械使用单位应当按照本办法，配备与其规模相适应的医疗器械质量管理机构或者质量管理人员，建立覆盖质量管理全过程的使用质量管理制度，承担本单位使用医疗器械的质量管理责任。 鼓励医疗器械使用单位采用信息化技术手段进行医疗器械质量管理。"},{"i":5,"n":"第五条","txt":"医疗器械生产经营企业销售的医疗器械应当符合强制性标准以及经注册或者备案的产品技术要求。医疗器械生产经营企业应当按照与医疗器械使用单位的合同约定，提供医疗器械售后服务，指导和配合医疗器械使用单位开展质量管理工作。"},{"i":6,"n":"第六条","txt":"医疗器械使用单位发现所使用的医疗器械发生不良事件或者可疑不良事件的，应当按照医疗器械不良事件监测的有关规定报告并处理。"},{"i":7,"n":"第七条","txt":"医疗器械使用单位应当对医疗器械采购实行统一管理，由其指定的部门或者人员统一采购医疗器械，其他部门或者人员不得自行采购。"},{"i":8,"n":"第八条","txt":"医疗器械使用单位应当从具有资质的医疗器械生产经营企业购进医疗器械，索取、查验供货者资质、医疗器械注册证或者备案凭证等证明文件。对购进的医疗器械应当验明产品合格证明文件，并按规定进行验收。对有特殊储运要求的医疗器械还应当核实储运条件是否符合产品说明书和标签标示的要求。"},{"i":9,"n":"第九条","txt":"医疗器械使用单位应当真实、完整、准确地记录进货查验情况。进货查验记录应当保存至医疗器械规定使用期限届满后2年或者使用终止后2年。大型医疗器械进货查验记录应当保存至医疗器械规定使用期限届满后5年或者使用终止后5年；植入性医疗器械进货查验记录应当永久保存。 医疗器械使用单位应当妥善保存购入第三类医疗器械的原始资料，确保信息具有可追溯性。"},{"i":10,"n":"第十条","txt":"医疗器械使用单位贮存医疗器械的场所、设施及条件应当与医疗器械品种、数量相适应，符合产品说明书、标签标示的要求及使用安全、有效的需要；对温度、湿度等环境条件有特殊要求的，还应当监测和记录贮存区域的温度、湿度等数据。"},{"i":11,"n":"第十一条","txt":"医疗器械使用单位应当按照贮存条件、医疗器械有效期限等要求对贮存的医疗器械进行定期检查并记录。"},{"i":12,"n":"第十二条","txt":"医疗器械使用单位不得购进和使用未依法注册或者备案、无合格证明文件以及过期、失效、淘汰的医疗器械。"},{"i":13,"n":"第十三条","txt":"医疗器械使用单位应当建立医疗器械使用前质量检查制度。在使用医疗器械前，应当按照产品说明书的有关要求进行检查。 使用无菌医疗器械前，应当检查直接接触医疗器械的包装及其有效期限。包装破损、标示不清、超过有效期限或者可能影响使用安全、有效的，不得使用。"},{"i":14,"n":"第十四条","txt":"医疗器械使用单位对植入和介入类医疗器械应当建立使用记录，植入性医疗器械使用记录永久保存，相关资料应当纳入信息化管理系统，确保信息可追溯。"},{"i":15,"n":"第十五条","txt":"医疗器械使用单位应当建立医疗器械维护维修管理制度。对需要定期检查、检验、校准、保养、维护的医疗器械，应当按照产品说明书的要求进行检查、检验、校准、保养、维护并记录，及时进行分析、评估，确保医疗器械处于良好状态。 对使用期限长的大型医疗器械，应当逐台建立使用档案，记录其使用、维护等情况。记录保存期限不得少于医疗器械规定使用期限届满后5年或者使用终止后5年。"},{"i":16,"n":"第十六条","txt":"医疗器械使用单位应当按照产品说明书等要求使用医疗器械。一次性使用的医疗器械不得重复使用，对使用过的应当按照国家有关规定销毁并记录。"},{"i":17,"n":"第十七条","txt":"医疗器械使用单位可以按照合同的约定要求医疗器械生产经营企业提供医疗器械维护维修服务，也可以委托有条件和能力的维修服务机构进行医疗器械维护维修，或者自行对在用医疗器械进行维护维修。 医疗器械使用单位委托维修服务机构或者自行对在用医疗器械进行维护维修的，医疗器械生产经营企业应当按照合同的约定提供维护手册、维修手册、软件备份、故障代码表、备件清单、零部件、维修密码等维护维修必需的材料和信息。"},{"i":18,"n":"第十八条","txt":"由医疗器械生产经营企业或者维修服务机构对医疗器械进行维护维修的，应当在合同中约定明确的质量要求、维修要求等相关事项，医疗器械使用单位应当在每次维护维修后索取并保存相关记录；医疗器械使用单位自行对医疗器械进行维护维修的，应当加强对从事医疗器械维护维修的技术人员的培训考核，并建立培训档案。"},{"i":19,"n":"第十九条","txt":"医疗器械使用单位发现使用的医疗器械存在安全隐患的，应当立即停止使用，通知检修；经检修仍不能达到使用安全标准的，不得继续使用，并按照有关规定处置。"},{"i":20,"n":"第二十条","txt":"医疗器械使用单位之间转让在用医疗器械，转让方应当确保所转让的医疗器械安全、有效，并提供产品合法证明文件。 转让双方应当签订协议，移交产品说明书、使用和维修记录档案复印件等资料，并经有资质的检验机构检验合格后方可转让。受让方应当参照本办法第八条关于进货查验的规定进行查验，符合要求后方可使用。 不得转让未依法注册或者备案、无合格证明文件或者检验不合格，以及过期、失效、淘汰的医疗器械。"},{"i":21,"n":"第二十一条","txt":"医疗器械使用单位接受医疗器械生产经营企业或者其他机构、个人捐赠医疗器械的，捐赠方应当提供医疗器械的相关合法证明文件，受赠方应当参照本办法第八条关于进货查验的规定进行查验，符合要求后方可使用。 不得捐赠未依法注册或者备案、无合格证明文件或者检验不合格，以及过期、失效、淘汰的医疗器械。 医疗器械使用单位之间捐赠在用医疗器械的，参照本办法第二十条关于转让在用医疗器械的规定办理。"},{"i":22,"n":"第二十二条","txt":"食品药品监督管理部门按照风险管理原则，对使用环节的医疗器械质量实施监督管理。 设区的市级食品药品监督管理部门应当编制并实施本行政区域的医疗器械使用单位年度监督检查计划，确定监督检查的重点、频次和覆盖率。对存在较高风险的医疗器械、有特殊储运要求的医疗器械以及有不良信用记录的医疗器械使用单位等，应当实施重点监管。 年度监督检查计划及其执行情况应当报告省、自治区、直辖市食品药品监督管理部门。"},{"i":23,"n":"第二十三条","txt":"食品药品监督管理部门对医疗器械使用单位建立、执行医疗器械使用质量管理制度的情况进行监督检查，应当记录监督检查结果，并纳入监督管理档案。 食品药品监督管理部门对医疗器械使用单位进行监督检查时，可以对相关的医疗器械生产经营企业、维修服务机构等进行延伸检查。 医疗器械使用单位、生产经营企业和维修服务机构等应当配合食品药品监督管理部门的监督检查，如实提供有关情况和资料，不得拒绝和隐瞒。"},{"i":24,"n":"第二十四条","txt":"医疗器械使用单位应当按照本办法和本单位建立的医疗器械使用质量管理制度，每年对医疗器械质量管理工作进行全面自查，并形成自查报告。食品药品监督管理部门在监督检查中对医疗器械使用单位的自查报告进行抽查。"},{"i":25,"n":"第二十五条","txt":"食品药品监督管理部门应当加强对使用环节医疗器械的抽查检验。省级以上食品药品监督管理部门应当根据抽查检验结论，及时发布医疗器械质量公告。"},{"i":26,"n":"第二十六条","txt":"个人和组织发现医疗器械使用单位有违反本办法的行为，有权向医疗器械使用单位所在地食品药品监督管理部门举报。接到举报的食品药品监督管理部门应当及时核实、处理。经查证属实的，应当按照有关规定对举报人给予奖励。"},{"i":27,"n":"第二十七条","txt":"医疗器械使用单位有下列情形之一的，由县级以上食品药品监督管理部门按照《医疗器械监督管理条例》第六十六条的规定予以处罚： （一）使用不符合强制性标准或者不符合经注册或者备案的产品技术要求的医疗器械的； （二）使用无合格证明文件、过期、失效、淘汰的医疗器械，或者使用未依法注册的医疗器械的。"},{"i":28,"n":"第二十八条","txt":"医疗器械使用单位有下列情形之一的，由县级以上食品药品监督管理部门按照《医疗器械监督管理条例》第六十七条的规定予以处罚： （一）未按照医疗器械产品说明书和标签标示要求贮存医疗器械的； （二）转让或者捐赠过期、失效、淘汰、检验不合格的在用医疗器械的。"},{"i":29,"n":"第二十九条","txt":"医疗器械使用单位有下列情形之一的，由县级以上食品药品监督管理部门按照《医疗器械监督管理条例》第六十八条的规定予以处罚： （一）未建立并执行医疗器械进货查验制度，未查验供货者的资质，或者未真实、完整、准确地记录进货查验情况的； （二）未按照产品说明书的要求进行定期检查、检验、校准、保养、维护并记录的； （三）发现使用的医疗器械存在安全隐患未立即停止使用、通知检修，或者继续使用经检修仍不能达到使用安全标准的医疗器械的； （四）未妥善保存购入第三类医疗器械的原始资料的； （五）未按规定建立和保存植入和介入类医疗器械使用记录的。"},{"i":30,"n":"第三十条","txt":"医疗器械使用单位有下列情形之一的，由县级以上食品药品监督管理部门责令限期改正，给予警告；拒不改正的，处1万元以下罚款： （一）未按规定配备与其规模相适应的医疗器械质量管理机构或者质量管理人员，或者未按规定建立覆盖质量管理全过程的使用质量管理制度的； （二）未按规定由指定的部门或者人员统一采购医疗器械的； （三）购进、使用未备案的第一类医疗器械，或者从未备案的经营企业购进第二类医疗器械的； （四）贮存医疗器械的场所、设施及条件与医疗器械品种、数量不相适应的，或者未按照贮存条件、医疗器械有效期限等要求对贮存的医疗器械进行定期检查并记录的； （五）未按规定建立、执行医疗器械使用前质量检查制度的； （六）未按规定索取、保存医疗器械维护维修相关记录的； （七）未按规定对本单位从事医疗器械维护维修的相关技术人员进行培训考核、建立培训档案的； （八）未按规定对其医疗器械质量管理工作进行自查、形成自查"},{"i":31,"n":"第三十一条","txt":"医疗器械生产经营企业违反本办法第十七条规定，未按要求提供维护维修服务，或者未按要求提供维护维修所必需的材料和信息的，由县级以上食品药品监督管理部门给予警告，责令限期改正；情节严重或者拒不改正的，处5000元以上2万元以下罚款。"},{"i":32,"n":"第三十二条","txt":"医疗器械使用单位、生产经营企业和维修服务机构等不配合食品药品监督管理部门的监督检查，或者拒绝、隐瞒、不如实提供有关情况和资料的，由县级以上食品药品监督管理部门责令改正，给予警告，可以并处2万元以下罚款。"},{"i":33,"n":"第三十三条","txt":"用于临床试验的试验用医疗器械的质量管理，按照医疗器械临床试验等有关规定执行。"},{"i":34,"n":"第三十四条","txt":"对使用环节的医疗器械使用行为的监督管理，按照国家卫生和计划生育委员会的有关规定执行。"},{"i":35,"n":"第三十五条","txt":"本办法自2016年2月1日起施行。"}],"yiliaoqixiefenleiguize":[{"i":1,"n":"第一条","txt":"为规范医疗器械分类，根据《医疗器械监督管理条例》，制定本规则。"},{"i":2,"n":"第二条","txt":"本规则用于指导制定医疗器械分类目录和确定新的医疗器械的管理类别。"},{"i":3,"n":"第三条","txt":"本规则有关用语的含义是： （一）预期目的 指产品说明书、标签或者宣传资料载明的，使用医疗器械应当取得的作用。 （二）无源医疗器械 不依靠电能或者其他能源，但是可以通过由人体或者重力产生的能量，发挥其功能的医疗器械。 （三）有源医疗器械 任何依靠电能或者其他能源，而不是直接由人体或者重力产生的能量，发挥其功能的医疗器械。 （四）侵入器械 借助手术全部或者部分通过体表侵入人体，接触体内组织、血液循环系统、中枢神经系统等部位的医疗器械，包括介入手术中使用的器材、一次性使用无菌手术器械和暂时或短期留在人体内的器械等。本规则中的侵入器械不包括重复使用手术器械。 （五）重复使用手术器械 用于手术中进行切、割、钻、锯、抓、刮、钳、抽、夹等过程，不连接任何有源医疗器械，通过一定的处理可以重新使用的无源医疗器械。 （六）植入器械 借助手术全部或者部分进入人体内或腔道（口）中，或者用于替代人体上皮表面或眼"},{"i":4,"n":"第四条","txt":"医疗器械按照风险程度由低到高，管理类别依次分为第一类、第二类和第三类。 医疗器械风险程度，应当根据医疗器械的预期目的，通过结构特征、使用形式、使用状态、是否接触人体等因素综合判定。"},{"i":5,"n":"第五条","txt":"依据影响医疗器械风险程度的因素，医疗器械可以分为以下几种情形： （一）根据结构特征的不同，分为无源医疗器械和有源医疗器械。 （二）根据是否接触人体，分为接触人体器械和非接触人体器械。 （三）根据不同的结构特征和是否接触人体，医疗器械的使用形式包括： 无源接触人体器械：液体输送器械、改变血液体液器械、医用敷料、侵入器械、重复使用手术器械、植入器械、避孕和计划生育器械、其他无源接触人体器械。 无源非接触人体器械：护理器械、医疗器械清洗消毒器械、其他无源非接触人体器械。 有源接触人体器械：能量治疗器械、诊断监护器械、液体输送器械、电离辐射器械、植入器械、其他有源接触人体器械。 有源非接触人体器械：临床检验仪器设备、独立软件、医疗器械消毒灭菌设备、其他有源非接触人体器械。 （四）根据不同的结构特征、是否接触人体以及使用形式，医疗器械的使用状态或者其产生的影响包括以下情形： 无源接触人体器械：根"},{"i":6,"n":"第六条","txt":"医疗器械的分类应当根据医疗器械分类判定表（见附件）进行分类判定。有以下情形的，还应当结合下述原则进行分类： （一）如果同一医疗器械适用两个或者两个以上的分类，应当采取其中风险程度最高的分类；由多个医疗器械组成的医疗器械包，其分类应当与包内风险程度最高的医疗器械一致。 （二）可作为附件的医疗器械，其分类应当综合考虑该附件对配套主体医疗器械安全性、有效性的影响；如果附件对配套主体医疗器械有重要影响，附件的分类应不低于配套主体医疗器械的分类。 （三）监控或者影响医疗器械主要功能的医疗器械，其分类应当与被监控、影响的医疗器械的分类一致。 （四）以医疗器械作用为主的药械组合产品，按照第三类医疗器械管理。 （五）可被人体吸收的医疗器械，按照第三类医疗器械管理。 （六）对医疗效果有重要影响的有源接触人体器械，按照第三类医疗器械管理。 （七）医用敷料如果有以下情形，按照第三类医疗器械管理，包括：预期具"},{"i":7,"n":"第七条","txt":"体外诊断试剂按照有关规定进行分类。"},{"i":8,"n":"第八条","txt":"国家食品药品监督管理总局根据医疗器械生产、经营、使用情况，及时对医疗器械的风险变化进行分析、评价，对医疗器械分类目录进行调整。"},{"i":9,"n":"第九条","txt":"国家食品药品监督管理总局可以组织医疗器械分类专家委员会制定、调整医疗器械分类目录。"},{"i":10,"n":"第十条","txt":"本规则自2016年1月1日起施行。2000年4月5日公布的《医疗器械分类规则》（原国家药品监督管理局令第15号）同时废止。 附件：医疗器械分类判定表 注：1．本表中“Ⅰ”、“Ⅱ”、“Ⅲ”分别代表第一类、第二类、第三类医疗器械； 2．本表中“－”代表不存在这种情形。"}],"yiliaoqixiezhaohuiguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强医疗器械监督管理，控制存在缺陷的医疗器械产品，消除医疗器械安全隐患，保证医疗器械的安全、有效，保障人体健康和生命安全，根据《医疗器械监督管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"中华人民共和国境内已上市医疗器械的召回及其监督管理，适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称医疗器械召回，是指医疗器械生产企业按照规定的程序对其已上市销售的某一类别、型号或者批次的存在缺陷的医疗器械产品，采取警示、检查、修理、重新标签、修改并完善说明书、软件更新、替换、收回、销毁等方式进行处理的行为。 前款所述医疗器械生产企业，是指境内医疗器械产品注册人或者备案人、进口医疗器械的境外制造厂商在中国境内指定的代理人。"},{"i":4,"n":"第四条","txt":"本办法所称存在缺陷的医疗器械产品包括： （一）正常使用情况下存在可能危及人体健康和生命安全的不合理风险的产品； （二）不符合强制性标准、经注册或者备案的产品技术要求的产品； （三）不符合医疗器械生产、经营质量管理有关规定导致可能存在不合理风险的产品； （四）其他需要召回的产品。"},{"i":5,"n":"第五条","txt":"医疗器械生产企业是控制与消除产品缺陷的责任主体，应当主动对缺陷产品实施召回。"},{"i":6,"n":"第六条","txt":"医疗器械生产企业应当按照本办法的规定建立健全医疗器械召回管理制度，收集医疗器械安全相关信息，对可能的缺陷产品进行调查、评估，及时召回缺陷产品。 进口医疗器械的境外制造厂商在中国境内指定的代理人应当将仅在境外实施医疗器械召回的有关信息及时报告国家食品药品监督管理总局；凡涉及在境内实施召回的，中国境内指定的代理人应当按照本办法的规定组织实施。 医疗器械经营企业、使用单位应当积极协助医疗器械生产企业对缺陷产品进行调查、评估，主动配合生产企业履行召回义务，按照召回计划及时传达、反馈医疗器械召回信息，控制和收回缺陷产品。"},{"i":7,"n":"第七条","txt":"医疗器械经营企业、使用单位发现其经营、使用的医疗器械可能为缺陷产品的，应当立即暂停销售或者使用该医疗器械，及时通知医疗器械生产企业或者供货商，并向所在地省、自治区、直辖市食品药品监督管理部门报告；使用单位为医疗机构的，还应当同时向所在地省、自治区、直辖市卫生行政部门报告。 医疗器械经营企业、使用单位所在地省、自治区、直辖市食品药品监督管理部门收到报告后，应当及时通报医疗器械生产企业所在地省、自治区、直辖市食品药品监督管理部门。"},{"i":8,"n":"第八条","txt":"召回医疗器械的生产企业所在地省、自治区、直辖市食品药品监督管理部门负责医疗器械召回的监督管理，其他省、自治区、直辖市食品药品监督管理部门应当配合做好本行政区域内医疗器械召回的有关工作。 国家食品药品监督管理总局监督全国医疗器械召回的管理工作。"},{"i":9,"n":"第九条","txt":"国家食品药品监督管理总局和省、自治区、直辖市食品药品监督管理部门应当按照医疗器械召回信息通报和信息公开有关制度，采取有效途径向社会公布缺陷产品信息和召回信息，必要时向同级卫生行政部门通报相关信息。"},{"i":10,"n":"第十条","txt":"医疗器械生产企业应当按照规定建立健全医疗器械质量管理体系和医疗器械不良事件监测系统，收集、记录医疗器械的质量投诉信息和医疗器械不良事件信息，对收集的信息进行分析，对可能存在的缺陷进行调查和评估。 医疗器械经营企业、使用单位应当配合医疗器械生产企业对有关医疗器械缺陷进行调查，并提供有关资料。"},{"i":11,"n":"第十一条","txt":"医疗器械生产企业应当按照规定及时将收集的医疗器械不良事件信息向食品药品监督管理部门报告，食品药品监督管理部门可以对医疗器械不良事件或者可能存在的缺陷进行分析和调查，医疗器械生产企业、经营企业、使用单位应当予以配合。"},{"i":12,"n":"第十二条","txt":"对存在缺陷的医疗器械产品进行评估的主要内容包括： （一）产品是否符合强制性标准、经注册或者备案的产品技术要求； （二）在使用医疗器械过程中是否发生过故障或者伤害； （三）在现有使用环境下是否会造成伤害，是否有科学文献、研究、相关试验或者验证能够解释伤害发生的原因； （四）伤害所涉及的地区范围和人群特点； （五）对人体健康造成的伤害程度； （六）伤害发生的概率； （七）发生伤害的短期和长期后果； （八）其他可能对人体造成伤害的因素。"},{"i":13,"n":"第十三条","txt":"根据医疗器械缺陷的严重程度，医疗器械召回分为： （一）一级召回：使用该医疗器械可能或者已经引起严重健康危害的； （二）二级召回：使用该医疗器械可能或者已经引起暂时的或者可逆的健康危害的； （三）三级召回：使用该医疗器械引起危害的可能性较小但仍需要召回的。 医疗器械生产企业应当根据具体情况确定召回级别并根据召回级别与医疗器械的销售和使用情况，科学设计召回计划并组织实施。"},{"i":14,"n":"第十四条","txt":"医疗器械生产企业按照本办法第十条、第十二条的要求进行调查评估后，确定医疗器械产品存在缺陷的，应当立即决定并实施召回，同时向社会发布产品召回信息。 实施一级召回的，医疗器械召回公告应当在国家食品药品监督管理总局网站和中央主要媒体上发布；实施二级、三级召回的，医疗器械召回公告应当在省、自治区、直辖市食品药品监督管理部门网站发布，省、自治区、直辖市食品药品监督管理部门网站发布的召回公告应当与国家食品药品监督管理总局网站链接。"},{"i":15,"n":"第十五条","txt":"医疗器械生产企业作出医疗器械召回决定的，一级召回应当在1日内，二级召回应当在3日内，三级召回应当在7日内，通知到有关医疗器械经营企业、使用单位或者告知使用者。 召回通知应当包括以下内容： （一）召回医疗器械名称、型号规格、批次等基本信息； （二）召回的原因； （三）召回的要求，如立即暂停销售和使用该产品、将召回通知转发到相关经营企业或者使用单位等； （四）召回医疗器械的处理方式。"},{"i":16,"n":"第十六条","txt":"医疗器械生产企业作出医疗器械召回决定的，应当立即向所在地省、自治区、直辖市食品药品监督管理部门和批准该产品注册或者办理备案的食品药品监督管理部门提交医疗器械召回事件报告表，并在5个工作日内将调查评估报告和召回计划提交至所在地省、自治区、直辖市食品药品监督管理部门和批准注册或者办理备案的食品药品监督管理部门备案。 医疗器械生产企业所在地省、自治区、直辖市食品药品监督管理部门应当在收到召回事件报告表1个工作日内将召回的有关情况报告国家食品药品监督管理总局。"},{"i":17,"n":"第十七条","txt":"调查评估报告应当包括以下内容： （一）召回医疗器械的具体情况，包括名称、型号规格、批次等基本信息； （二）实施召回的原因； （三）调查评估结果； （四）召回分级。 召回计划应当包括以下内容： （一）医疗器械生产销售情况及拟召回的数量； （二）召回措施的具体内容，包括实施的组织、范围和时限等； （三）召回信息的公布途径与范围； （四）召回的预期效果； （五）医疗器械召回后的处理措施。"},{"i":18,"n":"第十八条","txt":"医疗器械生产企业所在地省、自治区、直辖市食品药品监督管理部门可以对生产企业提交的召回计划进行评估，认为生产企业所采取的措施不能有效消除产品缺陷或者控制产品风险的，应当书面要求其采取提高召回等级、扩大召回范围、缩短召回时间或者改变召回产品的处理方式等更为有效的措施进行处理。医疗器械生产企业应当按照食品药品监督管理部门的要求修改召回计划并组织实施。"},{"i":19,"n":"第十九条","txt":"医疗器械生产企业对上报的召回计划进行变更的，应当及时报所在地省、自治区、直辖市食品药品监督管理部门备案。"},{"i":20,"n":"第二十条","txt":"医疗器械生产企业在实施召回的过程中，应当根据召回计划定期向所在地省、自治区、直辖市食品药品监督管理部门提交召回计划实施情况报告。"},{"i":21,"n":"第二十一条","txt":"医疗器械生产企业对召回医疗器械的处理应当有详细的记录，并向医疗器械生产企业所在地省、自治区、直辖市食品药品监督管理部门报告，记录应当保存至医疗器械注册证失效后5年，第一类医疗器械召回的处理记录应当保存5年。对通过警示、检查、修理、重新标签、修改并完善说明书、软件更新、替换、销毁等方式能够消除产品缺陷的，可以在产品所在地完成上述行为。需要销毁的，应当在食品药品监督管理部门监督下销毁。"},{"i":22,"n":"第二十二条","txt":"医疗器械生产企业应当在召回完成后10个工作日内对召回效果进行评估，并向所在地省、自治区、直辖市食品药品监督管理部门提交医疗器械召回总结评估报告。"},{"i":23,"n":"第二十三条","txt":"医疗器械生产企业所在地省、自治区、直辖市食品药品监督管理部门应当自收到总结评估报告之日起10个工作日内对报告进行审查，并对召回效果进行评估；认为召回尚未有效消除产品缺陷或者控制产品风险的，应当书面要求生产企业重新召回。医疗器械生产企业应当按照食品药品监督管理部门的要求进行重新召回。"},{"i":24,"n":"第二十四条","txt":"食品药品监督管理部门经过调查评估，认为医疗器械生产企业应当召回存在缺陷的医疗器械产品而未主动召回的，应当责令医疗器械生产企业召回医疗器械。 责令召回的决定可以由医疗器械生产企业所在地省、自治区、直辖市食品药品监督管理部门作出，也可以由批准该医疗器械注册或者办理备案的食品药品监督管理部门作出。作出该决定的食品药品监督管理部门，应当在其网站向社会公布责令召回信息。 医疗器械生产企业应当按照食品药品监督管理部门的要求进行召回，并按本办法第十四条第二款的规定向社会公布产品召回信息。 必要时，食品药品监督管理部门可以要求医疗器械生产企业、经营企业和使用单位立即暂停生产、销售和使用，并告知使用者立即暂停使用该缺陷产品。"},{"i":25,"n":"第二十五条","txt":"食品药品监督管理部门作出责令召回决定，应当将责令召回通知书送达医疗器械生产企业，通知书包括以下内容： （一）召回医疗器械的具体情况，包括名称、型号规格、批次等基本信息； （二）实施召回的原因； （三）调查评估结果； （四）召回要求，包括范围和时限等。"},{"i":26,"n":"第二十六条","txt":"医疗器械生产企业收到责令召回通知书后，应当按照本办法第十五条、第十六条的规定通知医疗器械经营企业和使用单位或者告知使用者，制定、提交召回计划，并组织实施。"},{"i":27,"n":"第二十七条","txt":"医疗器械生产企业应当按照本办法第十九条、第二十条、第二十一条、第二十二条的规定向食品药品监督管理部门报告医疗器械召回的相关情况，进行召回医疗器械的后续处理。 食品药品监督管理部门应当按照本办法第二十三条的规定对医疗器械生产企业提交的医疗器械召回总结评估报告进行审查，并对召回效果进行评价，必要时通报同级卫生行政部门。经过审查和评价，认为召回不彻底、尚未有效消除产品缺陷或者控制产品风险的，食品药品监督管理部门应当书面要求医疗器械生产企业重新召回。医疗器械生产企业应当按照食品药品监督管理部门的要求进行重新召回。"},{"i":28,"n":"第二十八条","txt":"医疗器械生产企业因违反法律、法规、规章规定造成上市医疗器械存在缺陷，依法应当给予行政处罚，但该企业已经采取召回措施主动消除或者减轻危害后果的，食品药品监督管理部门依照《中华人民共和国行政处罚法》的规定给予从轻或者减轻处罚；违法行为轻微并及时纠正，没有造成危害后果的，不予处罚。 医疗器械生产企业召回医疗器械的，不免除其依法应当承担的其他法律责任。"},{"i":29,"n":"第二十九条","txt":"医疗器械生产企业违反本办法第二十四条规定，拒绝召回医疗器械的，依据《医疗器械监督管理条例》第六十六条的规定进行处理。"},{"i":30,"n":"第三十条","txt":"医疗器械生产企业有下列情形之一的，予以警告，责令限期改正，并处3万元以下罚款： （一）违反本办法第十四条规定，未按照要求及时向社会发布产品召回信息的； （二）违反本办法第十五条规定，未在规定时间内将召回医疗器械的决定通知到医疗器械经营企业、使用单位或者告知使用者的； （三）违反本办法第十八条、第二十三条、第二十七条第二款规定，未按照食品药品监督管理部门要求采取改正措施或者重新召回医疗器械的； （四）违反本办法第二十一条规定，未对召回医疗器械的处理作详细记录或者未向食品药品监督管理部门报告的。"},{"i":31,"n":"第三十一条","txt":"医疗器械生产企业有下列情形之一的，予以警告，责令限期改正；逾期未改正的，处3万元以下罚款： （一）未按照本办法规定建立医疗器械召回管理制度的； （二）拒绝配合食品药品监督管理部门开展调查的； （三）未按照本办法规定提交医疗器械召回事件报告表、调查评估报告和召回计划、医疗器械召回计划实施情况和总结评估报告的； （四）变更召回计划，未报食品药品监督管理部门备案的。"},{"i":32,"n":"第三十二条","txt":"医疗器械经营企业、使用单位违反本办法第七条第一款规定的，责令停止销售、使用存在缺陷的医疗器械，并处5000元以上3万元以下罚款；造成严重后果的，由原发证部门吊销《医疗器械经营许可证》。"},{"i":33,"n":"第三十三条","txt":"医疗器械经营企业、使用单位拒绝配合有关医疗器械缺陷调查、拒绝协助医疗器械生产企业召回医疗器械的，予以警告，责令限期改正；逾期拒不改正的，处3万元以下罚款。"},{"i":34,"n":"第三十四条","txt":"食品药品监督管理部门及其工作人员不履行医疗器械监督管理职责或者滥用职权、玩忽职守，有下列情形之一的，由监察机关或者任免机关根据情节轻重，对直接负责的主管人员和其他直接责任人员给予批评教育，或者依法给予警告、记过或者记大过的处分；造成严重后果的，给予降级、撤职或者开除的处分： （一）未按规定向社会发布召回信息的； （二）未按规定向相关部门报告或者通报有关召回信息的； （三）应当责令召回而未采取责令召回措施的； （四）违反本办法第二十三条和第二十七条第二款规定，未能督促医疗器械生产企业有效实施召回的。"},{"i":35,"n":"第三十五条","txt":"召回的医疗器械已经植入人体的，医疗器械生产企业应当与医疗机构和患者共同协商，根据召回的不同原因，提出对患者的处理意见和应当采取的预案措施。"},{"i":36,"n":"第三十六条","txt":"召回的医疗器械给患者造成损害的，患者可以向医疗器械生产企业要求赔偿，也可以向医疗器械经营企业、使用单位要求赔偿。患者向医疗器械经营企业、使用单位要求赔偿的，医疗器械经营企业、使用单位赔偿后，有权向负有责任的医疗器械生产企业追偿。"},{"i":37,"n":"第三十七条","txt":"本办法自2017年5月1日起施行。2011年7月1日起施行的《医疗器械召回管理办法（试行）》（中华人民共和国卫生部令第82号）同时废止。"}],"yiliaoqixiebiaozhunguanlibanfa":[{"i":1,"n":"第一条","txt":"为促进科学技术进步，保障医疗器械安全有效，提高健康保障水平，加强医疗器械标准管理，根据《中华人民共和国标准化法》《中华人民共和国标准化法实施条例》和《医疗器械监督管理条例》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称医疗器械标准，是指由国家食品药品监督管理总局依据职责组织制修订，依法定程序发布，在医疗器械研制、生产、经营、使用、监督管理等活动中遵循的统一的技术要求。"},{"i":3,"n":"第三条","txt":"在中华人民共和国境内从事医疗器械标准的制修订、实施及监督管理，应当遵守法律、行政法规及本办法的规定。"},{"i":4,"n":"第四条","txt":"医疗器械标准按照其效力分为强制性标准和推荐性标准。 对保障人体健康和生命安全的技术要求，应当制定为医疗器械强制性国家标准和强制性行业标准。 对满足基础通用、与强制性标准配套、对医疗器械产业起引领作用等需要的技术要求，可以制定为医疗器械推荐性国家标准和推荐性行业标准。"},{"i":5,"n":"第五条","txt":"医疗器械标准按照其规范对象分为基础标准、方法标准、管理标准和产品标准。"},{"i":6,"n":"第六条","txt":"国家食品药品监督管理总局依法编制医疗器械标准规划，建立医疗器械标准管理工作制度，健全医疗器械标准管理体系。"},{"i":7,"n":"第七条","txt":"鼓励企业、社会团体、教育科研机构及个人广泛参与医疗器械标准制修订工作，并对医疗器械标准执行情况进行监督。"},{"i":8,"n":"第八条","txt":"鼓励参与国际标准化活动，参与制定和采用国际医疗器械标准。"},{"i":9,"n":"第九条","txt":"国家食品药品监督管理总局对在医疗器械标准工作中做出显著成绩的组织和个人，按照国家有关规定给予表扬和奖励。"},{"i":10,"n":"第十条","txt":"国家食品药品监督管理总局履行下列职责： （一）组织贯彻医疗器械标准管理相关法律、法规，制定医疗器械标准管理工作制度； （二）组织拟定医疗器械标准规划，编制标准制修订年度工作计划； （三）依法组织医疗器械标准制修订，发布医疗器械行业标准； （四）依法指导、监督医疗器械标准管理工作。"},{"i":11,"n":"第十一条","txt":"国家食品药品监督管理总局医疗器械标准管理中心（以下简称“医疗器械标准管理中心”）履行下列职责： （一）组织开展医疗器械标准体系的研究，拟定医疗器械标准规划草案和标准制修订年度工作计划建议； （二）依法承担医疗器械标准制修订的管理工作； （三）依法承担医疗器械标准化技术委员会的管理工作； （四）承担医疗器械标准宣传、培训的组织工作； （五）组织对标准实施情况进行调研，协调解决标准实施中的重大技术问题； （六）承担医疗器械国际标准化活动和对外合作交流的相关工作； （七）承担医疗器械标准信息化工作，组织医疗器械行业标准出版； （八）承担国家食品药品监督管理总局交办的其他标准管理工作。"},{"i":12,"n":"第十二条","txt":"国家食品药品监督管理总局根据医疗器械标准化工作的需要，经批准依法组建医疗器械标准化技术委员会。 医疗器械标准化技术委员会履行下列职责： （一）开展医疗器械标准研究工作，提出本专业领域标准发展规划、标准体系意见； （二）承担本专业领域医疗器械标准起草、征求意见、技术审查等组织工作，并对标准的技术内容和质量负责； （三）承担本专业领域医疗器械标准的技术指导工作，协助解决标准实施中的技术问题； （四）负责收集、整理本专业领域的医疗器械标准资料，并建立技术档案； （五）负责本专业领域医疗器械标准实施情况的跟踪评价； （六）负责本专业领域医疗器械标准技术内容的咨询和解释； （七）承担本专业领域医疗器械标准的宣传、培训、学术交流和相关国际标准化活动。"},{"i":13,"n":"第十三条","txt":"在现有医疗器械标准化技术委员会不能覆盖的专业技术领域，国家食品药品监督管理总局可以根据监管需要，按程序确定医疗器械标准化技术归口单位。标准化技术归口单位参照医疗器械标准化技术委员会的职责和有关规定开展相应领域医疗器械标准工作。"},{"i":14,"n":"第十四条","txt":"地方食品药品监督管理部门在本行政区域依法履行下列职责： （一）组织贯彻医疗器械标准管理的法律法规； （二）组织、参与医疗器械标准的制修订相关工作； （三）监督医疗器械标准的实施； （四）收集并向上一级食品药品监督管理部门报告标准实施过程中的问题。"},{"i":15,"n":"第十五条","txt":"医疗器械研制机构、生产经营企业和使用单位应当严格执行医疗器械强制性标准。 鼓励医疗器械研制机构、生产经营企业和使用单位积极研制和采用医疗器械推荐性标准，积极参与医疗器械标准制修订工作，及时向有关部门反馈医疗器械标准实施问题和提出改进建议。"},{"i":16,"n":"第十六条","txt":"医疗器械标准制修订程序包括标准立项、起草、征求意见、技术审查、批准发布、复审和废止等。具体规定由国家食品药品监督管理总局制定。 对医疗器械监管急需制修订的标准，可以按照国家食品药品监督管理总局规定的快速程序开展。"},{"i":17,"n":"第十七条","txt":"医疗器械标准管理中心应当根据医疗器械标准规划，向社会公开征集医疗器械标准制定、修订立项提案。 对征集到的立项提案，由相应的医疗器械标准化技术委员会（包括标准化技术归口单位，下同）进行研究后，提出本专业领域标准计划项目立项申请。 涉及两个或者两个以上医疗器械标准化技术委员会的标准计划项目立项提案，应当由医疗器械标准管理中心负责协调，确定牵头医疗器械标准化技术委员会，并由其提出标准计划项目立项申请。"},{"i":18,"n":"第十八条","txt":"医疗器械标准管理中心对医疗器械标准计划项目立项申请，经公开征求意见并组织专家论证后，提出医疗器械标准计划项目，编制标准制修订年度工作计划建议，报国家食品药品监督管理总局审核。 国家食品药品监督管理总局审核通过的医疗器械标准计划项目，应当向社会公示。国家标准计划项目送国务院标准化行政主管部门批准下达；行业标准计划项目由国家食品药品监督管理总局批准下达。"},{"i":19,"n":"第十九条","txt":"医疗器械生产经营企业、使用单位、监管部门、检测机构以及有关教育科研机构、社会团体等，可以向承担医疗器械标准计划项目的医疗器械标准化技术委员会提出起草相关医疗器械标准的申请。医疗器械标准化技术委员会结合标准的技术内容，按照公开、公正、择优的原则，选定起草单位。 起草单位应当广泛调研、深入分析研究，积极借鉴相关国际标准，在对技术内容进行充分验证的基础上起草医疗器械标准，形成医疗器械标准征求意见稿，经医疗器械标准化技术委员会初步审查后，报送医疗器械标准管理中心。"},{"i":20,"n":"第二十条","txt":"医疗器械标准征求意见稿在医疗器械标准管理中心网站向社会公开征求意见，征求意见的期限一般为两个月。承担医疗器械标准计划项目的医疗器械标准化技术委员会对征集到的意见进行汇总后，反馈给标准起草单位，起草单位应当对汇总意见进行认真研究，对征求意见稿进行修改完善，形成医疗器械标准送审稿。"},{"i":21,"n":"第二十一条","txt":"承担医疗器械标准计划项目的医疗器械标准化技术委员会负责组织对医疗器械标准送审稿进行技术审查。审查通过后，将医疗器械标准报批稿、实施建议及相关资料报送医疗器械标准管理中心进行审核。"},{"i":22,"n":"第二十二条","txt":"医疗器械标准管理中心将审核通过后的医疗器械标准报批稿及审核结论等报送国家食品药品监督管理总局审查。审查通过的医疗器械国家标准送国务院标准化行政主管部门批准、发布；审查通过的医疗器械行业标准由国家食品药品监督管理总局确定实施日期和实施要求，以公告形式发布。 医疗器械国家标准、行业标准按照国务院标准化行政主管部门的相关规定进行公开，供公众查阅。"},{"i":23,"n":"第二十三条","txt":"医疗器械标准批准发布后，因个别技术内容影响标准使用、需要进行修改，或者对原标准内容进行少量增减时，应当采用标准修改单方式修改。标准修改单应当按照标准制修订程序制定，由医疗器械标准的原批准部门审查发布。"},{"i":24,"n":"第二十四条","txt":"医疗器械标准化技术委员会应当对已发布实施的医疗器械标准开展复审工作，根据科学技术进步、产业发展以及监管需要对其有效性、适用性和先进性及时组织复审，提出复审结论。复审结论分为继续有效、修订或者废止。复审周期原则上不超过5年。 医疗器械标准复审结论由医疗器械标准管理中心审核通过后，报送国家食品药品监督管理总局审查。医疗器械国家标准复审结论，送国务院标准化行政主管部门批准；医疗器械行业标准复审结论由国家食品药品监督管理总局审查批准，并对复审结论为废止的标准以公告形式发布。"},{"i":25,"n":"第二十五条","txt":"医疗器械企业应当严格按照经注册或者备案的产品技术要求组织生产，保证出厂的医疗器械符合强制性标准以及经注册或者备案的产品技术要求。"},{"i":26,"n":"第二十六条","txt":"医疗器械推荐性标准被法律法规、规范性文件及经注册或者备案的产品技术要求引用的内容应当强制执行。"},{"i":27,"n":"第二十七条","txt":"医疗器械产品技术要求，应当与产品设计特性、预期用途和质量控制水平相适应，并不得低于产品适用的强制性国家标准和强制性行业标准。"},{"i":28,"n":"第二十八条","txt":"食品药品监督管理部门对医疗器械企业实施医疗器械强制性标准以及经注册或者备案的产品技术要求的情况进行监督检查。"},{"i":29,"n":"第二十九条","txt":"任何单位和个人有权向食品药品监督管理部门举报或者反映违反医疗器械强制性标准以及经注册或者备案的产品技术要求的行为。收到举报或者反映的部门，应当及时按规定作出处理。"},{"i":30,"n":"第三十条","txt":"医疗器械标准实行信息化管理，标准立项、发布、实施等信息应当及时向公众公开。"},{"i":31,"n":"第三十一条","txt":"食品药品监督管理部门应当在医疗器械标准发布后，及时组织、指导标准的宣传、培训。"},{"i":32,"n":"第三十二条","txt":"医疗器械标准化技术委员会对标准的实施情况进行跟踪评价。医疗器械标准管理中心根据跟踪评价情况对强制性标准实施情况进行统计分析。"},{"i":33,"n":"第三十三条","txt":"医疗器械国家标准的编号按照国务院标准化行政主管部门的规定编制。医疗器械行业标准的代号由大写汉语拼音字母等构成。强制性行业标准的代号为“YY”，推荐性行业标准的代号为“YY／Ｔ”。 行业标准的编号由行业标准的代号、标准号和标准发布的年号构成。其形式为：YY ××××1-××××2和YY／Ｔ ××××1-××××2。 ××××1为标准号，××××2为标准发布年号。"},{"i":34,"n":"第三十四条","txt":"依法成立的社会团体可以制定发布团体标准。团体标准的管理应当符合国家相关规定。"},{"i":35,"n":"第三十五条","txt":"医疗器械标准样品是医疗器械检验检测中的实物标准，其管理应当符合国家有关规定。"},{"i":36,"n":"第三十六条","txt":"本办法自2017年7月1日起施行。2002年1月4日发布的《医疗器械标准管理办法（试行）》（原国家药品监督管理局令第31号）同时废止。"}],"yiliaoqixiewangluoxiaoshoujianduguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强医疗器械网络销售和医疗器械网络交易服务监督管理，保障公众用械安全，根据《中华人民共和国网络安全法》《医疗器械监督管理条例》《互联网信息服务管理办法》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事医疗器械网络销售、提供医疗器械网络交易服务及其监督管理，应当遵守本办法。"},{"i":3,"n":"第三条","txt":"国家食品药品监督管理总局负责指导全国医疗器械网络销售、医疗器械网络交易服务的监督管理，并组织开展全国医疗器械网络销售和网络交易服务监测。 省级食品药品监督管理部门负责医疗器械网络交易服务的监督管理。 县级以上地方食品药品监督管理部门负责本行政区域内医疗器械网络销售的监督管理。"},{"i":4,"n":"第四条","txt":"从事医疗器械网络销售的企业、医疗器械网络交易服务第三方平台提供者应当遵守医疗器械法规、规章和规范，建立健全管理制度，依法诚信经营，保证医疗器械质量安全。 从事医疗器械网络销售的企业，是指通过网络销售医疗器械的医疗器械上市许可持有人（即医疗器械注册人或者备案人，以下简称持有人）和医疗器械生产经营企业。 医疗器械网络交易服务第三方平台提供者，是指在医疗器械网络交易中仅提供网页空间、虚拟交易场所、交易规则、交易撮合、电子订单等交易服务，供交易双方或者多方开展交易活动，不直接参与医疗器械销售的企业。"},{"i":5,"n":"第五条","txt":"从事医疗器械网络销售的企业、医疗器械网络交易服务第三方平台提供者应当采取技术措施，保障医疗器械网络销售数据和资料的真实、完整、可追溯。"},{"i":6,"n":"第六条","txt":"从事医疗器械网络销售的企业、医疗器械网络交易服务第三方平台提供者应当积极配合食品药品监督管理部门开展网络监测、抽样检验、现场检查等监督管理，按照食品药品监督管理部门的要求存储数据，提供信息查询、数据提取等相关支持。"},{"i":7,"n":"第七条","txt":"从事医疗器械网络销售的企业应当是依法取得医疗器械生产许可、经营许可或者办理备案的医疗器械生产经营企业。法律法规规定不需要办理许可或者备案的除外。 持有人通过网络销售其医疗器械，医疗器械生产企业受持有人委托通过网络销售受托生产的医疗器械，不需要办理经营许可或者备案，其销售条件应当符合《医疗器械监督管理条例》和本办法的要求。 持有人委托开展医疗器械网络销售的，应当评估确认受托方的合法资质、销售条件、技术水平和质量管理能力，对网络销售过程和质量控制进行指导和监督，对网络销售的医疗器械质量负责。"},{"i":8,"n":"第八条","txt":"从事医疗器械网络销售的企业，应当填写医疗器械网络销售信息表，将企业名称、法定代表人或者主要负责人、网站名称、网络客户端应用程序名、网站域名、网站IP地址、电信业务经营许可证或者非经营性互联网信息服务备案编号、医疗器械生产经营许可证件或者备案凭证编号等信息事先向所在地设区的市级食品药品监督管理部门备案。相关信息发生变化的，应当及时变更备案。"},{"i":9,"n":"第九条","txt":"从事医疗器械网络销售的企业，应当通过自建网站或者医疗器械网络交易服务第三方平台开展医疗器械网络销售活动。 通过自建网站开展医疗器械网络销售的企业，应当依法取得《互联网药品信息服务资格证书》，并具备与其规模相适应的办公场所以及数据备份、故障恢复等技术条件。"},{"i":10,"n":"第十条","txt":"从事医疗器械网络销售的企业，应当在其主页面显著位置展示其医疗器械生产经营许可证件或者备案凭证，产品页面应当展示该产品的医疗器械注册证或者备案凭证。相关展示信息应当画面清晰，容易辨识。其中，医疗器械生产经营许可证件或者备案凭证、医疗器械注册证或者备案凭证的编号还应当以文本形式展示。相关信息发生变更的，应当及时更新展示内容。"},{"i":11,"n":"第十一条","txt":"从事医疗器械网络销售的企业在网上发布的医疗器械名称、型号、规格、结构及组成、适用范围、医疗器械注册证编号或者备案凭证编号、注册人或者备案人信息、生产许可证或者备案凭证编号、产品技术要求编号、禁忌症等信息，应当与经注册或者备案的相关内容保持一致。"},{"i":12,"n":"第十二条","txt":"从事医疗器械网络销售的企业应当记录医疗器械销售信息，记录应当保存至医疗器械有效期后2年；无有效期的，保存时间不得少于5年；植入类医疗器械的销售信息应当永久保存。相关记录应当真实、完整、可追溯。"},{"i":13,"n":"第十三条","txt":"从事医疗器械网络销售的企业，经营范围不得超出其生产经营许可或者备案的范围。 医疗器械批发企业从事医疗器械网络销售，应当销售给具有资质的医疗器械经营企业或者使用单位。 医疗器械零售企业从事医疗器械网络销售，应当销售给消费者。销售给消费者个人的医疗器械，应当是可以由消费者个人自行使用的，其说明书应当符合医疗器械说明书和标签管理相关规定，标注安全使用的特别说明。"},{"i":14,"n":"第十四条","txt":"从事医疗器械网络销售的企业，应当按照医疗器械标签和说明书标明的条件贮存和运输医疗器械。委托其他单位贮存和运输医疗器械的，应当对被委托方贮存和运输医疗器械的质量保障能力进行考核评估，明确贮存和运输过程中的质量安全责任，确保贮存和运输过程中的质量安全。"},{"i":15,"n":"第十五条","txt":"医疗器械网络交易服务第三方平台提供者应当依法取得《互联网药品信息服务资格证书》，具备与其规模相适应的办公场所以及数据备份、故障恢复等技术条件，设置专门的医疗器械网络质量安全管理机构或者配备医疗器械质量安全管理人员。"},{"i":16,"n":"第十六条","txt":"医疗器械网络交易服务第三方平台提供者应当向所在地省级食品药品监督管理部门备案，填写医疗器械网络交易服务第三方平台备案表，并提交以下材料： （一）营业执照原件、复印件； （二）法定代表人或者主要负责人、医疗器械质量安全管理人身份证明原件、复印件； （三）组织机构与部门设置说明； （四）办公场所地理位置图、房屋产权证明文件或者租赁协议（附房屋产权证明文件）原件、复印件； （五）电信业务经营许可证原件、复印件或者非经营性互联网信息服务备案说明； （六）《互联网药品信息服务资格证书》原件、复印件； （七）医疗器械网络交易服务质量管理制度等文件目录； （八）网站或者网络客户端应用程序基本情况介绍和功能说明； （九）其他相关证明材料。"},{"i":17,"n":"第十七条","txt":"省级食品药品监督管理部门应当当场对企业提交材料的完整性进行核对，符合规定的予以备案，发给医疗器械网络交易服务第三方平台备案凭证；提交资料不齐全或者不符合法定情形的，应当一次性告知需要补充材料的事项。 省级食品药品监督管理部门应当在备案后7个工作日内向社会公开相关备案信息。备案信息包括企业名称、法定代表人或者主要负责人、网站名称、网络客户端应用程序名、网站域名、网站IP地址、电信业务经营许可证或者非经营性互联网信息服务备案编号、医疗器械网络交易服务第三方平台备案凭证编号等。 省级食品药品监督管理部门应当在医疗器械网络交易服务第三方平台提供者备案后3个月内，对医疗器械网络交易服务第三方平台开展现场检查。"},{"i":18,"n":"第十八条","txt":"医疗器械网络交易服务第三方平台提供者名称、法定代表人或者主要负责人、网站名称、网络客户端应用程序名、网站域名、网站IP地址、电信业务经营许可证或者非经营性互联网信息服务备案编号等备案信息发生变化的，应当及时变更备案。"},{"i":19,"n":"第十九条","txt":"医疗器械网络交易服务第三方平台提供者，应当在其网站主页面显著位置标注医疗器械网络交易服务第三方平台备案凭证的编号。"},{"i":20,"n":"第二十条","txt":"医疗器械网络交易服务第三方平台提供者应当建立包括入驻平台的企业核实登记、质量安全监测、交易安全保障、网络销售违法行为制止及报告、严重违法行为平台服务停止、安全投诉举报处理、消费者权益保护、质量安全信息公告等管理制度。"},{"i":21,"n":"第二十一条","txt":"医疗器械网络交易服务第三方平台提供者应当对申请入驻平台的企业提供的医疗器械生产经营许可证件或者备案凭证、医疗器械注册证或者备案凭证、企业营业执照等材料进行核实，建立档案并及时更新，保证入驻平台的企业许可证件或者备案凭证所载明的生产经营场所等许可或者备案信息真实。 医疗器械网络交易服务第三方平台提供者应当与入驻平台的企业签订入驻协议，并在协议中明确双方义务及违约处置措施等相关内容。"},{"i":22,"n":"第二十二条","txt":"医疗器械网络交易服务第三方平台提供者应当记录在其平台上开展的医疗器械交易信息，记录应当保存至医疗器械有效期后2年；无有效期的，保存时间不得少于5年；植入类医疗器械交易信息应当永久保存。相关记录应当真实、完整、可追溯。"},{"i":23,"n":"第二十三条","txt":"医疗器械网络交易服务第三方平台提供者应当对平台上的医疗器械销售行为及信息进行监测，发现入驻网络交易服务第三方平台的企业存在超范围经营、发布虚假信息、夸大宣传等违法违规行为、无法取得联系或者存在其他严重安全隐患的，应当立即对其停止网络交易服务，并保存有关记录，向所在地省级食品药品监督管理部门报告。 发现入驻网络交易服务第三方平台的企业被食品药品监督管理部门责令停产停业、吊销许可证件等处罚，或者平台交易的产品被食品药品监督管理部门暂停销售或者停止销售的，应当立即停止提供相关网络交易服务。"},{"i":24,"n":"第二十四条","txt":"医疗器械网络交易服务第三方平台提供者应当在网站醒目位置及时发布产品质量安全隐患等相关信息。"},{"i":25,"n":"第二十五条","txt":"食品药品监督管理部门依照法律、法规、规章的规定，依职权对从事医疗器械网络销售的企业和医疗器械网络交易服务第三方平台实施监督检查和抽样检验。"},{"i":26,"n":"第二十六条","txt":"对从事医疗器械网络销售的企业违法行为的查处，由其所在地县级以上地方食品药品监督管理部门管辖。 未经许可或者备案从事医疗器械网络销售，能确定违法销售企业地址的，由违法销售企业所在地县级以上地方食品药品监督管理部门管辖；不能确定违法销售企业所在地的，由违法行为发生地或者违法行为结果地的县级以上地方食品药品监督管理部门管辖。通过医疗器械网络交易服务第三方平台销售的，由医疗器械网络交易服务第三方平台提供者所在地省级食品药品监督管理部门管辖；经调查后能够确定管辖地的，及时移送有管辖权的食品药品监督管理部门。 对医疗器械网络交易服务第三方平台提供者违法行为的查处，由其所在地省级食品药品监督管理部门管辖。 网络销售的医疗器械发生重大质量事故或者造成其他严重危害后果的，可以由违法企业所在地、违法行为发生地或者违法行为结果地省级食品药品监督管理部门管辖；后果特别严重的，省级食品药品监督管理部门可以报请国"},{"i":27,"n":"第二十七条","txt":"国家食品药品监督管理总局组织建立国家医疗器械网络交易监测平台，开展全国医疗器械网络销售和网络交易监测与处置，监测情况定期通报省级食品药品监督管理部门。对监测发现的涉嫌违法违规信息，及时转送相关省级食品药品监督管理部门。省级食品药品监督管理部门应当及时组织处理。"},{"i":28,"n":"第二十八条","txt":"省级食品药品监督管理部门自行建立的医疗器械网络销售监测平台，应当与国家医疗器械网络交易监测平台实现数据对接。"},{"i":29,"n":"第二十九条","txt":"食品药品监督管理部门开展医疗器械网络销售日常监督管理，或者对涉嫌违法违规的医疗器械网络销售行为进行查处时，有权采取下列措施： （一）进入企业医疗器械经营场所、办公场所和服务器所在地等实施现场检查； （二）对网络销售的医疗器械进行抽样检验； （三）询问有关人员，调查企业从事医疗器械网络销售行为的相关情况； （四）查阅、复制企业的交易数据、合同、票据、账簿以及其他相关资料； （五）调取网络销售的技术监测、记录资料； （六）依法查封扣押数据存储介质等； （七）法律、法规规定可以采取的其他措施。"},{"i":30,"n":"第三十条","txt":"对网络销售医疗器械的抽样检验，按照医疗器械质量监督抽查检验相关管理规定实施。 检验结果不符合医疗器械质量安全标准的，食品药品监督管理部门收到检验报告后，应当及时对相关生产经营企业开展监督检查，采取控制措施，及时发布质量公告，对违法行为依法查处。"},{"i":31,"n":"第三十一条","txt":"食品药品监督管理部门对医疗器械网络销售的技术监测记录、信息追溯资料等，可以作为认定医疗器械网络销售违法事实的依据。"},{"i":32,"n":"第三十二条","txt":"从事医疗器械网络销售的企业实际情况与备案信息不符且无法取得联系的，经所在地设区的市级食品药品监督管理部门公示后，依法注销其《医疗器械经营许可证》或者在第二类医疗器械经营备案信息中予以标注，并向社会公告。相关网站由省级食品药品监督管理部门通报同级通信主管部门。 医疗器械网络交易服务第三方平台提供者实际情况与备案信息不符且无法取得联系的，经原备案所在地省级食品药品监督管理部门公示后，在其备案信息中予以标注，向社会公告；备案时提供虚假资料的，由省级食品药品监督管理部门向社会公告备案单位。其网站由省级食品药品监督管理部门通报同级通信主管部门。"},{"i":33,"n":"第三十三条","txt":"食品药品监督管理部门在检查中发现从事医疗器械网络销售的企业或者医疗器械网络交易服务第三方平台未按规定建立并执行相关质量管理制度，且存在医疗器械质量安全隐患的，食品药品监督管理部门可以责令其暂停网络销售或者暂停提供相关网络交易服务。 恢复网络销售或者恢复提供相关网络交易服务的，从事医疗器械网络销售的企业或者医疗器械网络交易服务第三方平台提供者应当向原作出处理决定的食品药品监督管理部门提出申请，经食品药品监督管理部门检查通过后方可恢复。"},{"i":34,"n":"第三十四条","txt":"从事医疗器械网络销售的企业、医疗器械网络交易服务第三方平台提供者，有下列情形之一的，食品药品监督管理部门可以依职责对其法定代表人或者主要负责人进行约谈： （一）发生医疗器械质量安全问题，可能引发医疗器械质量安全风险的； （二）未及时妥善处理投诉举报的医疗器械质量问题，可能存在医疗器械质量安全隐患的； （三）未及时采取有效措施排查、消除医疗器械质量安全隐患，未落实医疗器械质量安全责任的； （四）需要进行约谈的其他情形。 约谈不影响食品药品监督管理部门依法对其进行行政处理，约谈情况及后续处理情况可以向社会公开。 被约谈企业无正当理由未按照要求落实整改的，省级食品药品监督管理部门、所在地设区的市级食品药品监督管理部门应当依职责增加监督检查频次。"},{"i":35,"n":"第三十五条","txt":"有下列情形之一的，食品药品监督管理部门可以将从事医疗器械网络销售的企业、医疗器械网络交易服务第三方平台提供者及其法定代表人或者主要负责人列入失信企业和失信人员名单，并向社会公开： （一）拒不执行暂停网络销售或者暂停提供相关网络交易服务决定的； （二）企业被约谈后拒不按照要求整改的。"},{"i":36,"n":"第三十六条","txt":"县级以上地方食品药品监督管理部门应当定期汇总分析本行政区域医疗器械网络销售监督管理情况，报告上一级食品药品监督管理部门，并依法向社会公开。 省级食品药品监督管理部门应当每年汇总分析医疗器械网络销售和网络交易服务第三方平台监督管理情况，报告国家食品药品监督管理总局，并依法向社会公开。"},{"i":37,"n":"第三十七条","txt":"从事医疗器械网络销售的企业、医疗器械网络交易服务第三方平台提供者违反法律法规有关规定从事销售或者交易服务，法律法规已有规定的，从其规定。构成犯罪的，移送公安机关处理。"},{"i":38,"n":"第三十八条","txt":"违反本办法规定，未取得医疗器械经营许可从事网络第三类医疗器械销售的，依照《医疗器械监督管理条例》第六十三条的规定予以处罚；未取得第二类医疗器械经营备案凭证从事网络第二类医疗器械销售的，依照《医疗器械监督管理条例》第六十五条的规定予以处罚。"},{"i":39,"n":"第三十九条","txt":"从事医疗器械网络销售的企业未按照本办法规定备案的，由县级以上地方食品药品监督管理部门责令限期改正，给予警告；拒不改正的，向社会公告，处1万元以下罚款。"},{"i":40,"n":"第四十条","txt":"有下列情形之一的，由县级以上地方食品药品监督管理部门责令改正，给予警告；拒不改正的，处5000元以上1万元以下罚款： （一）从事医疗器械网络销售的企业未按照本办法要求展示医疗器械生产经营许可证或者备案凭证、医疗器械注册证或者备案凭证的； （二）医疗器械网络交易服务第三方平台提供者未按照本办法要求展示医疗器械网络交易服务第三方平台备案凭证编号的。"},{"i":41,"n":"第四十一条","txt":"有下列情形之一的，由县级以上地方食品药品监督管理部门责令改正，给予警告；拒不改正的，处5000元以上2万元以下罚款： （一）从事医疗器械网络销售的企业备案信息发生变化，未按规定变更的； （二）从事医疗器械网络销售的企业未按规定建立并执行质量管理制度的； （三）医疗器械网络交易服务第三方平台提供者备案事项发生变化未按规定办理变更的； （四）医疗器械网络交易服务第三方平台提供者未按规定要求设置与其规模相适应的质量安全管理机构或者配备质量安全管理人员的； （五）医疗器械网络交易服务第三方平台提供者未按规定建立并执行质量管理制度的。"},{"i":42,"n":"第四十二条","txt":"医疗器械网络交易服务第三方平台提供者未按本办法规定备案的，由省级食品药品监督管理部门责令限期改正；拒不改正的，向社会公告，处3万元以下罚款。"},{"i":43,"n":"第四十三条","txt":"有下列情形之一的，由县级以上地方食品药品监督管理部门责令改正，给予警告；拒不改正的，处1万元以上3万元以下罚款： （一）从事医疗器械网络销售的企业、医疗器械网络交易服务第三方平台条件发生变化，不再满足规定要求的； （二）从事医疗器械网络销售的企业、医疗器械网络交易服务第三方平台提供者不配合食品药品监督管理部门的监督检查，或者拒绝、隐瞒、不如实提供相关材料和数据的。"},{"i":44,"n":"第四十四条","txt":"有下列情形之一的，由县级以上地方食品药品监督管理部门责令改正，处1万元以上3万元以下罚款： （一）从事医疗器械网络销售的企业超出经营范围销售的； （二）医疗器械批发企业销售给不具有资质的经营企业、使用单位的。 医疗器械零售企业将非消费者自行使用的医疗器械销售给消费者个人的，依照前款第一项规定予以处罚。"},{"i":45,"n":"第四十五条","txt":"从事医疗器械网络销售的企业未按照医疗器械说明书和标签标示要求运输、贮存医疗器械的，依照《医疗器械监督管理条例》第六十七条的规定予以处罚。"},{"i":46,"n":"第四十六条","txt":"负责监管医疗器械网络销售的食品药品监督管理部门工作人员不履行职责或者滥用职权、玩忽职守、徇私舞弊的，依法追究行政责任；构成犯罪的，移送司法机关追究刑事责任。"},{"i":47,"n":"第四十七条","txt":"医疗器械网络交易服务第三方平台提供者提供的医疗器械产品或者服务造成他人人身、财产损失的，根据相关法律法规的规定承担民事责任。"},{"i":48,"n":"第四十八条","txt":"医疗器械网络交易服务第三方平台备案凭证的格式由国家食品药品监督管理总局统一制定。 医疗器械网络交易服务第三方平台备案凭证由省级食品药品监督管理部门印制。 医疗器械网络交易服务第三方平台备案凭证编号的编排方式为：（X）网械平台备字〔XXXX〕第XXXXX号。其中： 第一位X代表备案部门所在地省、自治区、直辖市的简称； 第二到五位X代表4位数备案年份； 第六到十位X代表5位数备案流水号。"},{"i":49,"n":"第四十九条","txt":"医疗器械网络信息服务按照《互联网药品信息服务管理办法》执行。"},{"i":50,"n":"第五十条","txt":"本办法自2018年3月1日起施行。"}],"yiliaoqixieshuomingshuhebiaoqianguanliguiding":[{"i":1,"n":"第一条","txt":"为规范医疗器械说明书和标签，保证医疗器械使用的安全，根据《医疗器械监督管理条例》，制定本规定。"},{"i":2,"n":"第二条","txt":"凡在中华人民共和国境内销售、使用的医疗器械，应当按照本规定要求附有说明书和标签。"},{"i":3,"n":"第三条","txt":"医疗器械说明书是指由医疗器械注册人或者备案人制作，随产品提供给用户，涵盖该产品安全有效的基本信息，用以指导正确安装、调试、操作、使用、维护、保养的技术文件。 医疗器械标签是指在医疗器械或者其包装上附有的用于识别产品特征和标明安全警示等信息的文字说明及图形、符号。"},{"i":4,"n":"第四条","txt":"医疗器械说明书和标签的内容应当科学、真实、完整、准确，并与产品特性相一致。 医疗器械说明书和标签的内容应当与经注册或者备案的相关内容一致。 医疗器械标签的内容应当与说明书有关内容相符合。"},{"i":5,"n":"第五条","txt":"医疗器械说明书和标签对疾病名称、专业名词、诊断治疗过程和结果的表述，应当采用国家统一发布或者规范的专用词汇，度量衡单位应当符合国家相关标准的规定。"},{"i":6,"n":"第六条","txt":"医疗器械说明书和标签中使用的符号或者识别颜色应当符合国家相关标准的规定；无相关标准规定的，该符号及识别颜色应当在说明书中描述。"},{"i":7,"n":"第七条","txt":"医疗器械最小销售单元应当附有说明书。 医疗器械的使用者应当按照说明书使用医疗器械。"},{"i":8,"n":"第八条","txt":"医疗器械的产品名称应当使用通用名称，通用名称应当符合国家食品药品监督管理总局制定的医疗器械命名规则。第二类、第三类医疗器械的产品名称应当与医疗器械注册证中的产品名称一致。 产品名称应当清晰地标明在说明书和标签的显著位置。"},{"i":9,"n":"第九条","txt":"医疗器械说明书和标签文字内容应当使用中文，中文的使用应当符合国家通用的语言文字规范。医疗器械说明书和标签可以附加其他文种，但应当以中文表述为准。 医疗器械说明书和标签中的文字、符号、表格、数字、图形等应当准确、清晰、规范。"},{"i":10,"n":"第十条","txt":"医疗器械说明书一般应当包括以下内容： （一）产品名称、型号、规格； （二）注册人或者备案人的名称、住所、联系方式及售后服务单位，进口医疗器械还应当载明代理人的名称、住所及联系方式； （三）生产企业的名称、住所、生产地址、联系方式及生产许可证编号或者生产备案凭证编号，委托生产的还应当标注受托企业的名称、住所、生产地址、生产许可证编号或者生产备案凭证编号； （四）医疗器械注册证编号或者备案凭证编号； （五）产品技术要求的编号； （六）产品性能、主要结构组成或者成分、适用范围； （七）禁忌症、注意事项、警示以及提示的内容； （八）安装和使用说明或者图示，由消费者个人自行使用的医疗器械还应当具有安全使用的特别说明； （九）产品维护和保养方法，特殊储存、运输条件、方法； （十）生产日期，使用期限或者失效日期； （十一）配件清单，包括配件、附属品、损耗品更换周期以及更换方法的说明等； （十二）医疗"},{"i":11,"n":"第十一条","txt":"医疗器械说明书中有关注意事项、警示以及提示性内容主要包括： （一）产品使用的对象； （二）潜在的安全危害及使用限制； （三）产品在正确使用过程中出现意外时，对操作者、使用者的保护措施以及应当采取的应急和纠正措施； （四）必要的监测、评估、控制手段； （五）一次性使用产品应当注明“一次性使用”字样或者符号，已灭菌产品应当注明灭菌方式以及灭菌包装损坏后的处理方法，使用前需要消毒或者灭菌的应当说明消毒或者灭菌的方法； （六）产品需要同其他医疗器械一起安装或者联合使用时，应当注明联合使用器械的要求、使用方法、注意事项； （七）在使用过程中，与其他产品可能产生的相互干扰及其可能出现的危害； （八）产品使用中可能带来的不良事件或者产品成分中含有的可能引起副作用的成分或者辅料； （九）医疗器械废弃处理时应当注意的事项，产品使用后需要处理的，应当注明相应的处理方法； （十）根据产品特性，应当提示操作者"},{"i":12,"n":"第十二条","txt":"重复使用的医疗器械应当在说明书中明确重复使用的处理过程，包括清洁、消毒、包装及灭菌的方法和重复使用的次数或者其他限制。"},{"i":13,"n":"第十三条","txt":"医疗器械标签一般应当包括以下内容： （一）产品名称、型号、规格； （二）注册人或者备案人的名称、住所、联系方式，进口医疗器械还应当载明代理人的名称、住所及联系方式； （三）医疗器械注册证编号或者备案凭证编号； （四）生产企业的名称、住所、生产地址、联系方式及生产许可证编号或者生产备案凭证编号，委托生产的还应当标注受托企业的名称、住所、生产地址、生产许可证编号或者生产备案凭证编号； （五）生产日期，使用期限或者失效日期； （六）电源连接条件、输入功率； （七）根据产品特性应当标注的图形、符号以及其他相关内容； （八）必要的警示、注意事项； （九）特殊储存、操作条件或者说明； （十）使用中对环境有破坏或者负面影响的医疗器械，其标签应当包含警示标志或者中文警示说明； （十一）带放射或者辐射的医疗器械，其标签应当包含警示标志或者中文警示说明。 医疗器械标签因位置或者大小受限而无法全部标明上述内"},{"i":14,"n":"第十四条","txt":"医疗器械说明书和标签不得有下列内容： （一）含有“疗效最佳”、“保证治愈”、“包治”、“根治”、“即刻见效”、“完全无毒副作用”等表示功效的断言或者保证的； （二）含有“最高技术”、“最科学”、“最先进”、“最佳”等绝对化语言和表示的； （三）说明治愈率或者有效率的； （四）与其他企业产品的功效和安全性相比较的； （五）含有“保险公司保险”、“无效退款”等承诺性语言的； （六）利用任何单位或者个人的名义、形象作证明或者推荐的； （七）含有误导性说明，使人感到已经患某种疾病，或者使人误解不使用该医疗器械会患某种疾病或者加重病情的表述，以及其他虚假、夸大、误导性的内容； （八）法律、法规规定禁止的其他内容。"},{"i":15,"n":"第十五条","txt":"医疗器械说明书应当由注册申请人或者备案人在医疗器械注册或者备案时，提交食品药品监督管理部门审查或者备案，提交的说明书内容应当与其他注册或者备案资料相符合。"},{"i":16,"n":"第十六条","txt":"经食品药品监督管理部门注册审查的医疗器械说明书的内容不得擅自更改。 已注册的医疗器械发生注册变更的，申请人应当在取得变更文件后，依据变更文件自行修改说明书和标签。 说明书的其他内容发生变化的，应当向医疗器械注册的审批部门书面告知，并提交说明书更改情况对比说明等相关文件。审批部门自收到书面告知之日起20个工作日内未发出不予同意通知件的，说明书更改生效。"},{"i":17,"n":"第十七条","txt":"已备案的医疗器械，备案信息表中登载内容、备案产品技术要求以及说明书其他内容发生变化的，备案人自行修改说明书和标签的相关内容。"},{"i":18,"n":"第十八条","txt":"说明书和标签不符合本规定要求的，由县级以上食品药品监督管理部门按照《医疗器械监督管理条例》第六十七条的规定予以处罚。"},{"i":19,"n":"第十九条","txt":"本规定自2014年10月1日起施行。2004年7月8日公布的《医疗器械说明书、标签和包装标识管理规定》（原国家食品药品监督管理局令第10号）同时废止。"}],"yiliaoqixietongyongmingchengmingmingguize":[{"i":1,"n":"第一条","txt":"为加强医疗器械监督管理，保证医疗器械通用名称命名科学、规范，根据《医疗器械监督管理条例》，制定本规则。"},{"i":2,"n":"第二条","txt":"凡在中华人民共和国境内销售、使用的医疗器械应当使用通用名称，通用名称的命名应当符合本规则。"},{"i":3,"n":"第三条","txt":"医疗器械通用名称应当符合国家有关法律、法规的规定，科学、明确，与产品的真实属性相一致。"},{"i":4,"n":"第四条","txt":"医疗器械通用名称应当使用中文，符合国家语言文字规范。"},{"i":5,"n":"第五条","txt":"具有相同或者相似的预期目的、共同技术的同品种医疗器械应当使用相同的通用名称。"},{"i":6,"n":"第六条","txt":"医疗器械通用名称由一个核心词和一般不超过三个特征词组成。 核心词是对具有相同或者相似的技术原理、结构组成或者预期目的的医疗器械的概括表述。 特征词是对医疗器械使用部位、结构特点、技术特点或者材料组成等特定属性的描述。使用部位是指产品在人体的作用部位，可以是人体的系统、器官、组织、细胞等。结构特点是对产品特定结构、外观形态的描述。技术特点是对产品特殊作用原理、机理或者特殊性能的说明或者限定。材料组成是对产品的主要材料或者主要成分的描述。"},{"i":7,"n":"第七条","txt":"医疗器械通用名称除应当符合本规则第六条的规定外，不得含有下列内容： （一）型号、规格； （二）图形、符号等标志； （三）人名、企业名称、注册商标或者其他类似名称； （四）“最佳”、“唯一”、“精确”、“速效”等绝对化、排他性的词语，或者表示产品功效的断言或者保证； （五）说明有效率、治愈率的用语； （六）未经科学证明或者临床评价证明，或者虚无、假设的概念性名称； （七）明示或者暗示包治百病，夸大适用范围，或者其他具有误导性、欺骗性的内容； （八）“美容”、“保健”等宣传性词语； （九）有关法律、法规禁止的其他内容。"},{"i":8,"n":"第八条","txt":"根据《中华人民共和国商标法》第十一条第一款的规定，医疗器械通用名称不得作为商标注册。"},{"i":9,"n":"第九条","txt":"按照医疗器械管理的体外诊断试剂的命名依照《体外诊断试剂注册管理办法》（国家食品药品监督管理总局令第5号）的有关规定执行。"},{"i":10,"n":"第十条","txt":"本规则自2016年4月1日起施行。"}],"yiliaojigouzhijizhuceguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强医疗机构制剂的管理，规范医疗机构制剂的申报与审批，根据《中华人民共和国药品管理法》（以下简称《药品管理法》）及《中华人民共和国药品管理法实施条例》（以下简称《药品管理法实施条例》），制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内申请医疗机构制剂的配制、调剂使用，以及进行相关的审批、检验和监督管理，适用本办法。"},{"i":3,"n":"第三条","txt":"医疗机构制剂，是指医疗机构根据本单位临床需要经批准而配制、自用的固定处方制剂。 医疗机构配制的制剂，应当是市场上没有供应的品种。"},{"i":4,"n":"第四条","txt":"国家食品药品监督管理局负责全国医疗机构制剂的监督管理工作。 省、自治区、直辖市（食品）药品监督管理部门负责本辖区医疗机构制剂的审批和监督管理工作。"},{"i":5,"n":"第五条","txt":"医疗机构制剂的申请人，应当是持有《医疗机构执业许可证》并取得《医疗机构制剂许可证》的医疗机构。 未取得《医疗机构制剂许可证》或者《医疗机构制剂许可证》无相应制剂剂型的“医院”类别的医疗机构可以申请医疗机构中药制剂，但是必须同时提出委托配制制剂的申请。接受委托配制的单位应当是取得《医疗机构制剂许可证》的医疗机构或者取得《药品生产质量管理规范》认证证书的药品生产企业。委托配制的制剂剂型应当与受托方持有的《医疗机构制剂许可证》或者《药品生产质量管理规范》认证证书所载明的范围一致。"},{"i":6,"n":"第六条","txt":"医疗机构制剂只能在本医疗机构内凭执业医师或者执业助理医师的处方使用，并与《医疗机构执业许可证》所载明的诊疗范围一致。"},{"i":7,"n":"第七条","txt":"申请医疗机构制剂，应当进行相应的临床前研究，包括处方筛选、配制工艺、质量指标、药理、毒理学研究等。"},{"i":8,"n":"第八条","txt":"申请医疗机构制剂注册所报送的资料应当真实、完整、规范。"},{"i":9,"n":"第九条","txt":"申请制剂所用的化学原料药及实施批准文号管理的中药材、中药饮片必须具有药品批准文号，并符合法定的药品标准。"},{"i":10,"n":"第十条","txt":"申请人应当对其申请注册的制剂或者使用的处方、工艺、用途等，提供申请人或者他人在中国的专利及其权属状态说明；他人在中国存在专利的，申请人应当提交对他人的专利不构成侵权的声明。"},{"i":11,"n":"第十一条","txt":"医疗机构制剂的名称，应当按照国家食品药品监督管理局颁布的药品命名原则命名，不得使用商品名称。"},{"i":12,"n":"第十二条","txt":"医疗机构配制制剂使用的辅料和直接接触制剂的包装材料、容器等，应当符合国家食品药品监督管理局有关辅料、直接接触药品的包装材料和容器的管理规定。"},{"i":13,"n":"第十三条","txt":"医疗机构制剂的说明书和包装标签由省、自治区、直辖市（食品）药品监督管理部门根据申请人申报的资料，在批准制剂申请时一并予以核准。 医疗机构制剂的说明书和包装标签应当按照国家食品药品监督管理局有关药品说明书和包装标签的管理规定印制，其文字、图案不得超出核准的内容，并需标注“本制剂仅限本医疗机构使用”字样。"},{"i":14,"n":"第十四条","txt":"有下列情形之一的，不得作为医疗机构制剂申报： （一）市场上已有供应的品种； （二）含有未经国家食品药品监督管理局批准的活性成份的品种； （三）除变态反应原外的生物制品； （四）中药注射剂； （五）中药、化学药组成的复方制剂； （六）麻醉药品、精神药品、医疗用毒性药品、放射性药品； （七）其他不符合国家有关规定的制剂。"},{"i":15,"n":"第十五条","txt":"申请配制医疗机构制剂，申请人应当填写《医疗机构制剂注册申请表》，向所在地省、自治区、直辖市（食品）药品监督管理部门或者其委托的设区的市级（食品）药品监督管理机构提出申请，报送有关资料和制剂实样。"},{"i":16,"n":"第十六条","txt":"收到申请的省、自治区、直辖市（食品）药品监督管理部门或者其委托的设区的市级（食品）药品监督管理机构对申报资料进行形式审查，符合要求的予以受理；不符合要求的，应当自收到申请材料之日起5日内书面通知申请人并说明理由，逾期未通知的自收到材料之日起即为受理。"},{"i":17,"n":"第十七条","txt":"省、自治区、直辖市（食品）药品监督管理部门或者其委托的设区的市级（食品）药品监督管理机构应当在申请受理后10日内组织现场考察，抽取连续3批检验用样品，通知指定的药品检验所进行样品检验和质量标准技术复核。受委托的设区的市级（食品）药品监督管理机构应当在完成上述工作后将审查意见、考察报告及申报资料报送省、自治区、直辖市（食品）药品监督管理部门，并通知申请人。"},{"i":18,"n":"第十八条","txt":"接到检验通知的药品检验所应当在40日内完成样品检验和质量标准技术复核，出具检验报告书及标准复核意见，报送省、自治区、直辖市（食品）药品监督管理部门并抄送通知其检验的（食品）药品监督管理机构和申请人。"},{"i":19,"n":"第十九条","txt":"省、自治区、直辖市（食品）药品监督管理部门应当在收到全部资料后40日内组织完成技术审评，符合规定的，发给《医疗机构制剂临床研究批件》。 申请配制的化学制剂已有同品种获得制剂批准文号的，可以免于进行临床研究。"},{"i":20,"n":"第二十条","txt":"临床研究用的制剂，应当按照《医疗机构制剂配制质量管理规范》或者《药品生产质量管理规范》的要求配制，配制的制剂应当符合经省、自治区、直辖市（食品）药品监督管理部门审定的质量标准。"},{"i":21,"n":"第二十一条","txt":"医疗机构制剂的临床研究，应当在获得《医疗机构制剂临床研究批件》后，取得受试者知情同意书以及伦理委员会的同意，按照《药物临床试验质量管理规范》的要求实施。"},{"i":22,"n":"第二十二条","txt":"医疗机构制剂的临床研究，应当在本医疗机构按照临床研究方案进行，受试例数不得少于60例。"},{"i":23,"n":"第二十三条","txt":"完成临床研究后，申请人向所在地省、自治区、直辖市（食品）药品监督管理部门或者其委托的设区的市级（食品）药品监督管理机构报送临床研究总结资料。"},{"i":24,"n":"第二十四条","txt":"省、自治区、直辖市（食品）药品监督管理部门收到全部申报资料后40日内组织完成技术审评，做出是否准予许可的决定。符合规定的，应当自做出准予许可决定之日起10日内向申请人核发《医疗机构制剂注册批件》及制剂批准文号，同时报国家食品药品监督管理局备案；不符合规定的，应当书面通知申请人并说明理由，同时告知申请人享有依法申请行政复议或者提起行政诉讼的权利。"},{"i":25,"n":"第二十五条","txt":"医疗机构制剂批准文号的格式为： X药制字H（Z）＋4位年号＋4位流水号。 X-省、自治区、直辖市简称，H-化学制剂，Z-中药制剂。"},{"i":26,"n":"第二十六条","txt":"医疗机构制剂一般不得调剂使用。发生灾情、疫情、突发事件或者临床急需而市场没有供应时，需要调剂使用的，属省级辖区内医疗机构制剂调剂的，必须经所在地省、自治区、直辖市（食品）药品监督管理部门批准；属国家食品药品监督管理局规定的特殊制剂以及省、自治区、直辖市之间医疗机构制剂调剂的，必须经国家食品药品监督管理局批准。"},{"i":27,"n":"第二十七条","txt":"省级辖区内申请医疗机构制剂调剂使用的，应当由使用单位向所在地省、自治区、直辖市（食品）药品监督管理部门提出申请，说明使用理由、期限、数量和范围，并报送有关资料。 省、自治区、直辖市之间医疗机构制剂的调剂使用以及国家食品药品监督管理局规定的特殊制剂的调剂使用，应当由取得制剂批准文号的医疗机构向所在地省、自治区、直辖市（食品）药品监督管理部门提出申请，说明使用理由、期限、数量和范围，经所在地省、自治区、直辖市（食品）药品监督管理部门审查同意后，由使用单位将审查意见和相关资料一并报送使用单位所在地省、自治区、直辖市（食品）药品监督管理部门审核同意后，报国家食品药品监督管理局审批。"},{"i":28,"n":"第二十八条","txt":"取得制剂批准文号的医疗机构应当对调剂使用的医疗机构制剂的质量负责。接受调剂的医疗机构应当严格按照制剂的说明书使用制剂，并对超范围使用或者使用不当造成的不良后果承担责任。"},{"i":29,"n":"第二十九条","txt":"医疗机构制剂的调剂使用，不得超出规定的期限、数量和范围。"},{"i":30,"n":"第三十条","txt":"医疗机构配制制剂，应当严格执行经批准的质量标准，并不得擅自变更工艺、处方、配制地点和委托配制单位。需要变更的，申请人应当提出补充申请，报送相关资料，经批准后方可执行。"},{"i":31,"n":"第三十一条","txt":"医疗机构制剂批准文号的有效期为3年。有效期届满需要继续配制的，申请人应当在有效期届满前3个月按照原申请配制程序提出再注册申请，报送有关资料。"},{"i":32,"n":"第三十二条","txt":"省、自治区、直辖市（食品）药品监督管理部门应当在受理再注册申请后30日内，作出是否批准再注册的决定。准予再注册的，应当自决定做出之日起10日内通知申请人，予以换发《医疗机构制剂注册批件》，并报国家食品药品监督管理局备案。 决定不予再注册的，应当书面通知申请人并说明理由，同时告知申请人享有依法申请行政复议或者提起行政诉讼的权利。"},{"i":33,"n":"第三十三条","txt":"有下列情形之一的，省、自治区、直辖市（食品）药品监督管理部门不予批准再注册，并注销制剂批准文号： （一）市场上已有供应的品种； （二）按照本办法应予撤销批准文号的： （三）未在规定时间内提出再注册申请的； （四）其他不符合规定的。"},{"i":34,"n":"第三十四条","txt":"已被注销批准文号的医疗机构制剂，不得配制和使用；已经配制的，由当地（食品）药品监督管理部门监督销毁或者处理。"},{"i":35,"n":"第三十五条","txt":"配制和使用制剂的医疗机构应当注意观察制剂不良反应，并按照国家食品药品监督管理局的有关规定报告和处理。"},{"i":36,"n":"第三十六条","txt":"省、自治区、直辖市（食品）药品监督管理部门对质量不稳定、疗效不确切、不良反应大或者其他原因危害人体健康的医疗机构制剂，应当责令医疗机构停止配制，并撤销其批准文号。 已被撤销批准文号的医疗机构制剂，不得配制和使用；已经配制的，由当地（食品）药品监督管理部门监督销毁或者处理。"},{"i":37,"n":"第三十七条","txt":"医疗机构制剂的抽查检验，按照国家食品药品监督管理局药品抽查检验的有关规定执行。"},{"i":38,"n":"第三十八条","txt":"医疗机构不再具有配制制剂的资格或者条件时，其取得的相应制剂批准文号自行废止，并由省、自治区、直辖市（食品）药品监督管理部门予以注销，但允许委托配制的中药制剂批准文号除外。允许委托配制的中药制剂如需继续配制，可参照本办法第三十条变更委托配制单位的规定提出委托配制的补充申请。"},{"i":39,"n":"第三十九条","txt":"未经批准，医疗机构擅自使用其他医疗机构配制的制剂的，依照《药品管理法》第八十条的规定给予处罚。"},{"i":40,"n":"第四十条","txt":"医疗机构配制制剂，违反《药品管理法》第四十八条、第四十九条规定的，分别依照《药品管理法》第七十四条、第七十五条的规定给予处罚。 未按省、自治区、直辖市（食品）药品监督管理部门批准的标准配制制剂的，属于《药品管理法》第四十九条第三款第六项其他不符合药品标准规定的情形，依照《药品管理法》第七十五条的规定给予处罚。"},{"i":41,"n":"第四十一条","txt":"提供虚假的证明文件、申报资料、样品或者采取其他欺骗手段申请批准证明文件的，省、自治区、直辖市（食品）药品监督管理部门对该申请不予受理，对申请人给予警告，一年内不受理其申请；已取得批准证明文件的，撤销其批准证明文件，五年内不受理其申请，并处一万元以上三万元以下罚款。"},{"i":42,"n":"第四十二条","txt":"医疗机构配制的制剂不得在市场上销售或者变相销售，不得发布医疗机构制剂广告。 医疗机构将其配制的制剂在市场上销售或者变相销售的，依照《药品管理法》第八十四条的规定给予处罚。"},{"i":43,"n":"第四十三条","txt":"省、自治区、直辖市（食品）药品监督管理部门违反本办法的行政行为，国家食品药品监督管理局应当责令其限期改正；逾期不改正的，由国家食品药品监督管理局予以改变或者撤销。"},{"i":44,"n":"第四十四条","txt":"本办法规定的行政机关实施行政许可的期限以工作日计算，不含法定节假日。"},{"i":45,"n":"第四十五条","txt":"本办法中“固定处方制剂”，是指制剂处方固定不变，配制工艺成熟，并且可在临床上长期使用于某一病症的制剂。"},{"i":46,"n":"第四十六条","txt":"省、自治区、直辖市（食品）药品监督管理部门可以根据本办法，结合本地实际制定实施细则。"},{"i":47,"n":"第四十七条","txt":"本办法自2005年8月1日起施行。 附件： 1、医疗机构制剂注册申报资料要求 2、医疗机构制剂调剂使用申报资料项目 3、医疗机构制剂再注册申报资料项目 4、医疗机构制剂有关的申请表格及批件格式 附件一： 医疗机构制剂注册申报资料要求 一、申报资料项目 1．制剂名称及命名依据。 2．立题目的以及该品种的市场供应情况。 3．证明性文件。 4．标签及说明书设计样稿。 5．处方组成、来源、理论依据以及使用背景情况。 6．配制工艺的研究资料及文献资料。 7．质量研究的试验资料及文献资料。 8．制剂的质量标准草案及起草说明。 9．制剂的稳定性试验资料。 10．样品的自检报告书。 11．辅料的来源及质量标准。 12．直接接触制剂的包装材料和容器的选择依据及质量标准。 13．主要药效学试验资料及文献资料。 14．急性毒性试验资料及文献资料。 15．长期毒性试验资料及文献资料。 16．临床研究方案。 1"}],"yiliaojigouzhijipeizhijianduguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强医疗机构制剂配制的监督管理，根据《中华人民共和国药品管理法》（以下简称《药品管理法》）、《中华人民共和国药品管理法实施条例》（以下简称《药品管理法实施条例》）的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"医疗机构制剂的配制及其监督管理适用本办法。"},{"i":3,"n":"第三条","txt":"医疗机构制剂配制监督管理是指（食品）药品监督管理部门依法对医疗机构制剂配制条件和配制过程等进行审查、许可、检查的监督管理活动。"},{"i":4,"n":"第四条","txt":"国家食品药品监督管理局负责全国医疗机构制剂配制的监督管理工作。 省、自治区、直辖市（食品）药品监督管理部门负责本辖区医疗机构制剂配制的监督管理工作。"},{"i":5,"n":"第五条","txt":"医疗机构配制制剂应当遵守《医疗机构制剂配制质量管理规范》。"},{"i":6,"n":"第六条","txt":"医疗机构配制制剂，必须具有能够保证制剂质量的人员、设施、检验仪器、卫生条件和管理制度。"},{"i":7,"n":"第七条","txt":"医疗机构设立制剂室，应当向所在地省、自治区、直辖市（食品）药品监督管理部门提交以下材料： （一）《医疗机构制剂许可证申请表》（见附件1）； （二）实施《医疗机构制剂配制质量管理规范》自查报告； （三）医疗机构的基本情况及《医疗机构执业许可证》副本复印件； （四）所在地省、自治区、直辖市卫生行政部门的审核同意意见； （五）拟办制剂室的基本情况，包括制剂室的投资规模、占地面积、周围环境、基础设施等条件说明，并提供医疗机构总平面布局图、制剂室总平面布局图（标明空气洁净度等级）； 制剂室负责人、药检室负责人、制剂质量管理组织负责人简历（包括姓名、年龄、性别、学历、所学专业、职务、职称、原从事药学工作年限等）及专业技术人员占制剂室工作人员的比例； 制剂室负责人、药检室负责人、制剂质量管理组织负责人应当为本单位在职专业人员，且制剂室负责人和药检室负责人不得互相兼任； （六）拟配制剂型、配制能力、品"},{"i":8,"n":"第八条","txt":"申请人应当对其申请材料的真实性负责。"},{"i":9,"n":"第九条","txt":"省、自治区、直辖市（食品）药品监督管理部门收到申请后，应当根据下列情况分别作出处理： （一）申请事项依法不属于本部门职权范围的，应当即时作出不予受理的决定，并告知申请人向有关行政机关申请； （二）申请材料存在可以当场更正的错误的，应当允许申请人当场更正； （三）申请材料不齐全或者不符合形式审查要求的，应当当场或者在5个工作日内发给申请人《补正材料通知书》，一次性告知申请人需要补正的全部内容，逾期不告知的，自收到申请材料之日起即为受理； （四）申请材料齐全、符合形式审查要求，或者申请人按照要求提交全部补正材料的，予以受理。 省、自治区、直辖市（食品）药品监督管理部门受理或者不受理《医疗机构制剂许可证》申请的，应当出具加盖本部门受理专用印章并注明日期的《受理通知书》或者《不予受理通知书》。"},{"i":10,"n":"第十条","txt":"省、自治区、直辖市（食品）药品监督管理部门应当自收到申请之日起30个工作日内，按照国家食品药品监督管理局制定的《医疗机构制剂许可证验收标准》组织验收。验收合格的，予以批准，并自批准决定作出之日起10个工作日内向申请人核发《医疗机构制剂许可证》；验收不合格的，作出不予批准的决定，书面通知申请人并说明理由，同时告知申请人享有依法申请行政复议或者提起行政诉讼的权利。 省、自治区、直辖市（食品）药品监督管理部门验收合格后，应当自颁发《医疗机构制剂许可证》之日起20个工作日内，将有关情况报国家食品药品监督管理局备案。"},{"i":11,"n":"第十一条","txt":"省、自治区、直辖市（食品）药品监督管理部门应当在办公场所公示申请《医疗机构制剂许可证》所需的事项、依据、条件、期限、需要提交的全部材料的目录和申请书示范文本等。 省、自治区、直辖市（食品）药品监督管理部门颁发《医疗机构制剂许可证》的有关决定，应当予以公开，公众有权查阅。"},{"i":12,"n":"第十二条","txt":"省、自治区、直辖市（食品）药品监督管理部门在对医疗机构制剂室开办申请进行审查时，应当公示审批过程和审批结果。申请人和利害关系人可以对直接关系其重大利益的事项提交书面意见进行陈述和申辩。"},{"i":13,"n":"第十三条","txt":"医疗机构设立制剂室的申请，直接涉及申请人与他人之间重大利益关系的，省、自治区、直辖市（食品）药品监督管理部门应当告知申请人、利害关系人享有申请听证的权利。 在核发《医疗机构制剂许可证》的过程中，省、自治区、直辖市（食品）药品监督管理部门认为涉及公共利益的重大许可事项，应当向社会公告，并举行听证。"},{"i":14,"n":"第十四条","txt":"医疗机构不得与其他单位共用配制场所、配制设备及检验设施等。"},{"i":15,"n":"第十五条","txt":"《医疗机构制剂许可证》分正本和副本。正、副本具有同等法律效力，有效期为5年。 《医疗机构制剂许可证》格式由国家食品药品监督管理局统一规定。"},{"i":16,"n":"第十六条","txt":"《医疗机构制剂许可证》是医疗机构配制制剂的法定凭证，应当载明证号、医疗机构名称、医疗机构类别、法定代表人、制剂室负责人、配制范围、注册地址、配制地址、发证机关、发证日期、有效期限等项目。其中由（食品）药品监督管理部门核准的许可事项为：制剂室负责人、配制地址、配制范围、有效期限。证号和配制范围按国家食品药品监督管理局规定的编号方法和制剂类别填写（见附件2、3）。"},{"i":17,"n":"第十七条","txt":"《医疗机构制剂许可证》变更分为许可事项变更和登记事项变更。 许可事项变更是指制剂室负责人、配制地址、配制范围的变更。 登记事项变更是指医疗机构名称、医疗机构类别、法定代表人、注册地址等事项的变更。"},{"i":18,"n":"第十八条","txt":"医疗机构变更《医疗机构制剂许可证》许可事项的，在许可事项发生变更前30日，向原审核、批准机关申请变更登记。原发证机关应当自收到变更申请之日起15个工作日内作出准予变更或者不予变更的决定。 医疗机构增加配制范围或者改变配制地址的，应当按本办法第七条的规定提交材料，经省、自治区、直辖市（食品）药品监督管理部门验收合格后，依照前款办理《医疗机构制剂许可证》变更登记。"},{"i":19,"n":"第十九条","txt":"医疗机构变更登记事项的，应当在有关部门核准变更后30日内，向原发证机关申请《医疗机构制剂许可证》变更登记，原发证机关应当在收到变更申请之日起15个工作日内办理变更手续。"},{"i":20,"n":"第二十条","txt":"《医疗机构制剂许可证》变更后，原发证机关应当在《医疗机构制剂许可证》副本上记录变更的内容和时间，并按变更后的内容重新核发《医疗机构制剂许可证》正本，收回原《医疗机构制剂许可证》正本。"},{"i":21,"n":"第二十一条","txt":"《医疗机构制剂许可证》有效期届满需要继续配制制剂的，医疗机构应当在有效期届满前6个月，向原发证机关申请换发《医疗机构制剂许可证》。 原发证机关结合医疗机构遵守法律法规、《医疗机构制剂配制质量管理规范》和质量体系运行情况，按照本办法关于设立医疗机构制剂室的条件和程序进行审查，在《医疗机构制剂许可证》有效期届满前作出是否准予换证的决定。符合规定准予换证的，收回原证，换发新证；不符合规定的，作出不予换证的书面决定，并说明理由，同时告知申请人享有依法申请行政复议或者提起行政诉讼的权利；逾期未作出决定的，视为同意换证，并办理相应手续。"},{"i":22,"n":"第二十二条","txt":"医疗机构终止配制制剂或者关闭的，由原发证机关缴销《医疗机构制剂许可证》，同时报国家食品药品监督管理局备案。"},{"i":23,"n":"第二十三条","txt":"遗失《医疗机构制剂许可证》的，持证单位应当在原发证机关指定的媒体上登载遗失声明并同时向原发证机关申请补发。遗失声明登载满1个月后原发证机关在10个工作日内补发《医疗机构制剂许可证》。"},{"i":24,"n":"第二十四条","txt":"医疗机构制剂室的药检室负责人及质量管理组织负责人发生变更的，应当在变更之日起30日内将变更人员简历及学历证明等有关情况报所在地省、自治区、直辖市（食品）药品监督管理部门备案。"},{"i":25,"n":"第二十五条","txt":"医疗机构制剂室的关键配制设施等条件发生变化的，应当自发生变化之日起30日内报所在地省、自治区、直辖市（食品）药品监督管理部门备案，省、自治区、直辖市（食品）药品监督管理部门根据需要进行检查。"},{"i":26,"n":"第二十六条","txt":"省、自治区、直辖市（食品）药品监督管理部门应当将上年度《医疗机构制剂许可证》核发、变更、换发、缴销、补办等办理情况，在每年3月底前汇总报国家食品药品监督管理局。"},{"i":27,"n":"第二十七条","txt":"任何单位和个人不得伪造、变造、买卖、出租、出借《医疗机构制剂许可证》。"},{"i":28,"n":"第二十八条","txt":"经省、自治区、直辖市（食品）药品监督管理部门批准，具有《医疗机构制剂许可证》且取得制剂批准文号，并属于“医院”类别的医疗机构的中药制剂，可以委托本省、自治区、直辖市内取得《医疗机构制剂许可证》的医疗机构或者取得《药品生产质量管理规范》认证证书的药品生产企业配制制剂。委托配制的制剂剂型应当与受托方持有的《医疗机构制剂许可证》或者《药品生产质量管理规范》认证证书所载明的范围一致。 未取得《医疗机构制剂许可证》的“医院”类别的医疗机构，在申请中药制剂批准文号时申请委托配制的，应当按照《医疗机构制剂注册管理办法》的相关规定办理。"},{"i":29,"n":"第二十九条","txt":"委托方按照本办法第三十三条的规定向所在地省、自治区、直辖市（食品）药品监督管理部门提交中药制剂委托配制的申请材料；省、自治区、直辖市（食品）药品监督管理部门参照本办法第九条的规定进行受理。"},{"i":30,"n":"第三十条","txt":"省、自治区、直辖市（食品）药品监督管理部门应当自申请受理之日起20个工作日内，按照本章规定的条件对申请进行审查，并作出决定。 经审查符合规定的，予以批准，并自书面批准决定作出之日起10个工作日内向委托方发放《医疗机构中药制剂委托配制批件》；不符合规定的，书面通知委托方并说明理由，同时告知其享有依法申请行政复议或者提起行政诉讼的权利。"},{"i":31,"n":"第三十一条","txt":"《医疗机构中药制剂委托配制批件》有效期不得超过该制剂批准证明文件载明的有效期限。在《医疗机构中药制剂委托配制批件》有效期内，委托方不得再行委托其他单位配制该制剂。"},{"i":32,"n":"第三十二条","txt":"《医疗机构中药制剂委托配制批件》有效期届满，需要继续委托配制的，委托方应当在有效期届满30日前办理委托配制的续展手续。 委托配制合同终止的，《医疗机构中药制剂委托配制批件》自动废止。"},{"i":33,"n":"第三十三条","txt":"申请制剂委托配制应当提供以下资料： （一）《医疗机构中药制剂委托配制申请表》（见附件4）； （二）委托方的《医疗机构制剂许可证》、制剂批准证明文件复印件； （三）受托方的《药品生产许可证》、《药品生产质量管理规范》认证证书或者《医疗机构制剂许可证》复印件； （四）委托配制的制剂质量标准、配制工艺； （五）委托配制的制剂原最小包装、标签和使用说明书实样； （六）委托配制的制剂拟采用的包装、标签和说明书式样及色标； （七）委托配制合同； （八）受托方所在地设区的市级（食品）药品监督管理机构组织对受托方技术人员，厂房（制剂室）、设施、设备等生产条件和能力，以及质检机构、检测设备等质量保证体系考核的意见。 委托配制申请续展应当提供以下资料： （一）委托方的《医疗机构制剂许可证》、制剂批准证明文件复印件； （二）受托方的《药品生产许可证》、《药品生产质量管理规范》认证证书或者《医疗机构制剂许可证"},{"i":34,"n":"第三十四条","txt":"委托配制制剂的质量标准应当执行原批准的质量标准，其处方、工艺、包装规格、标签及使用说明书等应当与原批准的内容相同。在委托配制的制剂包装、标签和说明书上，应当标明委托单位和受托单位名称、受托单位生产地址。 委托单位取得《医疗机构中药制剂委托配制批件》后，应当向所在地的设区的市级以上药品检验所报送委托配制的前三批制剂，经检验合格后方可投入使用。"},{"i":35,"n":"第三十五条","txt":"委托方对委托配制制剂的质量负责；受托方应当具备与配制该制剂相适应的配制与质量保证条件，按《药品生产质量管理规范》或者《医疗机构制剂配制质量管理规范》进行配制，向委托方出具批检验报告书，并按规定保存所有受托配制的文件和记录。"},{"i":36,"n":"第三十六条","txt":"省、自治区、直辖市（食品）药品监督管理部门对制剂委托配制申请进行审查时，应当参照执行本办法第十一条至第十三条的有关规定。"},{"i":37,"n":"第三十七条","txt":"省、自治区、直辖市（食品）药品监督管理部门应当将制剂委托配制的批准情况报国家食品药品监督管理局。"},{"i":38,"n":"第三十八条","txt":"本办法规定的监督检查的主要内容是医疗机构执行《医疗机构制剂配制质量管理规范》的情况、《医疗机构制剂许可证》换发的现场检查以及日常的监督检查。"},{"i":39,"n":"第三十九条","txt":"省、自治区、直辖市（食品）药品监督管理部门负责本辖区内医疗机构制剂配制的监督检查工作，应当建立实施监督检查的运行机制和管理制度，确定设区的市级（食品）药品监督管理机构和县级（食品）药品监督管理机构的监督检查职责。 国家食品药品监督管理局可以根据需要组织对医疗机构制剂配制进行监督检查，同时对省、自治区、直辖市（食品）药品监督管理部门的监督检查工作情况进行监督和抽查。"},{"i":40,"n":"第四十条","txt":"各级（食品）药品监督管理部门组织监督检查时，应当制订检查方案，明确检查标准，如实记录现场检查情况，提出整改内容及整改期限，检查结果以书面形式告知被检查单位，并实施追踪检查。"},{"i":41,"n":"第四十一条","txt":"监督检查时，医疗机构应当提供有关情况和材料： （一）实施《医疗机构制剂配制质量管理规范》自查情况； （二）《医疗机构执业许可证》、《医疗机构制剂许可证》； （三）药检室和制剂质量管理组织负责人以及主要配制条件、配制设备的变更情况； （四）制剂室接受监督检查及整改落实情况； （五）不合格制剂被质量公报通告后的整改情况； （六）需要审查的其他材料。"},{"i":42,"n":"第四十二条","txt":"监督检查完成后，（食品）药品监督管理部门在《医疗机构制剂许可证》副本上载明检查情况，并记载以下内容： （一）检查结论； （二）配制的制剂是否发生重大质量事故，是否有不合格制剂受到药品质量公报通告； （三）制剂室是否有违法配制行为及查处情况； （四）制剂室当年是否无配制制剂行为。"},{"i":43,"n":"第四十三条","txt":"医疗机构制剂配制发生重大质量事故，必须立即报所在地省、自治区、直辖市（食品）药品监督管理部门和有关部门，省、自治区、直辖市（食品）药品监督管理局部门应当在24小时内报国家食品药品监督管理局。"},{"i":44,"n":"第四十四条","txt":"（食品）药品监督管理部门实施监督检查，不得妨碍医疗机构的正常配制活动，不得索取或者收受医疗机构的财物，不得谋取其他利益。"},{"i":45,"n":"第四十五条","txt":"任何单位和个人发现医疗机构进行违法配制的活动，有权向（食品）药品监督管理部门举报，接受举报的（食品）药品监督管理部门应当及时核实、处理。"},{"i":46,"n":"第四十六条","txt":"有《中华人民共和国行政许可法》（以下简称《行政许可法》）第七十条情形之一的，原发证机关应当依法注销《医疗机构制剂许可证》。 省、自治区、直辖市（食品）药品监督管理部门注销《医疗机构制剂许可证》的，应当自注销之日起5个工作日内通知有关部门，并报国家食品药品监督管理局备案。"},{"i":47,"n":"第四十七条","txt":"有《行政许可法》第六十九条规定情形的，国家食品药品监督管理局或者省、自治区、直辖市（食品）药品监督管理部门根据利害关系人的请求或者依据职权，可以撤销《医疗机构制剂许可证》。"},{"i":48,"n":"第四十八条","txt":"申请人隐瞒有关情况或者提供虚假材料申请《医疗机构制剂许可证》的，省、自治区、直辖市（食品）药品监督管理部门不予受理或者不予批准，并给予警告，申请人在1年内不得再申请。 申请人提供虚假材料取得《医疗机构制剂许可证》的，省、自治区、直辖市（食品）药品监督管理部门应当吊销其《医疗机构制剂许可证》，并处1万元以上3万元以下的罚款，申请人在5年内不得再申请。"},{"i":49,"n":"第四十九条","txt":"未取得《医疗机构制剂许可证》配制制剂的，按《药品管理法》第七十三条的规定给予处罚。"},{"i":50,"n":"第五十条","txt":"（食品）药品监督管理部门对不符合法定条件的单位发给《医疗机构制剂许可证》的，按《药品管理法》第九十四条规定给予处罚。"},{"i":51,"n":"第五十一条","txt":"未经批准擅自委托或者接受委托配制制剂的，对委托方和受托方均依照《药品管理法》第七十四条的规定给予处罚。"},{"i":52,"n":"第五十二条","txt":"医疗机构违反本办法第十九条、第二十四条规定的，由所在地省、自治区、直辖市（食品）药品监督管理部门责令改正。 医疗机构违反本办法第二十五条规定的，由所在地省、自治区、直辖市（食品）药品监督管理部门给予警告，责令限期改正；逾期不改正的，可以处5000元以上1万元以下的罚款。"},{"i":53,"n":"第五十三条","txt":"在实施本办法规定的行政许可中违反相关法律、法规的，按有关法律、法规处理。"},{"i":54,"n":"第五十四条","txt":"本办法由国家食品药品监督管理局负责解释。"},{"i":55,"n":"第五十五条","txt":"本办法自2005年6月1日起施行。 　　附件：1．医疗机构制剂许可证申请表 　　2．《医疗机构制剂许可证》编号方法及代码 　　3．《医疗机构制剂许可证》中配制范围分类及填写规则 　　4．医疗机构中药制剂委托配制申请表 　　附件1： 　　登记编号： 医疗机构制剂许可证申请表 　　申请单位：　　　　　　　　　　　　　　　　　　　　　（公章） 　　填报日期：　　　　　　　　　　　　　　　　　年　　　月　　　日 　　国家食品药品监督管理局制 　　填写说明 　　一、登记编号由省、自治区、直辖市（食品）药品监督管理局填写。 　　二、医疗机构名称、法定代表人、注册地址、医疗机构类别按卫生部门核准的内容填写。 　　三、电话号码前标明所在地区长途电话区号。 　　四、配制地址应按制剂实际配制所在地址填写。 　　五、《医疗机构制剂许可证》证号和配制范围按国家食品药品监督管理局规定的编号方法及制剂类别填写"}],"yiliaojigouzhijipeizhizhiliangguanliguifan":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国药品管理法》的规定，参照《药品生产质量管理规范》的基本原则，制定本规范。"},{"i":2,"n":"第二条","txt":"医疗机构制剂是指医疗机构根据本单位临床需要而常规配制、自用的固定处方制剂。"},{"i":3,"n":"第三条","txt":"医疗机构配制制剂应取得省、自治区、直辖市药品监督管理局颁发的《医疗机构制剂许可证》。"},{"i":4,"n":"第四条","txt":"国家药品监督管理局和省、自治区、直辖市药品监督管理局负责对医疗机构制剂进行质量监督，并发布质量公告。"},{"i":5,"n":"第五条","txt":"本规范是医疗机构制剂配制和质量管理的基本准则，适用于制剂配制的全过程。"},{"i":6,"n":"第六条","txt":"医疗机构制剂配制应在药剂部门设制剂室、药检室和质量管理组织。机构与岗位人员的职责应明确，并配备具有相应素质及相应数量的专业技术人员。"},{"i":7,"n":"第七条","txt":"医疗机构负责人对本《规范》的实施及制剂质量负责。"},{"i":8,"n":"第八条","txt":"制剂室和药检室的负责人应具有大专以上药学或相关专业学历，具有相应管理的实践经验，有对工作中出现的问题作出正确判断和处理的能力。 制剂室和药检室的负责人不得互相兼任。"},{"i":9,"n":"第九条","txt":"从事制剂配制操作及药检人员，应经专业技术培训，具有基础理论知识和实际操作技能。 凡有特殊要求的制剂配制操作和药检人员还应经相应的专业技术培训。"},{"i":10,"n":"第十条","txt":"凡从事制剂配制工作的所有人员均应熟悉本规范，并应通过本规范的培训与考核。"},{"i":11,"n":"第十一条","txt":"为保证制剂质量，制剂室要远离各种污染源。周围的地面、路面、植被等不应对制剂配制过程造成污染。"},{"i":12,"n":"第十二条","txt":"制剂室应有防止污染、昆虫和其它动物进入的有效设施。"},{"i":13,"n":"第十三条","txt":"制剂室的房屋和面积必须与所配制的制剂剂型和规模相适应。应设工作人员更衣室。"},{"i":14,"n":"第十四条","txt":"各工作间应按制剂工序和空气洁净度级别要求合理布局。一般区和洁净区分开；配制、分装与贴签、包装分开；内服制剂与外用制剂分开；无菌制剂与其它制剂分开。"},{"i":15,"n":"第十五条","txt":"各种制剂应根据剂型的需要，工序合理衔接，设置不同的操作间，按工序划分操作岗位。"},{"i":16,"n":"第十六条","txt":"制剂室应具有与所配制剂相适应的物料、成品等库房，并有通风、防潮等设施。"},{"i":17,"n":"第十七条","txt":"中药材的前处理、提取、浓缩等必须与其后续工序严格分开，并应有有效的除尘、排风设施。"},{"i":18,"n":"第十八条","txt":"制剂室在设计和施工时，应考虑使用时便于进行清洁工作。洁净室的内表面应平整光滑，无裂缝、接口严密，无颗粒物脱落并能耐受清洗和消毒。墙壁与地面等交界处宜成弧形或采取其它措施，以减少积尘和便于清洁。"},{"i":19,"n":"第十九条","txt":"洁净室内各种管道、灯具、风口以及其它公用设施在设计和安装时应避免出现不易清洁的部位。"},{"i":20,"n":"第二十条","txt":"根据制剂工艺要求，划分空气洁净度级别（见附件表Ⅰ、表Ⅱ）。洁净室（区）内空气的微生物数和尘粒数应符合规定，应定期检测并记录。"},{"i":21,"n":"第二十一条","txt":"洁净室（区）应有足够照度，主要工作间的照度宜为３００勒克斯。"},{"i":22,"n":"第二十二条","txt":"洁净室的窗户、技术夹层及进入室内的管道、风口、灯具与墙壁或顶棚的连接部位均应密封。"},{"i":23,"n":"第二十三条","txt":"洁净室（区）应维持一定的正压，并送入一定比例的新风。"},{"i":24,"n":"第二十四条","txt":"洁净室（区）内安装的水池、地漏的位置应适宜，不得对制剂造成污染。１００级洁净区内不得设地漏。"},{"i":25,"n":"第二十五条","txt":"实验动物房应远离制剂室。"},{"i":26,"n":"第二十六条","txt":"设备的选型、安装应符合制剂配制要求，易于清洗、消毒或灭菌，便于操作、维修和保养，并能防止差错和减少污染。"},{"i":27,"n":"第二十七条","txt":"纯化水、注射用水的制备、储存和分配应能防止微生物的滋生和污染。储罐和输送管道所用材料应无毒、耐腐蚀，管道的设计和安装应避免死角、盲管。"},{"i":28,"n":"第二十八条","txt":"与药品直接接触的设备表面应光洁、平整、易清洗或消毒、耐腐蚀；不与药品发生化学变化和吸附药品。设备所用的润滑剂、冷却剂等不得对药品和容器造成污染。"},{"i":29,"n":"第二十九条","txt":"制剂配制和检验应有与所配制制剂品种相适应的设备、设施与仪器。"},{"i":30,"n":"第三十条","txt":"用于制剂配制和检验的仪器、仪表、量具、衡器等其适用范围和精密度应符合制剂配制和检验的要求，应定期校验，并有合格标志。校验记录应至少保存一年。"},{"i":31,"n":"第三十一条","txt":"建立设备管理的各项规章制度，制定标准操作规程。设备应由专人管理，定期维修、保养，并作好记录。"},{"i":32,"n":"第三十二条","txt":"制剂配制所用物料的购入、储存、发放与使用等应制定管理制度。"},{"i":33,"n":"第三十三条","txt":"制剂配制所用的物料应符合药用要求，不得对制剂质量产生不良影响。"},{"i":34,"n":"第三十四条","txt":"制剂配制所用的中药材应按质量标准购入，合理储存与保管。"},{"i":35,"n":"第三十五条","txt":"各种物料要严格管理。合格物料、待验物料及不合格物料应分别存放，并有易于识别的明显标志。不合格的物料，应及时处理。"},{"i":36,"n":"第三十六条","txt":"各种物料应按其性能与用途合理存放。对温度、湿度等有特殊要求的物料，应按规定条件储存。挥发性物料的存放，应注意避免污染其它物料。各种物料不得露天存放。"},{"i":37,"n":"第三十七条","txt":"物料应按规定的使用期限储存，储存期内如有特殊情况应及时检验。"},{"i":38,"n":"第三十八条","txt":"制剂的标签、使用说明书必须与药品监督管理部门批准的内容、式样、文字相一致，不得随意更改；应专柜存放，专人保管，不得流失。"},{"i":39,"n":"第三十九条","txt":"制剂室应有防止污染的卫生措施和卫生管理制度，并由专人负责。"},{"i":40,"n":"第四十条","txt":"配制间不得存放与配制无关的物品。配制中的废弃物应及时处理。"},{"i":41,"n":"第四十一条","txt":"更衣室、浴室及厕所的设置不得对洁净室（区）产生不良影响。"},{"i":42,"n":"第四十二条","txt":"配制间和制剂设备、容器等应有清洁规程，内容包括：清洁方法、程序、间隔时间、使用清洁剂或消毒剂、清洁工具的清洁方法和存放地点等。"},{"i":43,"n":"第四十三条","txt":"洁净室（区）应定期消毒。使用的消毒剂不得对设备、物料和成品产生污染。消毒剂品种应定期更换，防止产生耐药菌株。"},{"i":44,"n":"第四十四条","txt":"工作服的选材、式样及穿戴方式应与配制操作和洁净度级别要求相适应。 洁净室工作服的质地应光滑、不产生静电、不脱落纤维和颗粒性物质。无菌工作服必须包盖全部头发、胡须及脚部，并能阻留人体脱落物并不得混穿。 不同洁净度级别房间使用的工作服应分别定期清洗、整理，必要时应消毒或灭菌。洗涤时不应带入附加的颗粒物质。"},{"i":45,"n":"第四十五条","txt":"洁净室（区）仅限于在该室的配制人员和经批准的人员进入。"},{"i":46,"n":"第四十六条","txt":"进入洁净室（区）的人员不得化妆和佩带饰物，不得裸手直接接触药品。"},{"i":47,"n":"第四十七条","txt":"配制人员应有健康档案，并每年至少体检一次。传染病、皮肤病患者和体表有伤口者不得从事制剂配制工作。"},{"i":48,"n":"第四十八条","txt":"制剂室应有下列文件： （一）《医疗机构制剂许可证》及申报文件、验收、整改记录； （二）制剂品种申报及批准文件； （三）制剂室年检、抽验及监督检查文件及记录。"},{"i":49,"n":"第四十九条","txt":"医疗机构制剂室应有配制管理、质量管理的各项制度和记录。 （一）制剂室操作间、设施和设备的使用、维护、保养等制度和记录； （二）物料的验收、配制操作、检验、发放、成品分发和使用部门及患者的反馈、投诉等制度和记录； （三）配制返工、不合格品管理、物料退库、报损、特殊情况处理等制度和记录； （四）留样观察制度和记录； （五）制剂室内外环境、设备、人员等卫生管理制度和记录； （六）本规范和专业技术培训的制度和记录。"},{"i":50,"n":"第五十条","txt":"制剂配制管理文件主要有： （一）配制规程和标准操作规程 配制规程包括：制剂名称、剂型、处方、配制工艺的操作要求，原料、中间产品、成品的质量标准和技术参数及储存注意事项，成品容器、包装材料的要求等。 标准操作规程：配制过程中涉及的单元操作（如加热、搅拌、振摇、混合等）具体规定和应达到的要求。 （二）配制记录 配制记录（制剂单）应包括：编号、制剂名称、配制日期、制剂批号、有关设备名称与操作记录、原料用量、成品和半成品数量、配制过程的控制记录及特殊情况处理记录和各工序的操作者、复核者、清场者的签名等。"},{"i":51,"n":"第五十一条","txt":"配制制剂的质量管理文件主要有： （一）物料、半成品、成品的质量标准和检验操作规程； （二）制剂质量稳定性考察记录； （三）检验记录。"},{"i":52,"n":"第五十二条","txt":"制剂配制管理文件和质量管理文件的要求： （一）制订文件应符合《药品管理法》和相关法律、法规、规章的要求； （二）应建立文件的管理制度。使用的文件应为批准的现行文本，已撤销和过时的文件除留档备查外，不得在工作现场出现； （三）文件的制订、审查和批准的责任应明确，并有责任人签名； （四）有关配制记录和质量检验记录应完整归档，至少保存２年备查。"},{"i":53,"n":"第五十三条","txt":"配制规程和标准操作规程不得任意修改。如需修改时必须按制定时的程序办理修订、审批手续。"},{"i":54,"n":"第五十四条","txt":"在同一配制周期中制备出来的一定数量常规配制的制剂为一批，一批制剂在规定限度内具有同一性质和质量。每批制剂均应编制制剂批号。"},{"i":55,"n":"第五十五条","txt":"每批制剂均应按投入和产出的物料平衡进行检查，如有显著差异，必须查明原因，在得出合理解释，确认无潜在质量事故后，方可按正常程序处理。"},{"i":56,"n":"第五十六条","txt":"为防止制剂被污染和混淆，配制操作应采取下述措施： （一）每次配制后应清场，并填写清场记录。每次配制前应确认无上次遗留物； （二）不同制剂（包括同一制剂的不同规格）的配制操作不得在同一操作间同时进行； 如确实无法避免时，必须在不同的操作台配制，并应采取防止污染和混淆的措施； （三）在配制过程中应防止称量、过筛、粉碎等可能造成粉末飞散而引起的交叉污染； （四）在配制过程中使用的容器须有标明物料名称、批号、状态及数量等的标志。"},{"i":57,"n":"第五十七条","txt":"根据制剂配制规程选用工艺用水。工艺用水应符合质量标准并定期检验。根据验证结果，规定检验周期。"},{"i":58,"n":"第五十八条","txt":"每批制剂均应有一份能反映配制各个环节的完整记录。操作人员应及时填写记录，填写字迹清晰、内容真实、数据完整，并由操作人、复核人及清场人签字。记录应保持整洁，不得撕毁和任意涂改。需要更改时，更改人应在更改处签字，并需使被更改部分可以辨认。"},{"i":59,"n":"第五十九条","txt":"新制剂的配制工艺及主要设备应按验证方案进行验证。当影响制剂质量的主要因素，如配制工艺或质量控制方法、主要原辅料、主要配制设备等发生改变时，以及配制一定周期后，应进行再验证。所有验证记录应归档保存。"},{"i":60,"n":"第六十条","txt":"质量管理组织负责制剂配制全过程的质量管理。其主要职责： （一）制定质量管理组织任务、职责； （二）决定物料和中间品能否使用； （三）研究处理制剂重大质量问题； （四）制剂经检验合格后，由质量管理组织负责人审查配制全过程记录并决定是否发放使用； （五）审核不合格品的处理程序及监督实施。"},{"i":61,"n":"第六十一条","txt":"药检室负责制剂配制全过程的检验。其主要职责： （一）制定和修订物料、中间品和成品的内控标准和检验操作规程，制定取样和留样制度； （二）制定检验用设备、仪器、试剂、试液、标准品（或参考品）、滴定液与培养基及实验动物等管理办法； （三）对物料、中间品和成品进行取样、检验、留样，并出具检验报告； （四）监测洁净室（区）的微生物数和尘粒数； （五）评价原料、中间品及成品的质量稳定性，为确定物料储存期和制剂有效期提供数据； （六）制定药检室人员的职责。"},{"i":62,"n":"第六十二条","txt":"医疗机构制剂质量管理组织应定期组织自检。自检应按预定的程序，按规定内容进行检查，以证实与本规范的一致性。 自检应有记录并写出自检报告，包括评价及改进措施等。"},{"i":63,"n":"第六十三条","txt":"医疗机构制剂应按药品监督管理部门制定的原则并结合剂型特点、原料药的稳定性和制剂稳定性试验结果规定使用期限。"},{"i":64,"n":"第六十四条","txt":"制剂配发必须有完整的记录或凭据。内容包括：领用部门、制剂名称、批号、规格、数量等。制剂在使用过程中出现质量问题时，制剂质量管理组织应及时进行处理，出现质量问题的制剂应立即收回，并填写收回记录。收回记录应包括：制剂名称、批号、规格、数量、收回部门、收回原因、处理意见及日期等。"},{"i":65,"n":"第六十五条","txt":"制剂使用过程中发现的不良反应，应按《药品不良反应监测管理办法》的规定予以记录，填表上报。保留病历和有关检验、检查报告单等原始记录至少一年备查。"},{"i":66,"n":"第六十六条","txt":"本规范所使用的术语： 标准操作规程：经批准用以指示操作的通用性文件或管理办法。 配制规程：为各个制剂制定，为配制该制剂的标准操作，包括投料、配制工艺、成品包装等内容。 物料：原料、辅料、包装材料等。 验证：证明任何程序、配制过程、设备、物料、活动或系统确实能达到预期结果的有文件证明的一系列行动。 洁净室（区）：需要对尘粒及微生物数量进行控制的房间（区域）。其建筑结构、装备及其使用均具有减少该区域内污染源的介入、产生和滞留的功能。 一般区：是指洁净区之外，未规定有空气洁净度级别要求的区域，应符合卫生要求。 工艺用水：制剂配制工艺中使用的水，包括：饮用水、纯化水、注射用水。 纯化水：为蒸馏法、离子交换法、反渗透法或其它适宜的方法制得供药用的水，不含任何附加剂。 质量管理组织：是指医疗机构为加强制剂质量管理而由药剂部门及制剂室、药检室负责人组成的小组。"},{"i":67,"n":"第六十七条","txt":"本规范由国家药品监督管理局负责解释。"},{"i":68,"n":"第六十八条","txt":"本规范自发布之日起施行。"}],"guojiashipinyaopinjianduguanlijuyaopintebieshenpic58b1f4":[{"i":1,"n":"第一条","txt":"为有效预防、及时控制和消除突发公共卫生事件的危害，保障公众身体健康与生命安全，根据《中华人民共和国药品管理法》、《中华人民共和国传染病防治法》、《中华人民共和国药品管理法实施条例》和《突发公共卫生事件应急条例》等法律、法规规定，制定本程序。"},{"i":2,"n":"第二条","txt":"药品特别审批程序是指，存在发生突发公共卫生事件的威胁时以及突发公共卫生事件发生后，为使突发公共卫生事件应急所需防治药品尽快获得批准，国家食品药品监督管理局按照统一指挥、早期介入、快速高效、科学审批的原则，对突发公共卫生事件应急处理所需药品进行特别审批的程序和要求。"},{"i":3,"n":"第三条","txt":"存在以下情形时，国家食品药品监督管理局可以依法决定按照本程序对突发公共卫生事件应急所需防治药品实行特别审批： （一）中华人民共和国主席宣布进入紧急状态或者国务院决定省、自治区、直辖市的范围内部分地区进入紧急状态时； （二）突发公共卫生事件应急处理程序依法启动时； （三）国务院药品储备部门和卫生行政主管部门提出对已有国家标准药品实行特别审批的建议时； （四）其他需要实行特别审批的情形。"},{"i":4,"n":"第四条","txt":"国家食品药品监督管理局负责对突发公共卫生事件应急所需防治药品的药物临床试验、生产和进口等事项进行审批。 省、自治区、直辖市（食品）药品监督管理部门受国家食品药品监督管理局委托，负责突发公共卫生事件应急所需防治药品的现场核查及试制样品的抽样工作。"},{"i":5,"n":"第五条","txt":"药品特别审批程序启动后，突发公共卫生事件应急所需防治药品的注册申请统一由国家食品药品监督管理局负责受理。 突发公共卫生事件应急所需药品及预防用生物制品未在国内上市销售的，申请人应当在提出注册申请前，将有关研发情况事先告知国家食品药品监督管理局。"},{"i":6,"n":"第六条","txt":"申请人应当按照药品注册管理的有关规定和要求，向国家食品药品监督管理局提出注册申请，并提交相关技术资料。 突发公共卫生事件应急所需防治药品的注册申请可以电子申报方式提出。"},{"i":7,"n":"第七条","txt":"申请人在提交注册申请前，可以先行提出药物可行性评价申请，并提交综述资料及相关说明。国家食品药品监督管理局仅对申报药物立项的科学性和可行性进行评议，并在24小时内予以答复。 对药物可行性评价申请的答复不作为审批意见，对注册申请审批结果不具有法律约束力。"},{"i":8,"n":"第八条","txt":"国家食品药品监督管理局设立特别专家组，对突发公共卫生事件应急所需防治药品注册申请进行评估和审核，并在24小时内做出是否受理的决定，同时通知申请人。"},{"i":9,"n":"第九条","txt":"注册申请受理后，国家食品药品监督管理局应当在24小时内组织对注册申报资料进行技术审评，同时通知申请人所在地省、自治区、直辖市（食品）药品监督管理部门对药物研制情况及条件进行现场核查，并组织对试制样品进行抽样、检验。 省、自治区、直辖市（食品）药品监督管理部门应当在5日内将现场核查情况及相关意见上报国家食品药品监督管理局。"},{"i":10,"n":"第十条","txt":"省、自治区、直辖市（食品）药品监督管理部门应当组织药品注册、药品安全监管等部门人员参加现场核查。 预防用生物制品的现场核查及抽样工作应通知中国药品生物制品检定所派员参加。"},{"i":11,"n":"第十一条","txt":"突发公共卫生事件应急所需防治药品已有国家标准，国家食品药品监督管理局依法认为不需要进行药物临床试验的，可以直接按照本程序第六章的有关规定进行审批。"},{"i":12,"n":"第十二条","txt":"对申请人提交的只变更原生产用病毒株但不改变生产工艺及质量指标的特殊疫苗注册申请，国家食品药品监督管理局应当在确认变更的生产用病毒株后3日内作出审批决定。"},{"i":13,"n":"第十三条","txt":"药品检验机构收到省、自治区、直辖市（食品）药品监督管理部门抽取的样品后，应当立即组织对样品进行质量标准复核及实验室检验。 药品检验机构应当按照申报药品的检验周期完成检验工作。"},{"i":14,"n":"第十四条","txt":"对首次申请上市的药品，国家食品药品监督管理局认为必要时，可以采取早期介入方式，指派中国药品生物制品检定所在注册检验之前与申请人沟通，及时解决质量标准复核及实验室检验过程中可能出现的技术问题。 对用于预防、控制重大传染病疫情的预防用生物制品，国家食品药品监督管理局根据需要，可以决定注册检验与企业自检同步进行。"},{"i":15,"n":"第十五条","txt":"药物质量标准复核及实验室检验完成后，药品检验机构应当在2日内出具复核意见，连同药品检验报告一并报送国家食品药品监督管理局。"},{"i":16,"n":"第十六条","txt":"国家食品药品监督管理局受理突发公共卫生事件应急所需防治药品的注册申请后，应当在15日内完成首轮技术审评工作。"},{"i":17,"n":"第十七条","txt":"国家食品药品监督管理局认为需要补充资料的，应当将补充资料内容和时限要求立即告知申请人。 申请人在规定时限内提交补充资料后，国家食品药品监督管理局应当在3日内完成技术审评，或者根据需要在5日内再次组织召开审评会议，并在2日内完成审评报告。"},{"i":18,"n":"第十八条","txt":"技术审评工作完成后，国家食品药品监督管理局应当在3日内完成行政审查，作出审批决定，并告知申请人。 国家食品药品监督管理局决定发给临床试验批准证明文件的，应当出具《药物临床试验批件》；决定不予批准临床试验的，应当发给《审批意见通知件》，并说明理由。"},{"i":19,"n":"第十九条","txt":"申请人获准进行药物临床试验的，应当严格按照临床试验批准证明文件的相关要求开展临床试验，并严格执行《药物临床试验质量管理规范》的有关规定。"},{"i":20,"n":"第二十条","txt":"药物临床试验应当在经依法认定的具有药物临床试验资格的机构进行。临床试验确需由未经药物临床试验资格认定的机构承担的，应当得到国家食品药品监督管理局的特殊批准。 未经药物临床试验资格认定的机构承担临床试验的申请可与药品注册申请一并提出。"},{"i":21,"n":"第二十一条","txt":"负责药物临床试验的研究者应当按有关规定及时将临床试验过程中发生的不良事件上报国家食品药品监督管理局；未发生不良事件的，应将有关情况按月汇总上报。"},{"i":22,"n":"第二十二条","txt":"国家食品药品监督管理局依法对突发公共卫生事件应急所需防治药品的药物临床试验开展监督检查。"},{"i":23,"n":"第二十三条","txt":"申请人完成药物临床试验后，应当按照《药品注册管理办法》的有关规定，将相关资料报送国家食品药品监督管理局。"},{"i":24,"n":"第二十四条","txt":"国家食品药品监督管理局收到申请人提交的资料后，应当在24小时内组织技术审评，同时通知申请人所在地省、自治区、直辖市（食品）药品监督管理部门对药品生产情况及条件进行现场核查，并组织对试制样品进行抽样、检验。 省、自治区、直辖市（食品）药品监督管理部门应当在5日内将现场核查情况及相关意见上报国家食品药品监督管理局。"},{"i":25,"n":"第二十五条","txt":"新开办药品生产企业、药品生产企业新建药品生产车间或者新增生产剂型的，可以一并向国家食品药品监督管理局申请《药品生产质量管理规范》认证。国家食品药品监督管理局应当在进行药品注册审评的同时，立即开展《药品生产质量管理规范》认证检查。"},{"i":26,"n":"第二十六条","txt":"药品检验机构收到省、自治区、直辖市（食品）药品监督管理部门抽取的3个生产批号的样品后，应当立即组织安排检验。 检验工作结束后，药品检验机构应当在2日内完成检验报告，并报送国家食品药品监督管理局。"},{"i":27,"n":"第二十七条","txt":"国家食品药品监督管理局应当按照本程序第四章的规定开展技术审评，并于技术审评工作完成后3日内完成行政审查，作出审批决定，并告知申请人。 国家食品药品监督管理局决定发给药品批准证明文件的，应当出具《药品注册批件》，申请人具备药品相应生产条件的，可以同时发给药品批准文号；决定不予批准生产的，应当发给《审批意见通知件》，并说明理由。"},{"i":28,"n":"第二十八条","txt":"药品生产、经营企业和医疗卫生机构发现与特别批准的突发公共卫生事件应急所需防治药品有关的新的或者严重的药品不良反应、群体不良反应，应当立即向所在地省、自治区、直辖市（食品）药品监督管理部门、省级卫生行政主管部门以及药品不良反应监测专业机构报告。 药品不良反应监测专业机构应将特别批准的突发公共卫生事件应急所需防治药品作为重点监测品种，按有关规定对所收集的病例报告进行汇总分析，并及时上报省、自治区、直辖市（食品）药品监督管理部门及国家食品药品监督管理局。 国家食品药品监督管理局应当加强已批准生产的突发公共卫生事件应急所需药品的上市后再评价工作。"},{"i":29,"n":"第二十九条","txt":"突发公共卫生事件应急处理所需医疗器械的特别审批办法，由国家食品药品监督管理局参照本程序有关规定另行制定。"},{"i":30,"n":"第三十条","txt":"本程序自颁布之日起实施。"}],"guojiashipinyaopinjianduguanlizongjuguanyutiaozhen059198":[],"guojiashipinyaopinjianduguanlizongjuguanyutiaozhen901ce6":[],"guojiashipinyaopinjianduguanlizongjuguanyutiaozhene3d813":[],"guojiashipinyaopinjianduguanlizongjuxingzhengfuyibfb614d":[{"i":1,"n":"第一条","txt":"为规范和加强国家食品药品监督管理总局行政复议工作，根据《中华人民共和国行政复议法》（以下简称《行政复议法》）、《中华人民共和国行政复议法实施条例》（以下简称《行政复议法实施条例》），制定本办法。"},{"i":2,"n":"第二条","txt":"依法向国家食品药品监督管理总局申请行政复议的案件，其受理、审理、决定等，适用本办法。"},{"i":3,"n":"第三条","txt":"国家食品药品监督管理总局处理行政复议案件，应当遵循合法、公正、公开、及时、便民的原则，坚持有错必纠，保障法律、法规的正确实施。"},{"i":4,"n":"第四条","txt":"本办法所称行政复议案件是指： （一）不服国家食品药品监督管理总局及其委托的机构或者组织作出的具体行政行为而申请行政复议的案件； （二）不服省、自治区、直辖市食品药品监督管理部门及其委托的机构或者组织作出的具体行政行为而申请行政复议的案件； （三）其他依法由国家食品药品监督管理总局管辖的行政复议案件。"},{"i":5,"n":"第五条","txt":"国家食品药品监督管理总局行政复议办公室（以下简称行政复议办公室）设在法制司，办理行政复议案件的具体事项，依法履行下列职责： （一）对行政复议申请进行初步审查，决定是否受理； （二）向有关组织和人员调查取证，查阅相关文件和资料； （三）组织审理行政复议案件，提出审理建议，拟订行政复议决定； （四）对被申请人违反《行政复议法》、《行政复议法实施条例》及本办法的行为提出处理建议； （五）依照有关规定参与办理因不服行政复议决定提起行政诉讼的应诉事项； （六）法律、行政法规规定的职责和国家食品药品监督管理总局规定的其他职责。"},{"i":6,"n":"第六条","txt":"向国家食品药品监督管理总局申请行政复议，应当符合下列条件： （一）申请人是认为具体行政行为侵犯其合法权益的公民、法人或者其他组织； （二）符合《行政复议法》第二章关于行政复议范围的规定； （三）属于国家食品药品监督管理总局的职责范围； （四）有明确的被申请人； （五）有明确的请求事项和理由； （六）申请人不服的具体行政行为已经客观存在； （七）申请人认为被申请人不作为的，应当有申请人向被申请人提出申请的事实； （八）未超过法定申请期限。"},{"i":7,"n":"第七条","txt":"向国家食品药品监督管理总局申请行政复议，应当提交行政复议申请书（正、副本各一份）及有关证据材料。行政复议申请书应当载明申请人、被申请人、请求事项、事实和理由等内容。书面申请确有困难的，也可以口头提出复议申请，行政复议办公室应当对口头申请的内容和情况制作笔录并由申请人签字。"},{"i":8,"n":"第八条","txt":"行政复议办公室在收到行政复议申请后5个工作日内，按照本办法第六条规定的条件进行审查，符合条件的，依法予以受理；不符合条件的，决定不予受理，并书面告知申请人。 已向其他有权行政机关申请行政复议或者向人民法院提起行政诉讼，该有权行政机关或者人民法院已经依法受理的，国家食品药品监督管理总局不受理其行政复议申请。"},{"i":9,"n":"第九条","txt":"行政复议办公室应当自行政复议申请受理之日起7个工作日内将行政复议答复通知书、行政复议申请书副本或者口头申请笔录复印件发送被申请人。被申请人应当在接到答复通知之日起10日内提交答复意见及有关证据材料。答复意见应当包括当初作出具体行政行为的事实根据和法律依据。 被申请人是国家食品药品监督管理总局的，由有关司局或者机构依前款提交答复意见。"},{"i":10,"n":"第十条","txt":"对已受理的行政复议申请，在审理时发现不符合本办法第六条规定的，国家食品药品监督管理总局决定驳回行政复议申请。"},{"i":11,"n":"第十一条","txt":"审理行政复议案件，遇有下列情形之一的，可以决定中止审理： （一）审理过程中，需要对被申请人作出具体行政行为的依据进行解释而国家食品药品监督管理总局无权解释的； （二）申请人依据《行政复议法》第七条一并提出对具体行政行为所依据规定的审查申请，国家食品药品监督管理总局无权处理的； （三）本案的审理须以相关案件的审理结果为依据，而相关案件尚未审结的； （四）其他依法需要中止审理的。 按前款（一）、（二）项中止审理的，国家食品药品监督管理总局应当在7个工作日内按照法定程序转送有权机关处理。 中止审理的原因消除后，应当在5个工作日内决定恢复审理。 中止审理、恢复审理的决定由行政复议办公室作出，并书面通知当事人。"},{"i":12,"n":"第十二条","txt":"行政复议审理过程中，申请人说明理由后撤回行政复议申请的，行政复议自行终止。"},{"i":13,"n":"第十三条","txt":"审理行政复议案件，应当认真研究案卷，对当事人提供的证据进行调查、核实，必要时可以实地调查取证或者委托地方食品药品监督管理部门调查取证。"},{"i":14,"n":"第十四条","txt":"申请人、第三人可以查阅被申请人提出的书面答复意见及作出具体行政行为的证据、依据和其他有关材料，但涉及国家秘密、商业秘密和个人隐私的除外。"},{"i":15,"n":"第十五条","txt":"被申请人对其作出的具体行政行为承担举证责任，负责证明作出具体行政行为的事实根据和法律依据。 行政复议审理过程中，被申请人不得自行向申请人和其他组织或者个人收集证据。"},{"i":16,"n":"第十六条","txt":"申请人对下列事项承担举证责任： （一）证明行政复议申请符合法定条件，但被申请人认为申请人超过法定申请期限的除外； （二）不服被申请人不作为的，证明其在行政程序中向被申请人提出申请的事实； （三）一并提起行政赔偿申请的，证明其因被申请具体行政行为受到损害的事实； （四）其他依法应当由申请人承担举证责任的事项。"},{"i":17,"n":"第十七条","txt":"行政复议办公室组织审理行政复议案件，有下列情形之一的，应当及时提交局长办公会议研究： （一）对重大、复杂案件的行政复议决定； （二）对申请人依照《行政复议法》第七条提出的对规范性文件的审查申请作出处理决定； （三）对行政复议期间是否停止具体行政行为的执行作出决定； （四）应当提交局长办公会议决定的其他事项。"},{"i":18,"n":"第十八条","txt":"依照本办法第十七条规定应当由局长办公会议研究的行政复议案件，局长办公会议应当按照《行政复议法》第二十八条的规定，就具体行政行为的合法性、合理性及是否予以维持、撤销、变更等作出决定，由行政复议办公室根据局长办公会议的意见拟订行政复议决定书，按程序获得批准后，送达行政复议当事人。"},{"i":19,"n":"第十九条","txt":"依照本办法规定不需要经局长办公会议研究的行政复议案件，由行政复议办公室按照《行政复议法》第二十八条的规定提出审理意见，拟订行政复议决定书，按程序获得批准后，送达行政复议当事人。"},{"i":20,"n":"第二十条","txt":"有下列情形之一的，可以依据本办法第十八条、第十九条规定的程序作出确认具体行政行为无效或者违法的复议决定： （一）被申请人不履行法定职责，但决定责令其履行法定职责已无意义的； （二）被申请人的具体行政行为不合法或者明显不当，但不具有可撤销内容的； （三）被申请人的具体行政行为无效的。"},{"i":21,"n":"第二十一条","txt":"国家食品药品监督管理总局受理行政复议申请不得向当事人收取任何费用，所需经费由国家食品药品监督管理总局专项列支。"},{"i":22,"n":"第二十二条","txt":"本办法自2014年1月1日起施行。2002年8月5日发布的《国家药品监督管理局行政复议暂行办法》（原国家药品监督管理局令第34号）同时废止。"}],"yingyouerpeifangrufenchanpinpeifangzhuceguanlibanfbba623-2":[{"i":1,"n":"第一条","txt":"为严格婴幼儿配方乳粉产品配方注册管理，保证婴幼儿配方乳粉质量安全，根据《中华人民共和国食品安全法》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内生产销售和进口的婴幼儿配方乳粉产品配方注册管理，适用本办法。"},{"i":3,"n":"第三条","txt":"婴幼儿配方乳粉产品配方注册，是指国家食品药品监督管理总局依据本办法规定的程序和要求，对申请注册的婴幼儿配方乳粉产品配方进行审评，并决定是否准予注册的活动。"},{"i":4,"n":"第四条","txt":"婴幼儿配方乳粉产品配方注册管理，应当遵循科学、严格、公开、公平、公正的原则。"},{"i":5,"n":"第五条","txt":"国家食品药品监督管理总局负责婴幼儿配方乳粉产品配方注册管理工作。 国家食品药品监督管理总局行政受理机构（以下简称受理机构）负责婴幼儿配方乳粉产品配方注册申请的受理工作。 国家食品药品监督管理总局食品审评机构（以下简称审评机构）负责婴幼儿配方乳粉产品配方注册申请的审评工作。 国家食品药品监督管理总局审核查验机构（以下简称核查机构）负责婴幼儿配方乳粉产品配方注册的现场核查工作。 省、自治区、直辖市食品药品监督管理部门负责配合国家食品药品监督管理总局开展本行政区域婴幼儿配方乳粉产品配方注册的现场核查等工作。"},{"i":6,"n":"第六条","txt":"申请人应当对提交材料的真实性、完整性、合法性负责，并承担法律责任。 申请人应当协助食品药品监督管理部门开展与注册相关的现场核查、抽样检验等工作。"},{"i":7,"n":"第七条","txt":"申请人应当为拟在中华人民共和国境内生产并销售婴幼儿配方乳粉的生产企业或者拟向中华人民共和国出口婴幼儿配方乳粉的境外生产企业。 申请人应当具备与所生产婴幼儿配方乳粉相适应的研发能力、生产能力、检验能力，符合粉状婴幼儿配方食品良好生产规范要求，实施危害分析与关键控制点体系，对出厂产品按照有关法律法规和婴幼儿配方乳粉食品安全国家标准规定的项目实施逐批检验。"},{"i":8,"n":"第八条","txt":"申请注册产品配方应当符合有关法律法规和食品安全国家标准的要求，并提供证明产品配方科学性、安全性的研发与论证报告和充足依据。 申请婴幼儿配方乳粉产品配方注册，应当向国家食品药品监督管理总局提交下列材料： （一）婴幼儿配方乳粉产品配方注册申请书； （二）申请人主体资质证明文件； （三）原辅料的质量安全标准； （四）产品配方研发报告； （五）生产工艺说明； （六）产品检验报告； （七）研发能力、生产能力、检验能力的证明材料； （八）其他表明配方科学性、安全性的材料。"},{"i":9,"n":"第九条","txt":"同一企业申请注册两个以上同年龄段产品配方时，产品配方之间应当有明显差异，并经科学证实。每个企业原则上不得超过3个配方系列9种产品配方，每个配方系列包括婴儿配方乳粉（0-6月龄，1段）、较大婴儿配方乳粉（6-12月龄，2段）、幼儿配方乳粉（12-36月龄，3段）。"},{"i":10,"n":"第十条","txt":"同一集团公司已经获得婴幼儿配方乳粉产品配方注册及生产许可的全资子公司可以使用集团公司内另一全资子公司已经注册的婴幼儿配方乳粉产品配方。组织生产前，集团公司应当向国家食品药品监督管理总局提交书面报告。"},{"i":11,"n":"第十一条","txt":"受理机构对申请人提出的婴幼儿配方乳粉产品配方注册申请，应当根据下列情况分别作出处理： （一）申请事项依法不需要进行注册的，应当即时告知申请人不受理； （二）申请事项依法不属于国家食品药品监督管理总局职权范围的，应当即时作出不予受理的决定，并告知申请人向有关行政机关申请； （三）申请材料存在可以当场更正的错误的，应当允许申请人当场更正； （四）申请材料不齐全或者不符合法定形式的，应当当场或者在5个工作日内一次告知申请人需要补正的全部内容；逾期不告知的，自收到申请材料之日起即为受理； （五）申请材料齐全、符合法定形式，或者申请人按照要求提交全部补正申请材料的，应当受理注册申请。 受理机构受理或者不予受理注册申请，应当出具加盖国家食品药品监督管理总局行政许可受理专用章和注明日期的书面凭证。"},{"i":12,"n":"第十二条","txt":"受理机构应当在受理后3个工作日内将申请材料送交审评机构。"},{"i":13,"n":"第十三条","txt":"审评机构应当对申请材料以及产品配方声称与产品配方注册内容的一致性进行审查，并根据实际需要通知核查机构对申请人开展现场核查，组织检验机构开展抽样检验，组织专家对专业问题进行论证，自收到受理材料之日起60个工作日内完成审评工作。 特殊情况下需要延长审评时间的，经审评机构负责人同意，可以延长30个工作日，延长决定应当书面告知申请人。"},{"i":14,"n":"第十四条","txt":"核查机构应当自接到审评机构通知之日起20个工作日内完成对申请人研发能力、生产能力、检验能力等情况的现场核查，出具现场核查报告。 核查机构应当通知申请人所在地省级食品药品监督管理部门参与现场核查，省级食品药品监督管理部门应当派员参与。"},{"i":15,"n":"第十五条","txt":"审评机构应当委托具有法定资质的食品检验机构开展抽样检验。 检验机构应当自接受委托之日起30个工作日内完成抽样检验工作，出具产品检验报告。"},{"i":16,"n":"第十六条","txt":"对境外生产企业现场核查、抽样检验的工作时限，根据实际情况确定。"},{"i":17,"n":"第十七条","txt":"审评机构应当根据申请人申请材料、现场核查报告、产品检验报告开展审评，并作出审评结论。"},{"i":18,"n":"第十八条","txt":"审评机构作出不予注册审评结论的，应当向申请人发出拟不予注册的书面通知。申请人对通知有异议的，应当自收到通知之日起20个工作日内向审评机构提出书面复审申请并说明复审理由。复审的内容仅限于原申请事项及申请材料。 审评机构应当自受理复审申请之日起30个工作日内作出复审决定，并书面通知申请人。"},{"i":19,"n":"第十九条","txt":"审评机构认为需要申请人补正材料的，应当一次性告知需要补正的全部内容。申请人应当在3个月内按照补正通知的要求一次补正材料。补正材料的时间不计算在审评时间内。逾期未补正的，按申请人不再提供补正材料处理。"},{"i":20,"n":"第二十条","txt":"国家食品药品监督管理总局自受理申请之日起20个工作日内根据审评结论作出准予注册或者不予注册的决定。 受理机构应当自国家食品药品监督管理总局作出决定之日起10个工作日内向申请人发出婴幼儿配方乳粉产品配方注册证书或者不予注册决定。"},{"i":21,"n":"第二十一条","txt":"现场核查、抽样检验、复审所需时间不计算在技术审评和注册决定的期限内。审评时间不计算在注册决定的期限内。"},{"i":22,"n":"第二十二条","txt":"申请人对国家食品药品监督管理总局作出不予注册决定有异议的，可以向国家食品药品监督管理总局提出书面行政复议申请或者向人民法院提起行政诉讼。"},{"i":23,"n":"第二十三条","txt":"婴幼儿配方乳粉产品配方注册证书及附件应当载明下列事项： （一）产品名称； （二）企业名称、法定代表人、生产地址； （三）注册号、批准日期及有效期； （四）生产工艺； （五）产品配方。 婴幼儿配方乳粉产品配方注册号格式为：国食注字YP＋4位年代号＋4位顺序号，其中YP代表婴幼儿配方乳粉产品配方。 婴幼儿配方乳粉产品配方注册证书有效期为5年。"},{"i":24,"n":"第二十四条","txt":"婴幼儿配方乳粉产品配方注册有效期内，婴幼儿配方乳粉产品配方注册证书遗失或者损毁的，申请人应当向受理机构提出书面申请并说明理由。因遗失申请补发的，应当在省、自治区、直辖市食品药品监督管理部门网站上发布遗失声明；因损坏申请补发的，应当交回婴幼儿配方乳粉产品配方注册证书原件。 国家食品药品监督管理总局自受理之日起20个工作日内予以补发。补发的婴幼儿配方乳粉产品配方注册证书应当标注原批准日期，并注明“补发”字样。"},{"i":25,"n":"第二十五条","txt":"婴幼儿配方乳粉产品配方注册证书有效期内，需要变更注册证书及其附件载明事项的，申请人应当向国家食品药品监督管理总局提出变更注册申请，并提交下列材料： （一）婴幼儿配方乳粉产品配方变更注册申请书； （二）婴幼儿配方乳粉产品配方注册证书及附件； （三）与变更事项有关的证明材料。"},{"i":26,"n":"第二十六条","txt":"申请人申请产品配方变更等可能影响产品配方科学性、安全性的，审评机构应当根据实际需要按照本办法第十三条的规定组织开展审评，并作出审评结论。 申请人申请企业名称变更、生产地址名称变更等不影响产品配方科学性、安全性的，审评机构应当进行核实，并自受理机构受理之日起10个工作日内作出结论。申请人名称变更的，应当由变更后的申请人申请变更。 国家食品药品监督管理总局自接到审评结论之日起10个工作日内根据审评结论作出准予变更或者不予变更的决定。对符合条件的，依法办理变更手续，注册证书发证日期以变更批准日期为准，原注册号不变，证书有效期保持不变；不予变更注册的，作出不予变更注册决定。"},{"i":27,"n":"第二十七条","txt":"婴幼儿配方乳粉产品配方注册证书有效期届满需要延续的，申请人应当在注册证书有效期届满6个月前向国家食品药品监督管理总局提出延续注册申请，并提交下列材料： （一）婴幼儿配方乳粉产品配方延续注册申请书； （二）申请人主体资质证明文件； （三）企业研发能力、生产能力、检验能力情况； （四）企业生产质量管理体系自查报告； （五）产品营养、安全方面的跟踪评价情况； （六）生产企业所在地省、自治区、直辖市食品药品监督管理部门延续注册意见书； （七）婴幼儿配方乳粉产品配方注册证书及附件。 审评机构应当根据实际需要对延续注册申请按照本办法第十三条组织开展审评，并作出审评结论。 国家食品药品监督管理总局自受理申请之日起20个工作日内作出准予延续注册或者不予延续注册的决定。准予延续注册的，向申请人换发注册证书，原注册号不变，证书有效期自批准之日起重新计算；不予延续注册的，应当作出不予延续注册决定。逾期未作决"},{"i":28,"n":"第二十八条","txt":"有下列情形之一的，不予延续注册： （一）未在规定时限内提出延续注册申请的； （二）申请人在产品配方注册后5年内未按照注册配方组织生产的； （三）企业未能保持注册时研发能力、生产能力、检验能力的； （四）其他不符合有关规定的情形。"},{"i":29,"n":"第二十九条","txt":"婴幼儿配方乳粉产品配方变更注册与延续注册的程序未作规定的，适用本办法有关婴幼儿乳粉产品配方注册的相关规定。"},{"i":30,"n":"第三十条","txt":"申请人申请婴幼儿配方乳粉产品配方注册的，应当提交标签和说明书样稿及标签、说明书中声称的说明、证明材料。 标签和说明书涉及婴幼儿配方乳粉产品配方的，应当与获得注册的产品配方的内容一致，并标注注册号。"},{"i":31,"n":"第三十一条","txt":"产品名称中有动物性来源的，应当根据产品配方在配料表中如实标明使用的生乳、乳粉、乳清（蛋白）粉等乳制品原料的动物性来源。使用的乳制品原料有两种以上动物性来源时，应当标明各种动物性来源原料所占比例。 配料表应当将食用植物油具体的品种名称按照加入量的递减顺序标注。 营养成分表应当按照婴幼儿配方乳粉食品安全国家标准规定的营养素顺序列出，并按照能量、蛋白质、脂肪、碳水化合物、维生素、矿物质、可选择性成分等类别分类列出。"},{"i":32,"n":"第三十二条","txt":"声称生乳、原料乳粉等原料来源的，应当如实标明具体来源地或者来源国，不得使用“进口奶源”“源自国外牧场”“生态牧场”“进口原料”等模糊信息。"},{"i":33,"n":"第三十三条","txt":"声称应当注明婴幼儿配方乳粉适用月龄，可以同时使用“1段、2段、3段”的方式标注。"},{"i":34,"n":"第三十四条","txt":"标签和说明书不得含有下列内容： （一）涉及疾病预防、治疗功能； （二）明示或者暗示具有保健作用； （三）明示或者暗示具有益智、增加抵抗力或者免疫力、保护肠道等功能性表述； （四）对于按照食品安全标准不应当在产品配方中含有或者使用的物质，以“不添加”“不含有”“零添加”等字样强调未使用或者不含有； （五）虚假、夸大、违反科学原则或者绝对化的内容； （六）与产品配方注册的内容不一致的声称。"},{"i":35,"n":"第三十五条","txt":"承担婴幼儿配方乳粉产品配方注册技术审评、现场核查、抽样检验、专家论证的机构和人员应当对出具的审评结论、现场核查报告、产品检验报告、专家意见等负责。 婴幼儿配方乳粉产品配方注册技术审评、现场核查、抽样检验、专家论证的机构和人员应当依照有关法律、法规、规章的规定，恪守职业道德，按照食品安全国家标准、技术规范等对婴幼儿配方乳粉产品配方进行技术审评、现场核查和抽样检验，保证相关工作科学、客观和公正。"},{"i":36,"n":"第三十六条","txt":"食品药品监督管理部门接到有关单位或者个人举报的婴幼儿配方乳粉产品配方注册受理、技术审评、现场核查、抽样检验、专家论证、审批等工作中的违法违规行为，应当及时核实处理。"},{"i":37,"n":"第三十七条","txt":"国家食品药品监督管理总局自批准之日起20个工作日内公布婴幼儿配方乳粉产品配方注册目录信息。"},{"i":38,"n":"第三十八条","txt":"参与婴幼儿配方乳粉注册申请受理、技术审评、现场核查、抽样检验、专家论证等工作的机构和人员，应当保守在注册中知悉的商业秘密。 申请人应当按照国家有关规定对申请材料中的商业秘密进行标注并注明依据。"},{"i":39,"n":"第三十九条","txt":"申请人拒绝现场核查或者抽样检验的，国家食品药品监督管理总局不批准其产品配方注册申请。"},{"i":40,"n":"第四十条","txt":"有下列情形之一的，国家食品药品监督管理总局依据职权或者根据利害关系人的请求，可以撤销婴幼儿配方乳粉产品配方注册： （一）工作人员滥用职权、玩忽职守作出准予注册决定的； （二）超越法定职权作出准予注册决定的； （三）违反法定程序作出准予注册决定的； （四）对不具备申请资格或者不符合法定条件的申请人准予注册的； （五）依法可以撤销注册的其他情形。"},{"i":41,"n":"第四十一条","txt":"有下列情形之一的，由国家食品药品监督管理总局注销婴幼儿配方乳粉产品配方注册： （一）企业申请注销的； （二）企业依法终止的； （三）注册证书有效期届满未延续的； （四）注册依法被撤销、撤回，或者注册证书依法被吊销的； （五）法律法规规定应当注销的其他情形。"},{"i":42,"n":"第四十二条","txt":"食品安全法等法律法规对婴幼儿配方乳粉产品配方注册违法行为已有规定的，从其规定。"},{"i":43,"n":"第四十三条","txt":"申请人隐瞒有关情况或者提供虚假材料、样品申请婴幼儿配方乳粉产品配方注册的，国家食品药品监督管理总局不予受理或者不予注册，对申请人给予警告，并向社会公告。申请人在1年内不得再次申请婴幼儿配方乳粉产品配方注册；涉嫌犯罪的，依法移送公安机关，追究刑事责任。 申请人以欺骗、贿赂等不正当手段，或者隐瞒真实情况、提交虚假材料等方式取得婴幼儿配方乳粉产品配方注册证书的，国家食品药品监督管理总局依法予以撤销，处1万元以上3万元以下罚款。被许可人在3年内不得再次申请注册；涉嫌犯罪的，依法移送公安机关，追究刑事责任。"},{"i":44,"n":"第四十四条","txt":"申请人变更不影响产品配方科学性、安全性的事项，未依法申请变更的，由县级以上食品药品监督管理部门责令改正，给予警告；拒不改正的，处1万元以上3万元以下罚款。 申请人变更可能影响产品配方科学性、安全性的事项，未依法申请变更的，由县级以上食品药品监督管理部门依照食品安全法第一百二十四条的规定处罚。"},{"i":45,"n":"第四十五条","txt":"伪造、涂改、倒卖、出租、出借、转让婴幼儿配方乳粉产品配方注册证书的，由县级以上食品药品监督管理部门责令改正，给予警告，并处1万元以下罚款；情节严重的，处1万元以上3万元以下罚款；涉嫌犯罪的，依法移送公安机关，追究刑事责任。"},{"i":46,"n":"第四十六条","txt":"婴幼儿配方乳粉生产销售者违反本办法第三十条至第三十四条规定的，由食品药品监督管理部门责令改正，并依法处以1万元以上3万元以下罚款。"},{"i":47,"n":"第四十七条","txt":"食品药品监督管理部门及其工作人员对不符合条件的申请人准予注册，或者超越法定职权准予注册的，依照食品安全法第一百四十四条的规定处理。 食品药品监督管理部门及其工作人员在注册审评过程中滥用职权、玩忽职守、徇私舞弊的，依照食品安全法第一百四十五条的规定处理。"},{"i":48,"n":"第四十八条","txt":"本办法所称婴幼儿配方乳粉产品配方，是指生产婴幼儿配方乳粉使用的食品原料、食品添加剂及其使用量，以及产品中营养成分的含量。"},{"i":49,"n":"第四十九条","txt":"本办法自2016年10月1日起施行。"}],"teshuyixueyongtupeifangshipinzhuceguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范特殊医学用途配方食品注册行为，加强注册管理，保证特殊医学用途配方食品质量安全，根据《中华人民共和国食品安全法》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内生产销售和进口的特殊医学用途配方食品的注册管理，适用本办法。"},{"i":3,"n":"第三条","txt":"特殊医学用途配方食品注册，是指国家食品药品监督管理总局根据申请，依照本办法规定的程序和要求，对特殊医学用途配方食品的产品配方、生产工艺、标签、说明书以及产品安全性、营养充足性和特殊医学用途临床效果进行审查，并决定是否准予注册的过程。"},{"i":4,"n":"第四条","txt":"特殊医学用途配方食品注册管理，应当遵循科学、公开、公平、公正的原则。"},{"i":5,"n":"第五条","txt":"国家食品药品监督管理总局负责特殊医学用途配方食品的注册管理工作。 国家食品药品监督管理总局行政受理机构（以下简称受理机构）负责特殊医学用途配方食品注册申请的受理工作。 国家食品药品监督管理总局食品审评机构（以下简称审评机构）负责特殊医学用途配方食品注册申请的审评工作。 国家食品药品监督管理总局审核查验机构（以下简称核查机构）负责特殊医学用途配方食品注册审评过程中的现场核查工作。"},{"i":6,"n":"第六条","txt":"国家食品药品监督管理总局组建由食品营养、临床医学、食品安全、食品加工等领域专家组成的特殊医学用途配方食品注册审评专家库。"},{"i":7,"n":"第七条","txt":"国家食品药品监督管理总局应当加强信息化建设，提高特殊医学用途配方食品注册管理信息化水平。"},{"i":8,"n":"第八条","txt":"特殊医学用途配方食品注册申请人（以下简称申请人）应当为拟在我国境内生产并销售特殊医学用途配方食品的生产企业和拟向我国境内出口特殊医学用途配方食品的境外生产企业。 申请人应当具备与所生产特殊医学用途配方食品相适应的研发、生产能力，设立特殊医学用途配方食品研发机构，配备专职的产品研发人员、食品安全管理人员和食品安全专业技术人员，按照良好生产规范要求建立与所生产食品相适应的生产质量管理体系，具备按照特殊医学用途配方食品国家标准规定的全部项目逐批检验的能力。 研发机构中应当有食品相关专业高级职称或者相应专业能力的人员。"},{"i":9,"n":"第九条","txt":"申请特殊医学用途配方食品注册，应当向国家食品药品监督管理总局提交下列材料： （一）特殊医学用途配方食品注册申请书； （二）产品研发报告和产品配方设计及其依据； （三）生产工艺资料； （四）产品标准要求； （五）产品标签、说明书样稿； （六）试验样品检验报告； （七）研发、生产和检验能力证明材料； （八）其他表明产品安全性、营养充足性以及特殊医学用途临床效果的材料。 申请特定全营养配方食品注册，还应当提交临床试验报告。 申请人应当对其申请材料的真实性负责。"},{"i":10,"n":"第十条","txt":"受理机构对申请人提出的特殊医学用途配方食品注册申请，应当根据下列情况分别作出处理： （一）申请事项依法不需要进行注册的，应当即时告知申请人不受理； （二）申请事项依法不属于国家食品药品监督管理总局职权范围的，应当即时作出不予受理的决定，并告知申请人向有关行政机关申请； （三）申请材料存在可以当场更正的错误的，应当允许申请人当场更正； （四）申请材料不齐全或者不符合法定形式的，应当当场或者在5个工作日内一次告知申请人需要补正的全部内容，逾期不告知的，自收到申请材料之日起即为受理； （五）申请事项属于国家食品药品监督管理总局职权范围，申请材料齐全、符合法定形式，或者申请人按照要求提交全部补正申请材料的，应当受理注册申请。 受理机构受理或者不予受理注册申请，应当出具加盖国家食品药品监督管理总局行政许可受理专用章和注明日期的书面凭证。"},{"i":11,"n":"第十一条","txt":"审评机构应当对申请材料进行审查，并根据实际需要组织对申请人进行现场核查、对试验样品进行抽样检验、对临床试验进行现场核查和对专业问题进行专家论证。"},{"i":12,"n":"第十二条","txt":"核查机构应当自接到审评机构通知之日起20个工作日内完成对申请人的研发能力、生产能力、检验能力等情况的现场核查，并出具核查报告。 核查机构应当通知申请人所在地省级食品药品监督管理部门参与现场核查，省级食品药品监督管理部门应当派员参与现场核查。"},{"i":13,"n":"第十三条","txt":"审评机构应当委托具有法定资质的食品检验机构进行抽样检验。 检验机构应当自接受委托之日起30个工作日内完成抽样检验。"},{"i":14,"n":"第十四条","txt":"核查机构应当自接到审评机构通知之日起40个工作日内完成对临床试验的真实性、完整性、准确性等情况的现场核查，并出具核查报告。"},{"i":15,"n":"第十五条","txt":"审评机构可以从特殊医学用途配方食品注册审评专家库中选取专家，对审评过程中遇到的问题进行论证，并形成专家意见。"},{"i":16,"n":"第十六条","txt":"审评机构应当自收到受理材料之日起60个工作日内根据核查报告、检验报告以及专家意见完成技术审评工作，并作出审查结论。 审评过程中需要申请人补正材料的，审评机构应当一次告知需要补正的全部内容。申请人应当在6个月内一次补正材料。补正材料的时间不计算在审评时间内。 特殊情况下需要延长审评时间的，经审评机构负责人同意，可以延长30个工作日，延长决定应当及时书面告知申请人。"},{"i":17,"n":"第十七条","txt":"审评机构认为申请材料真实，产品科学、安全，生产工艺合理、可行和质量可控，技术要求和检验方法科学、合理的，应当提出予以注册的建议。 审评机构提出不予注册建议的，应当向申请人发出拟不予注册的书面通知。申请人对通知有异议的，应当自收到通知之日起20个工作日内向审评机构提出书面复审申请并说明复审理由。复审的内容仅限于原申请事项及申请材料。 审评机构应当自受理复审申请之日起30个工作日内作出复审决定。改变不予注册建议的，应当书面通知注册申请人。"},{"i":18,"n":"第十八条","txt":"国家食品药品监督管理总局应当自受理申请之日起20个工作日内对特殊医学用途配方食品注册申请作出是否准予注册的决定。 现场核查、抽样检验、复审所需要的时间不计算在审评和注册决定的期限内。 对于申请进口特殊医学用途配方食品注册的，应当根据境外生产企业的实际情况，确定境外现场核查和抽样检验时限。"},{"i":19,"n":"第十九条","txt":"国家食品药品监督管理总局作出准予注册决定的，受理机构自决定之日起10个工作日内颁发、送达特殊医学用途配方食品注册证书；作出不予注册决定的，应当说明理由，受理机构自决定之日起10个工作日内发出特殊医学用途配方食品不予注册决定，并告知申请人享有依法申请行政复议或者提起行政诉讼的权利。 特殊医学用途配方食品注册证书有效期限为5年。"},{"i":20,"n":"第二十条","txt":"特殊医学用途配方食品注册证书及附件应当载明下列事项： （一）产品名称； （二）企业名称、生产地址； （三）注册号及有效期； （四）产品类别； （五）产品配方； （六）生产工艺； （七）产品标签、说明书。 特殊医学用途配方食品注册号的格式为：国食注字TY+4位年号+4位顺序号，其中TY代表特殊医学用途配方食品。"},{"i":21,"n":"第二十一条","txt":"申请人需要变更特殊医学用途配方食品注册证书及其附件载明事项的，应当向国家食品药品监督管理总局提出变更注册申请，并提交下列材料： （一）特殊医学用途配方食品变更注册申请书； （二）变更注册证书及其附件载明事项的证明材料。"},{"i":22,"n":"第二十二条","txt":"申请人变更产品配方、生产工艺等可能影响产品安全性、营养充足性以及特殊医学用途临床效果的事项，国家食品药品监督管理总局应当进行实质性审查，并在本办法第十八条规定的期限内完成变更注册工作。 申请人变更企业名称、生产地址名称等不影响产品安全性、营养充足性以及特殊医学用途临床效果的事项，国家食品药品监督管理总局应当进行核实，并自受理之日起10个工作日内作出是否准予变更注册的决定。"},{"i":23,"n":"第二十三条","txt":"国家食品药品监督管理总局准予变更注册申请的，向申请人换发注册证书，原注册号不变，证书有效期不变；不予批准变更注册申请的，应当作出不予变更注册决定。"},{"i":24,"n":"第二十四条","txt":"特殊医学用途配方食品注册证书有效期届满，需要继续生产或者进口的，应当在有效期届满6个月前，向国家食品药品监督管理总局提出延续注册申请，并提交下列材料： （一）特殊医学用途配方食品延续注册申请书； （二）特殊医学用途配方食品质量安全管理情况； （三）特殊医学用途配方食品质量管理体系自查报告； （四）特殊医学用途配方食品跟踪评价情况。"},{"i":25,"n":"第二十五条","txt":"国家食品药品监督管理总局根据需要对延续注册申请进行实质性审查，并在本办法第十八条规定的期限内完成延续注册工作。逾期未作决定的，视为准予延续。"},{"i":26,"n":"第二十六条","txt":"国家食品药品监督管理总局准予延续注册的，向申请人换发注册证书，原注册号不变，证书有效期自批准之日起重新计算；不批准延续注册申请的，应当作出不予延续注册决定。"},{"i":27,"n":"第二十七条","txt":"有下列情形之一的，不予延续注册： （一）注册人未在规定时间内提出延续注册申请的； （二）注册产品连续12个月内在省级以上监督抽检中出现3批次以上不合格的； （三）企业未能保持注册时生产、检验能力的； （四）其他不符合法律法规以及产品安全性、营养充足性和特殊医学用途临床效果要求的情形。"},{"i":28,"n":"第二十八条","txt":"特殊医学用途配方食品变更注册与延续注册程序，本节未作规定的，适用本章第一节、第二节的相关规定。"},{"i":29,"n":"第二十九条","txt":"特定全营养配方食品需要进行临床试验的，由申请人委托符合要求的临床试验机构出具临床试验报告。临床试验报告应当包括完整的统计分析报告和数据。"},{"i":30,"n":"第三十条","txt":"临床试验应当按照特殊医学用途配方食品临床试验质量管理规范开展。 特殊医学用途配方食品临床试验质量管理规范由国家食品药品监督管理总局发布。"},{"i":31,"n":"第三十一条","txt":"申请人组织开展多中心临床试验的，应当明确组长单位和统计单位。"},{"i":32,"n":"第三十二条","txt":"申请人应当对用于临床试验的试验样品和对照样品的质量安全负责。 用于临床试验的试验样品应当由申请人生产并经检验合格，生产条件应当符合特殊医学用途配方食品良好生产规范。"},{"i":33,"n":"第三十三条","txt":"特殊医学用途配方食品的标签，应当依照法律、法规、规章和食品安全国家标准的规定进行标注。"},{"i":34,"n":"第三十四条","txt":"特殊医学用途配方食品的标签和说明书的内容应当一致，涉及特殊医学用途配方食品注册证书内容的，应当与注册证书内容一致，并标明注册号。 标签已经涵盖说明书全部内容的，可以不另附说明书。"},{"i":35,"n":"第三十五条","txt":"特殊医学用途配方食品标签、说明书应当真实准确、清晰持久、醒目易读。"},{"i":36,"n":"第三十六条","txt":"特殊医学用途配方食品标签、说明书不得含有虚假内容，不得涉及疾病预防、治疗功能。生产企业对其提供的标签、说明书的内容负责。"},{"i":37,"n":"第三十七条","txt":"特殊医学用途配方食品的名称应当反映食品的真实属性，使用食品安全国家标准规定的分类名称或者等效名称。"},{"i":38,"n":"第三十八条","txt":"特殊医学用途配方食品标签、说明书应当按照食品安全国家标准的规定在醒目位置标示下列内容： （一）请在医生或者临床营养师指导下使用； （二）不适用于非目标人群使用； （三）本品禁止用于肠外营养支持和静脉注射。"},{"i":39,"n":"第三十九条","txt":"特殊医学用途配方食品生产企业应当按照批准注册的产品配方、生产工艺等技术要求组织生产，保证特殊医学用途配方食品安全。 特殊医学用途配方食品生产企业提出的变更注册申请未经批准前，应当严格按照已经批准的注册证书及其附件载明的内容组织生产，不得擅自改变生产条件和要求。 特殊医学用途配方食品生产企业提出的变更注册申请经批准后，应当严格按照变更后的特殊医学用途配方食品注册证书及其附件载明的内容组织生产。"},{"i":40,"n":"第四十条","txt":"参与特殊医学用途配方食品注册申请受理、技术审评、现场核查、抽样检验、临床试验等工作的人员和专家，应当保守注册中知悉的商业秘密。 申请人应当按照国家有关规定对申请材料中的商业秘密进行标注并注明依据。"},{"i":41,"n":"第四十一条","txt":"有下列情形之一的，国家食品药品监督管理总局根据利害关系人的请求或者依据职权，可以撤销特殊医学用途配方食品注册： （一）工作人员滥用职权、玩忽职守作出准予注册决定的； （二）超越法定职权作出准予注册决定的； （三）违反法定程序作出准予注册决定的； （四）对不具备申请资格或者不符合法定条件的申请人准予注册的； （五）食品生产许可证被吊销的； （六）依法可以撤销注册的其他情形。"},{"i":42,"n":"第四十二条","txt":"有下列情形之一的，国家食品药品监督管理总局应当依法办理特殊医学用途配方食品注册注销手续： （一）企业申请注销的； （二）有效期届满未延续的； （三）企业依法终止的； （四）注册依法被撤销、撤回，或者注册证书依法被吊销的； （五）法律法规规定应当注销注册的其他情形。"},{"i":43,"n":"第四十三条","txt":"申请人隐瞒真实情况或者提供虚假材料申请注册的，国家食品药品监督管理总局不予受理或者不予注册，并给予警告；申请人在1年内不得再次申请注册。"},{"i":44,"n":"第四十四条","txt":"被许可人以欺骗、贿赂等不正当手段取得注册证书的，由国家食品药品监督管理总局撤销注册证书，并处1万元以上3万元以下罚款；申请人在3年内不得再次申请注册。"},{"i":45,"n":"第四十五条","txt":"伪造、涂改、倒卖、出租、出借、转让特殊医学用途配方食品注册证书的，由县级以上食品药品监督管理部门责令改正，给予警告，并处1万元以下罚款；情节严重的，处1万元以上3万元以下罚款。"},{"i":46,"n":"第四十六条","txt":"注册人变更不影响产品安全性、营养充足性以及特殊医学用途临床效果的事项，未依法申请变更的，由县级以上食品药品监督管理部门责令改正，给予警告；拒不改正的，处1万元以上3万元以下罚款。 注册人变更产品配方、生产工艺等影响产品安全性、营养充足性以及特殊医学用途临床效果的事项，未依法申请变更的，由县级以上食品药品监督管理部门依照食品安全法第一百二十四条第一款的规定进行处罚。"},{"i":47,"n":"第四十七条","txt":"食品药品监督管理部门及其工作人员对不符合条件的申请人准予注册，或者超越法定职权准予注册的，依照食品安全法第一百四十四条的规定给予处理。 食品药品监督管理部门及其工作人员在注册审批过程中滥用职权、玩忽职守、徇私舞弊的，依照食品安全法第一百四十五条的规定给予处理。"},{"i":48,"n":"第四十八条","txt":"特殊医学用途配方食品，是指为满足进食受限、消化吸收障碍、代谢紊乱或者特定疾病状态人群对营养素或者膳食的特殊需要，专门加工配制而成的配方食品，包括适用于0月龄至12月龄的特殊医学用途婴儿配方食品和适用于1岁以上人群的特殊医学用途配方食品。"},{"i":49,"n":"第四十九条","txt":"适用于0月龄至12月龄的特殊医学用途婴儿配方食品包括无乳糖配方食品或者低乳糖配方食品、乳蛋白部分水解配方食品、乳蛋白深度水解配方食品或者氨基酸配方食品、早产或者低出生体重婴儿配方食品、氨基酸代谢障碍配方食品和母乳营养补充剂等。"},{"i":50,"n":"第五十条","txt":"适用于1岁以上人群的特殊医学用途配方食品，包括全营养配方食品、特定全营养配方食品、非全营养配方食品。 全营养配方食品，是指可以作为单一营养来源满足目标人群营养需求的特殊医学用途配方食品。 特定全营养配方食品，是指可以作为单一营养来源满足目标人群在特定疾病或者医学状况下营养需求的特殊医学用途配方食品。常见特定全营养配方食品有：糖尿病全营养配方食品，呼吸系统疾病全营养配方食品，肾病全营养配方食品，肿瘤全营养配方食品，肝病全营养配方食品，肌肉衰减综合征全营养配方食品，创伤、感染、手术及其他应激状态全营养配方食品，炎性肠病全营养配方食品，食物蛋白过敏全营养配方食品，难治性癫痫全营养配方食品，胃肠道吸收障碍、胰腺炎全营养配方食品，脂肪酸代谢异常全营养配方食品，肥胖、减脂手术全营养配方食品。 非全营养配方食品，是指可以满足目标人群部分营养需求的特殊医学用途配方食品，不适用于作为单一营养来源。常见非"},{"i":51,"n":"第五十一条","txt":"医疗机构配制供病人食用的营养餐不适用本办法。"},{"i":52,"n":"第五十二条","txt":"本办法自2016年7月1日起施行。"}],"wangluoshipinanquanweifaxingweichachubanfa":[{"i":1,"n":"第一条","txt":"为依法查处网络食品安全违法行为，加强网络食品安全监督管理，保证食品安全，根据《中华人民共和国食品安全法》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内网络食品交易第三方平台提供者以及通过第三方平台或者自建的网站进行交易的食品生产经营者（以下简称入网食品生产经营者）违反食品安全法律、法规、规章或者食品安全标准行为的查处，适用本办法。"},{"i":3,"n":"第三条","txt":"国家市场监督管理总局负责监督指导全国网络食品安全违法行为查处工作。 县级以上地方市场监督管理部门负责本行政区域内网络食品安全违法行为查处工作。"},{"i":4,"n":"第四条","txt":"网络食品交易第三方平台提供者和入网食品生产经营者应当履行法律、法规和规章规定的食品安全义务。 网络食品交易第三方平台提供者和入网食品生产经营者应当对网络食品安全信息的真实性负责。"},{"i":5,"n":"第五条","txt":"网络食品交易第三方平台提供者和入网食品生产经营者应当配合市场监督管理部门对网络食品安全违法行为的查处，按照市场监督管理部门的要求提供网络食品交易相关数据和信息。"},{"i":6,"n":"第六条","txt":"鼓励网络食品交易第三方平台提供者和入网食品生产经营者开展食品安全法律、法规以及食品安全标准和食品安全知识的普及工作。"},{"i":7,"n":"第七条","txt":"任何组织或者个人均可向市场监督管理部门举报网络食品安全违法行为。"},{"i":8,"n":"第八条","txt":"网络食品交易第三方平台提供者应当在通信主管部门批准后30个工作日内，向所在地省级市场监督管理部门备案，取得备案号。 通过自建网站交易的食品生产经营者应当在通信主管部门批准后30个工作日内，向所在地市、县级市场监督管理部门备案，取得备案号。 省级和市、县级市场监督管理部门应当自完成备案后7个工作日内向社会公开相关备案信息。 备案信息包括域名、IP地址、电信业务经营许可证、企业名称、法定代表人或者负责人姓名、备案号等。"},{"i":9,"n":"第九条","txt":"网络食品交易第三方平台提供者和通过自建网站交易的食品生产经营者应当具备数据备份、故障恢复等技术条件，保障网络食品交易数据和资料的可靠性与安全性。"},{"i":10,"n":"第十条","txt":"网络食品交易第三方平台提供者应当建立入网食品生产经营者审查登记、食品安全自查、食品安全违法行为制止及报告、严重违法行为平台服务停止、食品安全投诉举报处理等制度，并在网络平台上公开。"},{"i":11,"n":"第十一条","txt":"网络食品交易第三方平台提供者应当对入网食品生产经营者食品生产经营许可证、入网食品添加剂生产企业生产许可证等材料进行审查，如实记录并及时更新。 网络食品交易第三方平台提供者应当对入网食用农产品生产经营者营业执照、入网食品添加剂经营者营业执照以及入网交易食用农产品的个人的身份证号码、住址、联系方式等信息进行登记，如实记录并及时更新。"},{"i":12,"n":"第十二条","txt":"网络食品交易第三方平台提供者应当建立入网食品生产经营者档案，记录入网食品生产经营者的基本情况、食品安全管理人员等信息。"},{"i":13,"n":"第十三条","txt":"网络食品交易第三方平台提供者和通过自建网站交易食品的生产经营者应当记录、保存食品交易信息，保存时间不得少于产品保质期满后6个月；没有明确保质期的，保存时间不得少于2年。"},{"i":14,"n":"第十四条","txt":"网络食品交易第三方平台提供者应当设置专门的网络食品安全管理机构或者指定专职食品安全管理人员，对平台上的食品经营行为及信息进行检查。 网络食品交易第三方平台提供者发现存在食品安全违法行为的，应当及时制止，并向所在地县级市场监督管理部门报告。"},{"i":15,"n":"第十五条","txt":"网络食品交易第三方平台提供者发现入网食品生产经营者有下列严重违法行为之一的，应当停止向其提供网络交易平台服务： （一）入网食品生产经营者因涉嫌食品安全犯罪被立案侦查或者提起公诉的； （二）入网食品生产经营者因食品安全相关犯罪被人民法院判处刑罚的； （三）入网食品生产经营者因食品安全违法行为被公安机关拘留或者给予其他治安管理处罚的； （四）入网食品生产经营者被市场监督管理部门依法作出吊销许可证、责令停产停业等处罚的。"},{"i":16,"n":"第十六条","txt":"入网食品生产经营者应当依法取得许可，入网食品生产者应当按照许可的类别范围销售食品，入网食品经营者应当按照许可的经营项目范围从事食品经营。法律、法规规定不需要取得食品生产经营许可的除外。 取得食品生产许可的食品生产者，通过网络销售其生产的食品，不需要取得食品经营许可。取得食品经营许可的食品经营者通过网络销售其制作加工的食品，不需要取得食品生产许可。"},{"i":17,"n":"第十七条","txt":"入网食品生产经营者不得从事下列行为： （一）网上刊载的食品名称、成分或者配料表、产地、保质期、贮存条件，生产者名称、地址等信息与食品标签或者标识不一致。 （二）网上刊载的非保健食品信息明示或者暗示具有保健功能；网上刊载的保健食品的注册证书或者备案凭证等信息与注册或者备案信息不一致。 （三）网上刊载的婴幼儿配方乳粉产品信息明示或者暗示具有益智、增加抵抗力、提高免疫力、保护肠道等功能或者保健作用。 （四）对在贮存、运输、食用等方面有特殊要求的食品，未在网上刊载的食品信息中予以说明和提示。 （五）法律、法规规定禁止从事的其他行为。"},{"i":18,"n":"第十八条","txt":"通过第三方平台进行交易的食品生产经营者应当在其经营活动主页面显著位置公示其食品生产经营许可证。通过自建网站交易的食品生产经营者应当在其网站首页显著位置公示营业执照、食品生产经营许可证。 餐饮服务提供者还应当同时公示其餐饮服务食品安全监督量化分级管理信息。相关信息应当画面清晰，容易辨识。"},{"i":19,"n":"第十九条","txt":"入网销售保健食品、特殊医学用途配方食品、婴幼儿配方乳粉的食品生产经营者，除依照本办法第十八条的规定公示相关信息外，还应当依法公示产品注册证书或者备案凭证，持有广告审查批准文号的还应当公示广告审查批准文号，并链接至市场监督管理部门网站对应的数据查询页面。保健食品还应当显著标明“本品不能代替药物”。 特殊医学用途配方食品中特定全营养配方食品不得进行网络交易。"},{"i":20,"n":"第二十条","txt":"网络交易的食品有保鲜、保温、冷藏或者冷冻等特殊贮存条件要求的，入网食品生产经营者应当采取能够保证食品安全的贮存、运输措施，或者委托具备相应贮存、运输能力的企业贮存、配送。"},{"i":21,"n":"第二十一条","txt":"对网络食品交易第三方平台提供者食品安全违法行为的查处，由网络食品交易第三方平台提供者所在地县级以上地方市场监督管理部门管辖。 对网络食品交易第三方平台提供者分支机构的食品安全违法行为的查处，由网络食品交易第三方平台提供者所在地或者分支机构所在地县级以上地方市场监督管理部门管辖。 对入网食品生产经营者食品安全违法行为的查处，由入网食品生产经营者所在地或者生产经营场所所在地县级以上地方市场监督管理部门管辖；对应当取得食品生产经营许可而没有取得许可的违法行为的查处，由入网食品生产经营者所在地、实际生产经营地县级以上地方市场监督管理部门管辖。 因网络食品交易引发食品安全事故或者其他严重危害后果的，也可以由网络食品安全违法行为发生地或者违法行为结果地的县级以上地方市场监督管理部门管辖。"},{"i":22,"n":"第二十二条","txt":"两个以上市场监督管理部门都有管辖权的网络食品安全违法案件，由最先立案查处的市场监督管理部门管辖。对管辖有争议的，由双方协商解决。协商不成的，报请共同的上一级市场监督管理部门指定管辖。"},{"i":23,"n":"第二十三条","txt":"消费者因网络食品安全违法问题进行投诉举报的，由网络食品交易第三方平台提供者所在地、入网食品生产经营者所在地或者生产经营场所所在地等县级以上地方市场监督管理部门处理。"},{"i":24,"n":"第二十四条","txt":"县级以上地方市场监督管理部门，对网络食品安全违法行为进行调查处理时，可以行使下列职权： （一）进入当事人网络食品交易场所实施现场检查； （二）对网络交易的食品进行抽样检验； （三）询问有关当事人，调查其从事网络食品交易行为的相关情况； （四）查阅、复制当事人的交易数据、合同、票据、账簿以及其他相关资料； （五）调取网络交易的技术监测、记录资料； （六）法律、法规规定可以采取的其他措施。"},{"i":25,"n":"第二十五条","txt":"县级以上市场监督管理部门通过网络购买样品进行检验的，应当按照相关规定填写抽样单，记录抽检样品的名称、类别以及数量，购买样品的人员以及付款账户、注册账号、收货地址、联系方式，并留存相关票据。买样人员应当对网络购买样品包装等进行查验，对样品和备份样品分别封样，并采取拍照或者录像等手段记录拆封过程。"},{"i":26,"n":"第二十六条","txt":"检验结果不符合食品安全标准的，市场监督管理部门应当按照有关规定及时将检验结果通知被抽样的入网食品生产经营者。入网食品生产经营者应当采取停止生产经营、封存不合格食品等措施，控制食品安全风险。 通过网络食品交易第三方平台购买样品的，应当同时将检验结果通知网络食品交易第三方平台提供者。网络食品交易第三方平台提供者应当依法制止不合格食品的销售。 入网食品生产经营者联系方式不详的，网络食品交易第三方平台提供者应当协助通知。入网食品生产经营者无法联系的，网络食品交易第三方平台提供者应当停止向其提供网络食品交易平台服务。"},{"i":27,"n":"第二十七条","txt":"网络食品交易第三方平台提供者和入网食品生产经营者有下列情形之一的，县级以上市场监督管理部门可以对其法定代表人或者主要负责人进行责任约谈： （一）发生食品安全问题，可能引发食品安全风险蔓延的； （二）未及时妥善处理投诉举报的食品安全问题，可能存在食品安全隐患的； （三）未及时采取有效措施排查、消除食品安全隐患，落实食品安全责任的； （四）县级以上市场监督管理部门认为需要进行责任约谈的其他情形。 责任约谈不影响市场监督管理部门依法对其进行行政处理，责任约谈情况及后续处理情况应当向社会公开。 被约谈者无正当理由未按照要求落实整改的，县级以上地方市场监督管理部门应当增加监督检查频次。"},{"i":28,"n":"第二十八条","txt":"食品安全法等法律法规对网络食品安全违法行为已有规定的，从其规定。"},{"i":29,"n":"第二十九条","txt":"违反本办法第八条规定，网络食品交易第三方平台提供者和通过自建网站交易的食品生产经营者未履行相应备案义务的，由县级以上地方市场监督管理部门责令改正，给予警告；拒不改正的，处5000元以上3万元以下罚款。"},{"i":30,"n":"第三十条","txt":"违反本办法第九条规定，网络食品交易第三方平台提供者和通过自建网站交易的食品生产经营者不具备数据备份、故障恢复等技术条件，不能保障网络食品交易数据和资料的可靠性与安全性的，由县级以上地方市场监督管理部门责令改正，给予警告；拒不改正的，处3万元罚款。"},{"i":31,"n":"第三十一条","txt":"违反本办法第十条规定，网络食品交易第三方平台提供者未按要求建立入网食品生产经营者审查登记、食品安全自查、食品安全违法行为制止及报告、严重违法行为平台服务停止、食品安全投诉举报处理等制度的或者未公开以上制度的，由县级以上地方市场监督管理部门责令改正，给予警告；拒不改正的，处5000元以上3万元以下罚款。"},{"i":32,"n":"第三十二条","txt":"违反本办法第十一条规定，网络食品交易第三方平台提供者未对入网食品生产经营者的相关材料及信息进行审查登记、如实记录并更新的，由县级以上地方市场监督管理部门依照食品安全法第一百三十一条的规定处罚。"},{"i":33,"n":"第三十三条","txt":"违反本办法第十二条规定，网络食品交易第三方平台提供者未建立入网食品生产经营者档案、记录入网食品生产经营者相关信息的，由县级以上地方市场监督管理部门责令改正，给予警告；拒不改正的，处5000元以上3万元以下罚款。"},{"i":34,"n":"第三十四条","txt":"违反本办法第十三条规定，网络食品交易第三方平台提供者未按要求记录、保存食品交易信息的，由县级以上地方市场监督管理部门责令改正，给予警告；拒不改正的，处5000元以上3万元以下罚款。"},{"i":35,"n":"第三十五条","txt":"违反本办法第十四条规定，网络食品交易第三方平台提供者未设置专门的网络食品安全管理机构或者指定专职食品安全管理人员对平台上的食品安全经营行为及信息进行检查的，由县级以上地方市场监督管理部门责令改正，给予警告；拒不改正的，处5000元以上3万元以下罚款。"},{"i":36,"n":"第三十六条","txt":"违反本办法第十五条规定，网络食品交易第三方平台提供者发现入网食品生产经营者有严重违法行为未停止提供网络交易平台服务的，由县级以上地方市场监督管理部门依照食品安全法第一百三十一条的规定处罚。"},{"i":37,"n":"第三十七条","txt":"网络食品交易第三方平台提供者未履行相关义务，导致发生下列严重后果之一的，由县级以上地方市场监督管理部门依照食品安全法第一百三十一条的规定责令停业，并将相关情况移送通信主管部门处理： （一）致人死亡或者造成严重人身伤害的； （二）发生较大级别以上食品安全事故的； （三）发生较为严重的食源性疾病的； （四）侵犯消费者合法权益，造成严重不良社会影响的； （五）引发其他的严重后果的。"},{"i":38,"n":"第三十八条","txt":"违反本办法第十六条规定，入网食品生产经营者未依法取得食品生产经营许可的，或者入网食品生产者超过许可的类别范围销售食品、入网食品经营者超过许可的经营项目范围从事食品经营的，依照食品安全法第一百二十二条的规定处罚。"},{"i":39,"n":"第三十九条","txt":"入网食品生产经营者违反本办法第十七条禁止性规定的，由县级以上地方市场监督管理部门责令改正，给予警告；拒不改正的，处5000元以上3万元以下罚款。"},{"i":40,"n":"第四十条","txt":"违反本办法第十八条规定，入网食品生产经营者未按要求进行信息公示的，由县级以上地方市场监督管理部门责令改正，给予警告；拒不改正的，处5000元以上3万元以下罚款。"},{"i":41,"n":"第四十一条","txt":"违反本办法第十九条第一款规定，食品生产经营者未按要求公示特殊食品相关信息的，由县级以上地方市场监督管理部门责令改正，给予警告；拒不改正的，处5000元以上3万元以下罚款。 违反本办法第十九条第二款规定，食品生产经营者通过网络销售特定全营养配方食品的，由县级以上地方市场监督管理部门处3万元罚款。"},{"i":42,"n":"第四十二条","txt":"违反本办法第二十条规定，入网食品生产经营者未按要求采取保证食品安全的贮存、运输措施，或者委托不具备相应贮存、运输能力的企业从事贮存、配送的，由县级以上地方市场监督管理部门依照食品安全法第一百三十二条的规定处罚。"},{"i":43,"n":"第四十三条","txt":"违反本办法规定，网络食品交易第三方平台提供者、入网食品生产经营者提供虚假信息的，由县级以上地方市场监督管理部门责令改正，处1万元以上3万元以下罚款。"},{"i":44,"n":"第四十四条","txt":"网络食品交易第三方平台提供者、入网食品生产经营者违反食品安全法规定，构成犯罪的，依法追究刑事责任。"},{"i":45,"n":"第四十五条","txt":"市场监督管理部门工作人员不履行职责或者滥用职权、玩忽职守、徇私舞弊的，依法追究行政责任；构成犯罪的，移送司法机关，依法追究刑事责任。"},{"i":46,"n":"第四十六条","txt":"对食品生产加工小作坊、食品摊贩等的网络食品安全违法行为的查处，可以参照本办法执行。"},{"i":47,"n":"第四十七条","txt":"市场监督管理部门依法对网络食品安全违法行为进行查处的，应当自行政处罚决定书作出之日起20个工作日内，公开行政处罚决定书。"},{"i":48,"n":"第四十八条","txt":"本办法自2016年10月1日起施行。"}],"wangluocanyinfuwushipinanquanjianduguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强网络餐饮服务食品安全监督管理，规范网络餐饮服务经营行为，保证餐饮食品安全，保障公众身体健康，根据《中华人民共和国食品安全法》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内，网络餐饮服务第三方平台提供者、通过第三方平台和自建网站提供餐饮服务的餐饮服务提供者（以下简称入网餐饮服务提供者），利用互联网提供餐饮服务及其监督管理，适用本办法。"},{"i":3,"n":"第三条","txt":"国家市场监督管理总局负责指导全国网络餐饮服务食品安全监督管理工作，并组织开展网络餐饮服务食品安全监测。 县级以上地方市场监督管理部门负责本行政区域内网络餐饮服务食品安全监督管理工作。"},{"i":4,"n":"第四条","txt":"入网餐饮服务提供者应当具有实体经营门店并依法取得食品经营许可证，并按照食品经营许可证载明的主体业态、经营项目从事经营活动，不得超范围经营。"},{"i":5,"n":"第五条","txt":"网络餐饮服务第三方平台提供者应当在通信主管部门批准后30个工作日内，向所在地省级市场监督管理部门备案。自建网站餐饮服务提供者应当在通信主管部门备案后30个工作日内，向所在地县级市场监督管理部门备案。备案内容包括域名、IP地址、电信业务经营许可证或者备案号、企业名称、地址、法定代表人或者负责人姓名等。 网络餐饮服务第三方平台提供者设立从事网络餐饮服务分支机构的，应当在设立后30个工作日内，向所在地县级市场监督管理部门备案。备案内容包括分支机构名称、地址、法定代表人或者负责人姓名等。 市场监督管理部门应当及时向社会公开相关备案信息。"},{"i":6,"n":"第六条","txt":"网络餐饮服务第三方平台提供者应当建立并执行入网餐饮服务提供者审查登记、食品安全违法行为制止及报告、严重违法行为平台服务停止、食品安全事故处置等制度，并在网络平台上公开相关制度。"},{"i":7,"n":"第七条","txt":"网络餐饮服务第三方平台提供者应当设置专门的食品安全管理机构，配备专职食品安全管理人员，每年对食品安全管理人员进行培训和考核。培训和考核记录保存期限不得少于2年。经考核不具备食品安全管理能力的，不得上岗。"},{"i":8,"n":"第八条","txt":"网络餐饮服务第三方平台提供者应当对入网餐饮服务提供者的食品经营许可证进行审查，登记入网餐饮服务提供者的名称、地址、法定代表人或者负责人及联系方式等信息，保证入网餐饮服务提供者食品经营许可证载明的经营场所等许可信息真实。 网络餐饮服务第三方平台提供者应当与入网餐饮服务提供者签订食品安全协议，明确食品安全责任。"},{"i":9,"n":"第九条","txt":"网络餐饮服务第三方平台提供者和入网餐饮服务提供者应当在餐饮服务经营活动主页面公示餐饮服务提供者的食品经营许可证。食品经营许可等信息发生变更的，应当及时更新。"},{"i":10,"n":"第十条","txt":"网络餐饮服务第三方平台提供者和入网餐饮服务提供者应当在网上公示餐饮服务提供者的名称、地址、量化分级信息，公示的信息应当真实。"},{"i":11,"n":"第十一条","txt":"入网餐饮服务提供者应当在网上公示菜品名称和主要原料名称，公示的信息应当真实。"},{"i":12,"n":"第十二条","txt":"网络餐饮服务第三方平台提供者提供食品容器、餐具和包装材料的，所提供的食品容器、餐具和包装材料应当无毒、清洁。 鼓励网络餐饮服务第三方平台提供者提供可降解的食品容器、餐具和包装材料。"},{"i":13,"n":"第十三条","txt":"网络餐饮服务第三方平台提供者和入网餐饮服务提供者应当加强对送餐人员的食品安全培训和管理。委托送餐单位送餐的，送餐单位应当加强对送餐人员的食品安全培训和管理。培训记录保存期限不得少于2年。"},{"i":14,"n":"第十四条","txt":"送餐人员应当保持个人卫生，使用安全、无害的配送容器，保持容器清洁，并定期进行清洗消毒。送餐人员应当核对配送食品，保证配送过程食品不受污染。"},{"i":15,"n":"第十五条","txt":"网络餐饮服务第三方平台提供者和自建网站餐饮服务提供者应当履行记录义务，如实记录网络订餐的订单信息，包括食品的名称、下单时间、送餐人员、送达时间以及收货地址，信息保存时间不得少于6个月。"},{"i":16,"n":"第十六条","txt":"网络餐饮服务第三方平台提供者应当对入网餐饮服务提供者的经营行为进行抽查和监测。 网络餐饮服务第三方平台提供者发现入网餐饮服务提供者存在违法行为的，应当及时制止并立即报告入网餐饮服务提供者所在地县级市场监督管理部门；发现严重违法行为的，应当立即停止提供网络交易平台服务。"},{"i":17,"n":"第十七条","txt":"网络餐饮服务第三方平台提供者应当建立投诉举报处理制度，公开投诉举报方式，对涉及消费者食品安全的投诉举报及时进行处理。"},{"i":18,"n":"第十八条","txt":"入网餐饮服务提供者加工制作餐饮食品应当符合下列要求： （一）制定并实施原料控制要求，选择资质合法、保证原料质量安全的供货商，或者从原料生产基地、超市采购原料，做好食品原料索证索票和进货查验记录，不得采购不符合食品安全标准的食品及原料； （二）在加工过程中应当检查待加工的食品及原料，发现有腐败变质、油脂酸败、霉变生虫、污秽不洁、混有异物、掺假掺杂或者感官性状异常的，不得加工使用； （三）定期维护食品贮存、加工、清洗消毒等设施、设备，定期清洗和校验保温、冷藏和冷冻等设施、设备，保证设施、设备运转正常； （四）在自己的加工操作区内加工食品，不得将订单委托其他食品经营者加工制作； （五）网络销售的餐饮食品应当与实体店销售的餐饮食品质量安全保持一致。"},{"i":19,"n":"第十九条","txt":"入网餐饮服务提供者应当使用无毒、清洁的食品容器、餐具和包装材料，并对餐饮食品进行包装，避免送餐人员直接接触食品，确保送餐过程中食品不受污染。"},{"i":20,"n":"第二十条","txt":"入网餐饮服务提供者配送有保鲜、保温、冷藏或者冷冻等特殊要求食品的，应当采取能保证食品安全的保存、配送措施。"},{"i":21,"n":"第二十一条","txt":"国家市场监督管理总局组织监测发现网络餐饮服务第三方平台提供者和入网餐饮服务提供者存在违法行为的，通知有关省级市场监督管理部门依法组织查处。"},{"i":22,"n":"第二十二条","txt":"县级以上地方市场监督管理部门接到网络餐饮服务第三方平台提供者报告入网餐饮服务提供者存在违法行为的，应当及时依法查处。"},{"i":23,"n":"第二十三条","txt":"县级以上地方市场监督管理部门应当加强对网络餐饮服务食品安全的监督检查，发现网络餐饮服务第三方平台提供者和入网餐饮服务提供者存在违法行为的，依法进行查处。"},{"i":24,"n":"第二十四条","txt":"县级以上地方市场监督管理部门对网络餐饮服务交易活动的技术监测记录资料，可以依法作为认定相关事实的依据。"},{"i":25,"n":"第二十五条","txt":"县级以上地方市场监督管理部门对于消费者投诉举报反映的线索，应当及时进行核查，被投诉举报人涉嫌违法的，依法进行查处。"},{"i":26,"n":"第二十六条","txt":"县级以上地方市场监督管理部门查处的入网餐饮服务提供者有严重违法行为的，应当通知网络餐饮服务第三方平台提供者，要求其立即停止对入网餐饮服务提供者提供网络交易平台服务。"},{"i":27,"n":"第二十七条","txt":"违反本办法第四条规定，入网餐饮服务提供者不具备实体经营门店，未依法取得食品经营许可证的，由县级以上地方市场监督管理部门依照食品安全法第一百二十二条的规定处罚。"},{"i":28,"n":"第二十八条","txt":"违反本办法第五条规定，网络餐饮服务第三方平台提供者以及分支机构或者自建网站餐饮服务提供者未履行相应备案义务的，由县级以上地方市场监督管理部门责令改正，给予警告；拒不改正的，处5000元以上3万元以下罚款。"},{"i":29,"n":"第二十九条","txt":"违反本办法第六条规定，网络餐饮服务第三方平台提供者未按要求建立、执行并公开相关制度的，由县级以上地方市场监督管理部门责令改正，给予警告；拒不改正的，处5000元以上3万元以下罚款。"},{"i":30,"n":"第三十条","txt":"违反本办法第七条规定，网络餐饮服务第三方平台提供者未设置专门的食品安全管理机构，配备专职食品安全管理人员，或者未按要求对食品安全管理人员进行培训、考核并保存记录的，由县级以上地方市场监督管理部门责令改正，给予警告；拒不改正的，处5000元以上3万元以下罚款。"},{"i":31,"n":"第三十一条","txt":"违反本办法第八条第一款规定，网络餐饮服务第三方平台提供者未对入网餐饮服务提供者的食品经营许可证进行审查，未登记入网餐饮服务提供者的名称、地址、法定代表人或者负责人及联系方式等信息，或者入网餐饮服务提供者食品经营许可证载明的经营场所等许可信息不真实的，由县级以上地方市场监督管理部门依照食品安全法第一百三十一条的规定处罚。 违反本办法第八条第二款规定，网络餐饮服务第三方平台提供者未与入网餐饮服务提供者签订食品安全协议的，由县级以上地方市场监督管理部门责令改正，给予警告；拒不改正的，处5000元以上3万元以下罚款。"},{"i":32,"n":"第三十二条","txt":"违反本办法第九条、第十条、第十一条规定，网络餐饮服务第三方平台提供者和入网餐饮服务提供者未按要求进行信息公示和更新的，由县级以上地方市场监督管理部门责令改正，给予警告；拒不改正的，处5000元以上3万元以下罚款。"},{"i":33,"n":"第三十三条","txt":"违反本办法第十二条规定，网络餐饮服务第三方平台提供者提供的食品配送容器、餐具和包装材料不符合规定的，由县级以上地方市场监督管理部门按照食品安全法第一百三十二条的规定处罚。"},{"i":34,"n":"第三十四条","txt":"违反本办法第十三条规定，网络餐饮服务第三方平台提供者和入网餐饮服务提供者未对送餐人员进行食品安全培训和管理，或者送餐单位未对送餐人员进行食品安全培训和管理，或者未按要求保存培训记录的，由县级以上地方市场监督管理部门责令改正，给予警告；拒不改正的，处5000元以上3万元以下罚款。"},{"i":35,"n":"第三十五条","txt":"违反本办法第十四条规定，送餐人员未履行使用安全、无害的配送容器等义务的，由县级以上地方市场监督管理部门对送餐人员所在单位按照食品安全法第一百三十二条的规定处罚。"},{"i":36,"n":"第三十六条","txt":"违反本办法第十五条规定，网络餐饮服务第三方平台提供者和自建网站餐饮服务提供者未按要求记录、保存网络订餐信息的，由县级以上地方市场监督管理部门责令改正，给予警告；拒不改正的，处5000元以上3万元以下罚款。"},{"i":37,"n":"第三十七条","txt":"违反本办法第十六条第一款规定，网络餐饮服务第三方平台提供者未对入网餐饮服务提供者的经营行为进行抽查和监测的，由县级以上地方市场监督管理部门责令改正，给予警告；拒不改正的，处5000元以上3万元以下罚款。 违反本办法第十六条第二款规定，网络餐饮服务第三方平台提供者发现入网餐饮服务提供者存在违法行为，未及时制止并立即报告入网餐饮服务提供者所在地县级市场监督管理部门的，或者发现入网餐饮服务提供者存在严重违法行为，未立即停止提供网络交易平台服务的，由县级以上地方市场监督管理部门依照食品安全法第一百三十一条的规定处罚。"},{"i":38,"n":"第三十八条","txt":"违反本办法第十七条规定，网络餐饮服务第三方平台提供者未按要求建立消费者投诉举报处理制度，公开投诉举报方式，或者未对涉及消费者食品安全的投诉举报及时进行处理的，由县级以上地方市场监督管理部门责令改正，给予警告；拒不改正的，处5000元以上3万元以下罚款。"},{"i":39,"n":"第三十九条","txt":"违反本办法第十八条第（一）项规定，入网餐饮服务提供者未履行制定实施原料控制要求等义务的，由县级以上地方市场监督管理部门依照食品安全法第一百二十六条第一款的规定处罚。 违反本办法第十八条第（二）项规定，入网餐饮服务提供者使用腐败变质、油脂酸败、霉变生虫、污秽不洁、混有异物、掺假掺杂或者感官性状异常等原料加工食品的，由县级以上地方市场监督管理部门依照食品安全法第一百二十四条第一款的规定处罚。 违反本办法第十八条第（三）项规定，入网餐饮服务提供者未定期维护食品贮存、加工、清洗消毒等设施、设备，或者未定期清洗和校验保温、冷藏和冷冻等设施、设备的，由县级以上地方市场监督管理部门依照食品安全法第一百二十六条第一款的规定处罚。 违反本办法第十八条第（四）项、第（五）项规定，入网餐饮服务提供者将订单委托其他食品经营者加工制作，或者网络销售的餐饮食品未与实体店销售的餐饮食品质量安全保持一致的，由县级以上"},{"i":40,"n":"第四十条","txt":"违反本办法第十九条规定，入网餐饮服务提供者未履行相应的包装义务的，由县级以上地方市场监督管理部门责令改正，给予警告；拒不改正的，处5000元以上3万元以下罚款。"},{"i":41,"n":"第四十一条","txt":"违反本办法第二十条规定，入网餐饮服务提供者配送有保鲜、保温、冷藏或者冷冻等特殊要求食品，未采取能保证食品安全的保存、配送措施的，由县级以上地方市场监督管理部门依照食品安全法第一百三十二条的规定处罚。"},{"i":42,"n":"第四十二条","txt":"县级以上地方市场监督管理部门应当自对网络餐饮服务第三方平台提供者和入网餐饮服务提供者违法行为作出处罚决定之日起20个工作日内在网上公开行政处罚决定书。"},{"i":43,"n":"第四十三条","txt":"省、自治区、直辖市的地方性法规和政府规章对小餐饮网络经营作出规定的，按照其规定执行。 本办法对网络餐饮服务食品安全违法行为的查处未作规定的，按照《网络食品安全违法行为查处办法》执行。"},{"i":44,"n":"第四十四条","txt":"网络餐饮服务第三方平台提供者和入网餐饮服务提供者违反食品安全法规定，构成犯罪的，依法追究刑事责任。"},{"i":45,"n":"第四十五条","txt":"餐饮服务连锁公司总部建立网站为其门店提供网络交易服务的，参照本办法关于网络餐饮服务第三方平台提供者的规定执行。"},{"i":46,"n":"第四十六条","txt":"本办法自2018年1月1日起施行。"}],"yaopinyiliaoqixiefeixingjianchabanfa":[{"i":1,"n":"第一条","txt":"为加强药品和医疗器械监督检查，强化安全风险防控，根据《中华人民共和国药品管理法》、《中华人民共和国药品管理法实施条例》、《医疗器械监督管理条例》等有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称药品医疗器械飞行检查，是指食品药品监督管理部门针对药品和医疗器械研制、生产、经营、使用等环节开展的不预先告知的监督检查。"},{"i":3,"n":"第三条","txt":"国家食品药品监督管理总局负责组织实施全国范围内的药品医疗器械飞行检查。地方各级食品药品监督管理部门负责组织实施本行政区域的药品医疗器械飞行检查。"},{"i":4,"n":"第四条","txt":"药品医疗器械飞行检查应当遵循依法独立、客观公正、科学处置的原则，围绕安全风险防控开展。"},{"i":5,"n":"第五条","txt":"被检查单位对食品药品监督管理部门组织实施的药品医疗器械飞行检查应当予以配合，不得拒绝、逃避或者阻碍。"},{"i":6,"n":"第六条","txt":"食品药品监督管理部门应当按照政府信息公开的要求公开检查结果，对重大或者典型案件，可以采取新闻发布等方式向社会公开。"},{"i":7,"n":"第七条","txt":"食品药品监督管理部门及有关工作人员应当严格遵守有关法律法规、廉政纪律和工作要求，不得向被检查单位提出与检查无关的要求，不得泄露飞行检查相关情况、举报人信息及被检查单位的商业秘密。"},{"i":8,"n":"第八条","txt":"有下列情形之一的，食品药品监督管理部门可以开展药品医疗器械飞行检查： （一）投诉举报或者其他来源的线索表明可能存在质量安全风险的； （二）检验发现存在质量安全风险的； （三）药品不良反应或者医疗器械不良事件监测提示可能存在质量安全风险的； （四）对申报资料真实性有疑问的； （五）涉嫌严重违反质量管理规范要求的； （六）企业有严重不守信记录的； （七）其他需要开展飞行检查的情形。"},{"i":9,"n":"第九条","txt":"开展飞行检查应当制定检查方案，明确检查事项、时间、人员构成和方式等。需要采用不公开身份的方式进行调查的，检查方案中应当予以明确。 必要时，食品药品监督管理部门可以联合公安机关等有关部门共同开展飞行检查。"},{"i":10,"n":"第十条","txt":"食品药品监督管理部门派出的检查组应当由2名以上检查人员组成，检查组实行组长负责制。检查人员应当是食品药品行政执法人员、依法取得检查员资格的人员或者取得本次检查授权的其他人员；根据检查工作需要，食品药品监督管理部门可以请相关领域专家参加检查工作。 参加检查的人员应当签署无利益冲突声明和廉政承诺书；所从事的检查活动与其个人利益之间可能发生矛盾或者冲突的，应当主动提出回避。"},{"i":11,"n":"第十一条","txt":"检查组应当调查核实被检查单位执行药品和医疗器械监管法律法规的实际情况，按照检查方案明确现场检查重点，并可以根据风险研判提出风险管控预案。"},{"i":12,"n":"第十二条","txt":"检查组成员不得事先告知被检查单位检查行程和检查内容，指定地点集中后，第一时间直接进入检查现场；直接针对可能存在的问题开展检查；不得透露检查过程中的进展情况、发现的违法线索等相关信息。"},{"i":13,"n":"第十三条","txt":"上级食品药品监督管理部门组织实施飞行检查的，可以适时通知被检查单位所在地食品药品监督管理部门。被检查单位所在地食品药品监督管理部门应当派员协助检查，协助检查的人员应当服从检查组的安排。"},{"i":14,"n":"第十四条","txt":"组织实施飞行检查的食品药品监督管理部门应当加强对检查组的指挥，根据现场检查反馈的情况及时调整应对策略，必要时启动协调机制，并可以派相关人员赴现场协调和指挥。"},{"i":15,"n":"第十五条","txt":"检查组到达检查现场后，检查人员应当出示相关证件和受食品药品监督管理部门委派开展监督检查的执法证明文件，通报检查要求及被检查单位的权利和义务。"},{"i":16,"n":"第十六条","txt":"被检查单位及有关人员应当及时按照检查组要求，明确检查现场负责人，开放相关场所或者区域，配合对相关设施设备的检查，保持正常生产经营状态，提供真实、有效、完整的文件、记录、票据、凭证、电子数据等相关材料，如实回答检查组的询问。"},{"i":17,"n":"第十七条","txt":"检查组应当详细记录检查时间、地点、现场状况等；对发现的问题应当进行书面记录，并根据实际情况收集或者复印相关文件资料、拍摄相关设施设备及物料等实物和现场情况、采集实物以及询问有关人员等。询问记录应当包括询问对象姓名、工作岗位和谈话内容等，并经询问对象逐页签字或者按指纹。 记录应当及时、准确、完整，客观真实反映现场检查情况。 飞行检查过程中形成的记录及依法收集的相关资料、实物等，可以作为行政处罚中认定事实的依据。"},{"i":18,"n":"第十八条","txt":"需要抽取成品及其他物料进行检验的，检查组可以按照抽样检验相关规定抽样或者通知被检查单位所在地食品药品监督管理部门按规定抽样。抽取的样品应当由具备资质的技术机构进行检验或者鉴定，所抽取样品的检验费、鉴定费由组织实施飞行检查的食品药品监督管理部门承担。"},{"i":19,"n":"第十九条","txt":"检查组认为证据可能灭失或者以后难以取得的，以及需要采取行政强制措施的，可以通知被检查单位所在地食品药品监督管理部门。被检查单位所在地食品药品监督管理部门应当依法采取证据保全或者行政强制措施。"},{"i":20,"n":"第二十条","txt":"有下列情形之一的，检查组应当立即报组织实施飞行检查的食品药品监督管理部门及时作出决定： （一）需要增加检查力量或者延伸检查范围的； （二）需要采取产品召回或者暂停研制、生产、销售、使用等风险控制措施的； （三）需要立案查处的； （四）涉嫌犯罪需要移送公安机关的； （五）其他需要报告的事项。 需要采取风险控制措施的，被检查单位应当按照食品药品监督管理部门的要求采取相应措施。"},{"i":21,"n":"第二十一条","txt":"现场检查时间由检查组根据检查需要确定，以能够查清查实问题为原则。 经组织实施飞行检查的食品药品监督管理部门同意后，检查组方可结束检查。"},{"i":22,"n":"第二十二条","txt":"检查结束时，检查组应当向被检查单位通报检查相关情况。被检查单位有异议的，可以陈述和申辩，检查组应当如实记录。"},{"i":23,"n":"第二十三条","txt":"检查结束后，检查组应当撰写检查报告。检查报告的内容包括：检查过程、发现问题、相关证据、检查结论和处理建议等。"},{"i":24,"n":"第二十四条","txt":"检查组一般应当在检查结束后5个工作日内，将检查报告、检查记录、相关证据材料等报组织实施飞行检查的食品药品监督管理部门。必要时，可以抄送被检查单位所在地食品药品监督管理部门。"},{"i":25,"n":"第二十五条","txt":"根据飞行检查结果，食品药品监督管理部门可以依法采取限期整改、发告诫信、约谈被检查单位、监督召回产品、收回或者撤销相关资格认证认定证书，以及暂停研制、生产、销售、使用等风险控制措施。风险因素消除后，应当及时解除相关风险控制措施。"},{"i":26,"n":"第二十六条","txt":"国家食品药品监督管理总局组织实施的飞行检查发现违法行为需要立案查处的，国家食品药品监督管理总局可以直接组织查处，也可以指定被检查单位所在地食品药品监督管理部门查处。 地方各级食品药品监督管理部门组织实施的飞行检查发现违法行为需要立案查处的，原则上应当直接查处。 由下级食品药品监督管理部门查处的，组织实施飞行检查的食品药品监督管理部门应当跟踪督导查处情况。"},{"i":27,"n":"第二十七条","txt":"飞行检查发现的违法行为涉嫌犯罪的，由负责立案查处的食品药品监督管理部门移送公安机关，并抄送同级检察机关。"},{"i":28,"n":"第二十八条","txt":"食品药品监督管理部门有权在任何时间进入被检查单位研制、生产、经营、使用等场所进行检查，被检查单位不得拒绝、逃避。 被检查单位有下列情形之一的，视为拒绝、逃避检查： （一）拖延、限制、拒绝检查人员进入被检查场所或者区域的，或者限制检查时间的； （二）无正当理由不提供或者延迟提供与检查相关的文件、记录、票据、凭证、电子数据等材料的； （三）以声称工作人员不在、故意停止生产经营等方式欺骗、误导、逃避检查的； （四）拒绝或者限制拍摄、复印、抽样等取证工作的； （五）其他不配合检查的情形。 检查组对被检查单位拒绝、逃避检查的行为应当进行书面记录，责令改正并及时报告组织实施飞行检查的食品药品监督管理部门；经责令改正后仍不改正、造成无法完成检查工作的，检查结论判定为不符合相关质量管理规范或者其他相关要求。"},{"i":29,"n":"第二十九条","txt":"被检查单位因违法行为应当受到行政处罚，且具有拒绝、逃避监督检查或者伪造、销毁、隐匿有关证据材料等情形的，由食品药品监督管理部门按照《中华人民共和国药品管理法》、《中华人民共和国药品管理法实施条例》、《医疗器械监督管理条例》等有关规定从重处罚。"},{"i":30,"n":"第三十条","txt":"被检查单位有下列情形之一，构成违反治安管理行为的，由食品药品监督管理部门商请公安机关依照《中华人民共和国治安管理处罚法》的规定进行处罚： （一）阻碍检查人员依法执行职务，或者威胁检查人员人身安全的； （二）伪造、变造、买卖或者使用伪造、变造的审批文件、认证认定证书等的； （三）隐藏、转移、变卖、损毁食品药品监督管理部门依法查封、扣押的财物的； （四）伪造、隐匿、毁灭证据或者提供虚假证言，影响依法开展检查的。"},{"i":31,"n":"第三十一条","txt":"上级食品药品监督管理部门应当及时将其组织实施的飞行检查结果通报被检查单位所在地食品药品监督管理部门。 下级食品药品监督管理部门应当及时将其组织实施的飞行检查中发现的重大问题书面报告上一级食品药品监督管理部门，并于每年年底前将该年度飞行检查的总结报告报上一级食品药品监督管理部门。"},{"i":32,"n":"第三十二条","txt":"针对飞行检查中发现的区域性、普遍性或者长期存在、比较突出的问题，上级食品药品监督管理部门可以约谈被检查单位所在地食品药品监督管理部门主要负责人或者当地人民政府负责人。 被约谈的食品药品监督管理部门应当及时提出整改措施，并将整改情况上报。"},{"i":33,"n":"第三十三条","txt":"食品药品监督管理部门及有关工作人员有下列情形之一的，应当公开通报；对有关工作人员按照干部管理权限给予行政处分和纪律处分，或者提出处理建议；涉嫌犯罪的，依法移交司法机关处理： （一）泄露飞行检查信息的； （二）泄露举报人信息或者被检查单位商业秘密的； （三）出具虚假检查报告或者检验报告的； （四）干扰、拖延检查或者拒绝立案查处的； （五）违反廉政纪律的； （六）有其他滥用职权或者失职渎职行为的。"},{"i":34,"n":"第三十四条","txt":"各级食品药品监督管理部门应当将药品医疗器械飞行检查所需费用及相关抽检费用纳入年度经费预算，并根据工作需要予以足额保障。"},{"i":35,"n":"第三十五条","txt":"本办法自2015年9月1日起施行。"}],"yaopinshuomingshuhebiaoqianguanliguiding":[{"i":1,"n":"第一条","txt":"为规范药品说明书和标签的管理，根据《中华人民共和国药品管理法》和《中华人民共和国药品管理法实施条例》制定本规定。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内上市销售的药品，其说明书和标签应当符合本规定的要求。"},{"i":3,"n":"第三条","txt":"药品说明书和标签由国家食品药品监督管理局予以核准。 药品的标签应当以说明书为依据，其内容不得超出说明书的范围，不得印有暗示疗效、误导使用和不适当宣传产品的文字和标识。"},{"i":4,"n":"第四条","txt":"药品包装必须按照规定印有或者贴有标签，不得夹带其他任何介绍或者宣传产品、企业的文字、音像及其他资料。 药品生产企业生产供上市销售的最小包装必须附有说明书。"},{"i":5,"n":"第五条","txt":"药品说明书和标签的文字表述应当科学、规范、准确。非处方药说明书还应当使用容易理解的文字表述，以便患者自行判断、选择和使用。"},{"i":6,"n":"第六条","txt":"药品说明书和标签中的文字应当清晰易辨，标识应当清楚醒目，不得有印字脱落或者粘贴不牢等现象，不得以粘贴、剪切、涂改等方式进行修改或者补充。"},{"i":7,"n":"第七条","txt":"药品说明书和标签应当使用国家语言文字工作委员会公布的规范化汉字，增加其他文字对照的，应当以汉字表述为准。"},{"i":8,"n":"第八条","txt":"出于保护公众健康和指导正确合理用药的目的，药品生产企业可以主动提出在药品说明书或者标签上加注警示语，国家食品药品监督管理局也可以要求药品生产企业在说明书或者标签上加注警示语。"},{"i":9,"n":"第九条","txt":"药品说明书应当包含药品安全性、有效性的重要科学数据、结论和信息，用以指导安全、合理使用药品。药品说明书的具体格式、内容和书写要求由国家食品药品监督管理局制定并发布。"},{"i":10,"n":"第十条","txt":"药品说明书对疾病名称、药学专业名词、药品名称、临床检验名称和结果的表述，应当采用国家统一颁布或规范的专用词汇，度量衡单位应当符合国家标准的规定。"},{"i":11,"n":"第十一条","txt":"药品说明书应当列出全部活性成份或者组方中的全部中药药味。注射剂和非处方药还应当列出所用的全部辅料名称。 药品处方中含有可能引起严重不良反应的成份或者辅料的，应当予以说明。"},{"i":12,"n":"第十二条","txt":"药品生产企业应当主动跟踪药品上市后的安全性、有效性情况，需要对药品说明书进行修改的，应当及时提出申请。 根据药品不良反应监测、药品再评价结果等信息，国家食品药品监督管理局也可以要求药品生产企业修改药品说明书。"},{"i":13,"n":"第十三条","txt":"药品说明书获准修改后，药品生产企业应当将修改的内容立即通知相关药品经营企业、使用单位及其他部门，并按要求及时使用修改后的说明书和标签。"},{"i":14,"n":"第十四条","txt":"药品说明书应当充分包含药品不良反应信息，详细注明药品不良反应。药品生产企业未根据药品上市后的安全性、有效性情况及时修改说明书或者未将药品不良反应在说明书中充分说明的，由此引起的不良后果由该生产企业承担。"},{"i":15,"n":"第十五条","txt":"药品说明书核准日期和修改日期应当在说明书中醒目标示。"},{"i":16,"n":"第十六条","txt":"药品的标签是指药品包装上印有或者贴有的内容，分为内标签和外标签。药品内标签指直接接触药品的包装的标签，外标签指内标签以外的其他包装的标签。"},{"i":17,"n":"第十七条","txt":"药品的内标签应当包含药品通用名称、适应症或者功能主治、规格、用法用量、生产日期、产品批号、有效期、生产企业等内容。 包装尺寸过小无法全部标明上述内容的，至少应当标注药品通用名称、规格、产品批号、有效期等内容。"},{"i":18,"n":"第十八条","txt":"药品外标签应当注明药品通用名称、成份、性状、适应症或者功能主治、规格、用法用量、不良反应、禁忌、注意事项、贮藏、生产日期、产品批号、有效期、批准文号、生产企业等内容。适应症或者功能主治、用法用量、不良反应、禁忌、注意事项不能全部注明的，应当标出主要内容并注明“详见说明书”字样。"},{"i":19,"n":"第十九条","txt":"用于运输、储藏的包装的标签，至少应当注明药品通用名称、规格、贮藏、生产日期、产品批号、有效期、批准文号、生产企业，也可以根据需要注明包装数量、运输注意事项或者其他标记等必要内容。"},{"i":20,"n":"第二十条","txt":"原料药的标签应当注明药品名称、贮藏、生产日期、产品批号、有效期、执行标准、批准文号、生产企业，同时还需注明包装数量以及运输注意事项等必要内容。"},{"i":21,"n":"第二十一条","txt":"同一药品生产企业生产的同一药品，药品规格和包装规格均相同的，其标签的内容、格式及颜色必须一致；药品规格或者包装规格不同的，其标签应当明显区别或者规格项明显标注。 同一药品生产企业生产的同一药品，分别按处方药与非处方药管理的，两者的包装颜色应当明显区别。"},{"i":22,"n":"第二十二条","txt":"对贮藏有特殊要求的药品，应当在标签的醒目位置注明。"},{"i":23,"n":"第二十三条","txt":"药品标签中的有效期应当按照年、月、日的顺序标注，年份用四位数字表示，月、日用两位数表示。其具体标注格式为“有效期至××××年××月”或者“有效期至××××年××月××日”；也可以用数字和其他符号表示为“有效期至××××.××.”或者“有效期至××××/××/××”等。 预防用生物制品有效期的标注按照国家食品药品监督管理局批准的注册标准执行，治疗用生物制品有效期的标注自分装日期计算，其他药品有效期的标注自生产日期计算。 有效期若标注到日，应当为起算日期对应年月日的前一天，若标注到月，应当为起算月份对应年月的前一月。"},{"i":24,"n":"第二十四条","txt":"药品说明书和标签中标注的药品名称必须符合国家食品药品监督管理局公布的药品通用名称和商品名称的命名原则，并与药品批准证明文件的相应内容一致。"},{"i":25,"n":"第二十五条","txt":"药品通用名称应当显著、突出，其字体、字号和颜色必须一致，并符合以下要求： （一）对于横版标签，必须在上三分之一范围内显著位置标出；对于竖版标签，必须在右三分之一范围内显著位置标出； （二）不得选用草书、篆书等不易识别的字体，不得使用斜体、中空、阴影等形式对字体进行修饰； （三）字体颜色应当使用黑色或者白色，与相应的浅色或者深色背景形成强烈反差； （四）除因包装尺寸的限制而无法同行书写的，不得分行书写。"},{"i":26,"n":"第二十六条","txt":"药品商品名称不得与通用名称同行书写，其字体和颜色不得比通用名称更突出和显著，其字体以单字面积计不得大于通用名称所用字体的二分之一。"},{"i":27,"n":"第二十七条","txt":"药品说明书和标签中禁止使用未经注册的商标以及其他未经国家食品药品监督管理局批准的药品名称。 药品标签使用注册商标的，应当印刷在药品标签的边角，含文字的，其字体以单字面积计不得大于通用名称所用字体的四分之一。"},{"i":28,"n":"第二十八条","txt":"麻醉药品、精神药品、医疗用毒性药品、放射性药品、外用药品和非处方药品等国家规定有专用标识的，其说明书和标签必须印有规定的标识。 国家对药品说明书和标签有特殊规定的，从其规定。"},{"i":29,"n":"第二十九条","txt":"中药材、中药饮片的标签管理规定由国家食品药品监督管理局另行制定。"},{"i":30,"n":"第三十条","txt":"药品说明书和标签不符合本规定的，按照《中华人民共和国药品管理法》的相关规定进行处罚。"},{"i":31,"n":"第三十一条","txt":"本规定自2006年6月1日起施行。国家药品监督管理局于2000年10月15日发布的《药品包装、标签和说明书管理规定（暂行）》同时废止。"}],"yaopinjinkouguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范药品进口备案、报关和口岸检验工作，保证进口药品的质量，根据《中华人民共和国药品管理法》、《中华人民共和国海关法》、《中华人民共和国药品管理法实施条例》（以下简称《药品管理法》、《海关法》、《药品管理法实施条例》）及相关法律法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"药品的进口备案、报关、口岸检验以及进口，适用本办法。"},{"i":3,"n":"第三条","txt":"药品必须经由国务院批准的允许药品进口的口岸进口。"},{"i":4,"n":"第四条","txt":"本办法所称进口备案，是指进口单位向允许药品进口的口岸所在地药品监督管理部门（以下称口岸药品监督管理局）申请办理《进口药品通关单》的过程。麻醉药品、精神药品进口备案，是指进口单位向口岸药品监督管理局申请办理《进口药品口岸检验通知书》的过程。 本办法所称口岸检验，是指国家食品药品监督管理局确定的药品检验机构（以下称口岸药品检验所）对抵达口岸的进口药品依法实施的检验工作。"},{"i":5,"n":"第五条","txt":"进口药品必须取得国家食品药品监督管理局核发的《进口药品注册证》（或者《医药产品注册证》），或者《进口药品批件》后，方可办理进口备案和口岸检验手续。 进口麻醉药品、精神药品，还必须取得国家食品药品监督管理局核发的麻醉药品、精神药品《进口准许证》。"},{"i":6,"n":"第六条","txt":"进口单位持《进口药品通关单》向海关申报，海关凭口岸药品监督管理局出具的《进口药品通关单》，办理进口药品的报关验放手续。 进口麻醉药品、精神药品，海关凭国家食品药品监督管理局核发的麻醉药品、精神药品《进口准许证》办理报关验放手续。"},{"i":7,"n":"第七条","txt":"国家食品药品监督管理局会同海关总署制定、修订、公布进口药品目录。"},{"i":8,"n":"第八条","txt":"口岸药品监督管理局负责药品的进口备案工作。口岸药品监督管理局承担的进口备案工作受国家食品药品监督管理局的领导，其具体职责包括： （一）受理进口备案申请，审查进口备案资料； （二）办理进口备案或者不予进口备案的有关事项； （三）联系海关办理与进口备案有关的事项； （四）通知口岸药品检验所对进口药品实施口岸检验； （五）对进口备案和口岸检验中发现的问题进行监督处理； （六）国家食品药品监督管理局规定的其他事项。"},{"i":9,"n":"第九条","txt":"报验单位应当是持有《药品经营许可证》的独立法人。药品生产企业进口本企业所需原料药和制剂中间体（包括境内分包装用制剂），应当持有《药品生产许可证》。"},{"i":10,"n":"第十条","txt":"下列情形的进口药品，必须经口岸药品检验所检验符合标准规定后，方可办理进口备案手续。检验不符合标准规定的，口岸药品监督管理局不予进口备案： （一）国家食品药品监督管理局规定的生物制品； （二）首次在中国境内销售的药品； （三）国务院规定的其他药品。"},{"i":11,"n":"第十一条","txt":"进口单位签订购货合同时，货物到岸地应当从允许药品进口的口岸选择。其中本办法第十条规定情形的药品，必须经由国家特别批准的允许药品进口的口岸进口。"},{"i":12,"n":"第十二条","txt":"进口备案，应当向货物到岸地口岸药品监督管理局提出申请，并由负责本口岸药品检验的口岸药品检验所进行检验。"},{"i":13,"n":"第十三条","txt":"办理进口备案，报验单位应当填写《进口药品报验单》，持《进口药品注册证》（或者《医药产品注册证》）（正本或者副本）原件，进口麻醉药品、精神药品还应当持麻醉药品、精神药品《进口准许证》原件，向所在地口岸药品监督管理局报送所进口品种的有关资料一式两份： （一）《进口药品注册证》（或者《医药产品注册证》）（正本或者副本）复印件；麻醉药品、精神药品的《进口准许证》复印件； （二）报验单位的《药品经营许可证》和《企业法人营业执照》复印件； （三）原产地证明复印件； （四）购货合同复印件； （五）装箱单、提运单和货运发票复印件； （六）出厂检验报告书复印件； （七）药品说明书及包装、标签的式样（原料药和制剂中间体除外）； （八）国家食品药品监督管理局规定批签发的生物制品，需要提供生产检定记录摘要及生产国或者地区药品管理机构出具的批签发证明原件； （九）本办法第十条规定情形以外的药品，应当提交最近一次"},{"i":14,"n":"第十四条","txt":"口岸药品监督管理局接到《进口药品报验单》及相关资料后，按照下列程序的要求予以审查： （一）逐项核查所报资料是否完整、真实； （二）查验《进口药品注册证》（或者《医药产品注册证》）（正本或者副本）原件，或者麻醉药品、精神药品的《进口准许证》原件真实性； （三）审查无误后，将《进口药品注册证》（或者《医药产品注册证》）（正本或者副本）原件，或者麻醉药品、精神药品的《进口准许证》原件，交还报验单位，并于当日办结进口备案的相关手续。"},{"i":15,"n":"第十五条","txt":"本办法第十条规定情形的药品，口岸药品监督管理局审查全部资料无误后，应当向负责检验的口岸药品检验所发出《进口药品口岸检验通知书》，附本办法第十三条规定的资料一份，同时向海关发出《进口药品抽样通知书》。有关口岸药品检验进入海关监管场所抽样的管理规定，由国家食品药品监督管理局与海关总署另行制定。 口岸药品检验所按照《进口药品口岸检验通知书》规定的抽样地点，抽取检验样品，进行质量检验，并将检验结果送交所在地口岸药品监督管理局。检验符合标准规定的，准予进口备案，由口岸药品监督管理局发出《进口药品通关单》；不符合标准规定的，不予进口备案，由口岸药品监督管理局发出《药品不予进口备案通知书》。"},{"i":16,"n":"第十六条","txt":"本办法第十条规定情形以外的药品，口岸药品监督管理局审查全部资料无误后，准予进口备案，发出《进口药品通关单》。同时向负责检验的口岸药品检验所发出《进口药品口岸检验通知书》，附本办法第十三条规定的资料一份。 对麻醉药品、精神药品，口岸药品监督管理局审查全部资料无误后，应当只向负责检验的口岸药品检验所发出《进口药品口岸检验通知书》，附本办法第十三条规定的资料一份，无需办理《进口药品通关单》。 口岸药品检验所应当到《进口药品口岸检验通知书》规定的抽样地点抽取样品，进行质量检验，并将检验结果送交所在地口岸药品监督管理局。对检验不符合标准规定的药品，由口岸药品监督管理局依照《药品管理法》及有关规定处理。"},{"i":17,"n":"第十七条","txt":"下列情形之一的进口药品，不予进口备案，由口岸药品监督管理局发出《药品不予进口备案通知书》；对麻醉药品、精神药品，口岸药品监督管理局不予发放《进口药品口岸检验通知书》： （一）不能提供《进口药品注册证》（或者《医药产品注册证》）（正本或者副本）、《进口药品批件》或者麻醉药品、精神药品的《进口准许证》原件的； （二）办理进口备案时，《进口药品注册证》（或者《医药产品注册证》），或者麻醉药品、精神药品的《进口准许证》已超过有效期的； （三）办理进口备案时，药品的有效期限已不满12个月的。（对于药品本身有效期不足12个月的，进口备案时，其有效期限应当不低于6个月）； （四）原产地证明所标示的实际生产地与《进口药品注册证》（或者《医药产品注册证》）规定的产地不符的，或者区域性国际组织出具的原产地证明未标明《进口药品注册证》（或者《医药产品注册证》）规定产地的； （五）进口单位未取得《药品经营许可"},{"i":18,"n":"第十八条","txt":"对不予进口备案的进口药品，进口单位应当予以退运。无法退运的，由海关移交口岸药品监督管理局监督处理。"},{"i":19,"n":"第十九条","txt":"进口临床急需药品、捐赠药品、新药研究和药品注册所需样品或者对照药品等，必须经国家食品药品监督管理局批准，并凭国家食品药品监督管理局核发的《进口药品批件》，按照本办法第十六条的规定，办理进口备案手续。"},{"i":20,"n":"第二十条","txt":"口岸药品检验所由国家食品药品监督管理局根据进口药品口岸检验工作的需要确定。口岸药品检验所的职责包括： （一）对到岸货物实施现场核验； （二）核查出厂检验报告书和原产地证明原件； （三）按照规定进行抽样； （四）对进口药品实施口岸检验； （五）对有异议的检验结果进行复验； （六）国家食品药品监督管理局规定的其他事项。"},{"i":21,"n":"第二十一条","txt":"中国药品生物制品检定所负责进口药品口岸检验工作的指导和协调。口岸检验所需标准品、对照品由中国药品生物制品检定所负责审核、标定。"},{"i":22,"n":"第二十二条","txt":"口岸药品检验所应当按照《进口药品注册证》（或者《医药产品注册证》）载明的注册标准对进口药品进行检验。"},{"i":23,"n":"第二十三条","txt":"口岸药品检验所接到《进口药品口岸检验通知书》后，应当在2日内与进口单位联系，到规定的存货地点按照《进口药品抽样规定》进行现场抽样。 进口单位应当在抽样前，提供出厂检验报告书和原产地证明原件。 对需进入海关监管区抽样的，口岸药品检验所应当同时与海关联系抽样事宜，并征得海关同意。抽样时，进口单位和海关的人员应当同时在场。"},{"i":24,"n":"第二十四条","txt":"口岸药品检验所现场抽样时，应当注意核查进口品种的实际到货情况，做好抽样记录并填写《进口药品抽样记录单》。 本办法第十条规定情形以外的药品，抽样完成后，口岸药品检验所应当在进口单位持有的《进口药品通关单》原件上注明“已抽样”的字样，并加盖抽样单位的公章。 对麻醉药品、精神药品，抽样完成后，应当在《进口准许证》原件上注明“已抽样”的字样，并加盖抽样单位的公章。"},{"i":25,"n":"第二十五条","txt":"对有下列情形之一的进口药品，口岸药品检验所不予抽样： （一）未提供出厂检验报告书和原产地证明原件，或者所提供的原件与申报进口备案时的复印件不符的； （二）装运唛头与单证不符的； （三）进口药品批号或者数量与单证不符的； （四）进口药品包装及标签与单证不符的； （五） 药品监督管理部门有其他证据证明进口药品可能危害人体健康的。 对不予抽样的药品，口岸药品检验所应当在2日内，将《进口药品抽样记录单》送交所在地口岸药品监督管理局。"},{"i":26,"n":"第二十六条","txt":"口岸药品检验所应当及时对所抽取的样品进行检验，并在抽样后20日内，完成检验工作，出具《进口药品检验报告书》。特殊品种或者特殊情况不能按时完成检验时，可以适当延长检验期限，并通知进口单位和口岸药品监督管理局。 《进口药品检验报告书》应当明确标有“符合标准规定”或者“不符合标准规定”的检验结论。 国家食品药品监督管理局规定批签发的生物制品，口岸检验符合标准规定，审核符合要求的，应当同时发放生物制品批签发证明。"},{"i":27,"n":"第二十七条","txt":"对检验符合标准规定的进口药品，口岸药品检验所应当将《进口药品检验报告书》送交所在地口岸药品监督管理局和进口单位。 对检验不符合标准规定的进口药品，口岸药品检验所应当将《进口药品检验报告书》及时发送口岸药品监督管理局和其他口岸药品检验所，同时报送国家食品药品监督管理局和中国药品生物制品检定所。"},{"i":28,"n":"第二十八条","txt":"进口药品的检验样品应当保存至有效期满。不易贮存的留样，可根据实际情况掌握保存时间。索赔或者退货检品的留样应当保存至该案完结时。超过保存期的留样，由口岸药品检验所予以处理并记录备案。"},{"i":29,"n":"第二十九条","txt":"进口单位对检验结果有异议的，可以自收到检验结果之日起7日内向原口岸药品检验所申请复验，也可以直接向中国药品生物制品检定所申请复验。生物制品的复验直接向中国药品生物制品检定所申请。 口岸药品检验所在受理复验申请后，应当及时通知口岸药品监督管理局，并自受理复验之日起10日内，作出复验结论，通知口岸药品监督管理局、其他口岸药品检验所，报国家食品药品监督管理局和中国药品生物制品检定所。"},{"i":30,"n":"第三十条","txt":"口岸药品检验所根据本办法第二十五条的规定不予抽样但已办结海关验放手续的药品，口岸药品监督管理局应当对已进口的全部药品采取查封、扣押的行政强制措施。"},{"i":31,"n":"第三十一条","txt":"本办法第十条规定情形以外的药品，经口岸药品检验所检验不符合标准规定的，进口单位应当在收到《进口药品检验报告书》后2日内，将全部进口药品流通、使用的详细情况，报告所在地口岸药品监督管理局。 所在地口岸药品监督管理局收到《进口药品检验报告书》后，应当及时采取对全部药品予以查封、扣押的行政强制措施，并在7日内作出行政处理决定。对申请复验的，必须自检验报告书发出之日起15日内作出行政处理决定。有关情况应当及时报告国家食品药品监督管理局，同时通告各省、自治区、直辖市药品监督管理局和其他口岸药品监督管理局。"},{"i":32,"n":"第三十二条","txt":"未在规定时间内提出复验或者经复验仍不符合标准规定的，口岸药品监督管理局应当按照《药品管理法》以及有关规定作出行政处理决定。有关情况应当及时报告国家食品药品监督管理局，同时通告各省、自治区、直辖市药品监督管理局和其他口岸药品监督管理局。 经复验符合标准规定的，口岸药品监督管理局应当解除查封、扣押的行政强制措施，并将处理情况报告国家食品药品监督管理局，同时通告各省、自治区、直辖市药品监督管理局和其他口岸药品监督管理局。"},{"i":33,"n":"第三十三条","txt":"药品进口备案中发现的其他问题，由口岸药品监督管理局按照《药品管理法》以及有关规定予以处理。"},{"i":34,"n":"第三十四条","txt":"国内药品生产企业、经营企业以及医疗机构采购进口药品时，供货单位应当同时提供以下资料： （一）《进口药品注册证》（或者《医药产品注册证》）复印件、《进口药品批件》复印件； （二）《进口药品检验报告书》复印件或者注明 “已抽样 ”并加盖公章的《进口药品通关单》复印件； 国家食品药品监督管理局规定批签发的生物制品，需要同时提供口岸药品检验所核发的批签发证明复印件。 进口麻醉药品、精神药品，应当同时提供其《进口药品注册证》（或者《医药产品注册证》）复印件、《进口准许证》复印件和《进口药品检验报告书》复印件。 上述各类复印件均需加盖供货单位公章。"},{"i":35,"n":"第三十五条","txt":"口岸药品监督管理局和口岸药品检验所应当建立严格的进口备案资料和口岸检验资料的管理制度，并对进口单位的呈报资料承担保密责任。"},{"i":36,"n":"第三十六条","txt":"对于违反本办法进口备案和口岸检验有关规定的口岸药品监督管理局和口岸药品检验所，国家食品药品监督管理局将根据情节给予批评、通报批评，情节严重的停止其进口备案和口岸检验资格。"},{"i":37,"n":"第三十七条","txt":"违反本办法涉及海关有关规定的，海关按照《海关法》、《中华人民共和国海关法行政处罚实施细则》的规定处理。"},{"i":38,"n":"第三十八条","txt":"本办法所称进口单位，包括经营单位、收货单位和报验单位。 经营单位，是指对外签订并执行进出口贸易合同的中国境内企业或单位。 收货单位，是指购货合同和货运发票中载明的收货人或者货主。 报验单位，是指该批进口药品的实际货主或者境内经销商，并具体负责办理进口备案和口岸检验手续。 收货单位和报验单位可以为同一单位。"},{"i":39,"n":"第三十九条","txt":"从境外进入保税仓库、保税区、出口加工区的药品，免予办理进口备案和口岸检验等进口手续，海关按有关规定实施监管；从保税仓库、出口监管仓库、保税区、出口加工区出库或出区进入国内的药品，按本办法有关规定办理进口备案和口岸检验等手续。 经批准以加工贸易方式进口的原料药、药材，免予办理进口备案和口岸检验等进口手续，其原料药及制成品禁止转为内销。确因特殊情况无法出口的，移交地方药品监督管理部门按规定处理，海关予以核销。 进出境人员随身携带的个人自用的少量药品，应当以自用、合理数量为限，并接受海关监管。"},{"i":40,"n":"第四十条","txt":"进口暂未列入进口药品目录的原料药，应当遵照本办法的规定，到口岸药品监督管理局办理进口备案手续。"},{"i":41,"n":"第四十一条","txt":"药材进口备案和口岸检验的规定，由国家食品药品监督管理局另行制定。"},{"i":42,"n":"第四十二条","txt":"进口麻醉药品、精神药品凭《进口药品注册证》（或者《医药产品注册证》），按照国务院麻醉药品、精神药品管理的有关法规办理《进口准许证》。"},{"i":43,"n":"第四十三条","txt":"本办法规定的麻醉药品、精神药品是指供临床使用的品种，科研、教学、兽用等麻醉药品、精神药品的进口，按照国务院麻醉药品、精神药品管理的有关法规执行。"},{"i":44,"n":"第四十四条","txt":"本办法由国家食品药品监督管理局和海关总署负责解释。"},{"i":45,"n":"第四十五条","txt":"本办法自2004年1月1日起实施。1999年5月1日实施的《进口药品管理办法》同时废止。 附：1.进口药品报验单（略，详情请登录卫生部网站） 2.进口药品通关单（略，详情请登录卫生部网站） 3.进口药品口岸检验通知书（略，详情请登录卫生部网站） 4.进口药品抽样通知书（略，详情请登录卫生部网站） 5.药品不予进口备案通知书（略，详情请登录卫生部网站） 6.进口药品抽样记录单（略，详情请登录卫生部网站） 7.进口药品批件（略，详情请登录卫生部网站） 8.进口药品检验报告书（略，详情请登录卫生部网站） 9.进口药品抽样规定（略，详情请登录卫生部网站）"}],"yaowufeilinchuangyanjiuzhiliangguanliguifan":[{"i":1,"n":"第一条","txt":"为保证药物非临床安全性评价研究的质量，保障公众用药安全，根据《中华人民共和国药品管理法》《中华人民共和国药品管理法实施条例》，制定本规范。"},{"i":2,"n":"第二条","txt":"本规范适用于为申请药品注册而进行的药物非临床安全性评价研究。药物非临床安全性评价研究的相关活动应当遵守本规范。以注册为目的的其他药物临床前相关研究活动参照本规范执行。"},{"i":3,"n":"第三条","txt":"药物非临床安全性评价研究是药物研发的基础性工作，应当确保行为规范，数据真实、准确、完整。"},{"i":4,"n":"第四条","txt":"本规范下列术语的含义是： （一）非临床研究质量管理规范，指有关非临床安全性评价研究机构运行管理和非临床安全性评价研究项目试验方案设计、组织实施、执行、检查、记录、存档和报告等全过程的质量管理要求。 （二）非临床安全性评价研究，指为评价药物安全性，在实验室条件下用实验系统进行的试验，包括安全药理学试验、单次给药毒性试验、重复给药毒性试验、生殖毒性试验、遗传毒性试验、致癌性试验、局部毒性试验、免疫原性试验、依赖性试验、毒代动力学试验以及与评价药物安全性有关的其他试验。 （三）非临床安全性评价研究机构（以下简称研究机构），指具备开展非临床安全性评价研究的人员、设施设备及质量管理体系等条件，从事药物非临床安全性评价研究的单位。 （四）多场所研究，指在不同研究机构或者同一研究机构中不同场所内共同实施完成的研究项目。该类研究项目只有一个试验方案、专题负责人，形成一个总结报告，专题负责人和实验系统所"},{"i":5,"n":"第五条","txt":"研究机构应当建立完善的组织管理体系，配备机构负责人、质量保证部门和相应的工作人员。"},{"i":6,"n":"第六条","txt":"研究机构的工作人员至少应当符合下列要求： （一）接受过与其工作相关的教育或者专业培训，具备所承担工作需要的知识、工作经验和业务能力； （二）掌握本规范中与其工作相关的要求，并严格执行； （三）严格执行与所承担工作有关的标准操作规程，对研究中发生的偏离标准操作规程的情况应当及时记录并向专题负责人或者主要研究者书面报告； （四）严格执行试验方案的要求，及时、准确、清楚地记录原始数据，并对原始数据的质量负责，对研究中发生的偏离试验方案的情况应当及时记录并向专题负责人或者主要研究者书面报告； （五）根据工作岗位的需要采取必要的防护措施，最大限度地降低工作人员的安全风险，同时确保受试物、对照品和实验系统不受化学性、生物性或者放射性污染； （六）定期进行体检，出现健康问题时，为确保研究的质量，应当避免参与可能影响研究的工作。"},{"i":7,"n":"第七条","txt":"机构负责人全面负责本研究机构的运行管理，至少应当履行以下职责： （一）确保研究机构的运行管理符合本规范的要求； （二）确保研究机构具有足够数量、具备资质的人员，以及符合本规范要求的设施、仪器设备及材料，以保证研究项目及时、正常地运行； （三）确保建立工作人员的教育背景、工作经历、培训情况、岗位描述等资料，并归档保存、及时更新； （四）确保工作人员清楚地理解自己的职责及所承担的工作内容，如有必要应当提供与这些工作相关的培训； （五）确保建立适当的、符合技术要求的标准操作规程，并确保工作人员严格遵守标准操作规程，所有新建和修改后的标准操作规程需经机构负责人签字批准方可生效，其原始文件作为档案进行保存； （六）确保在研究机构内制定质量保证计划，由独立的质量保证人员执行，并确保其按照本规范的要求履行质量保证职责； （七）确保制定主计划表并及时进行更新，确保定期对主计划表归档保存，主计划表应当至"},{"i":8,"n":"第八条","txt":"研究机构应当设立独立的质量保证部门负责检查本规范的执行情况，以保证研究的运行管理符合本规范要求。 质量保证人员的职责至少应当包括以下几个方面： （一）保存正在实施中的研究的试验方案及试验方案修改的副本、现行标准操作规程的副本，并及时获得主计划表的副本； （二）审查试验方案是否符合本规范的要求，审查工作应当记录归档； （三）根据研究的内容和持续时间制定检查计划，对每项研究实施检查，以确认所有研究均按照本规范的要求进行，并记录检查的内容、发现的问题、提出的建议等； （四）定期检查研究机构的运行管理状况，以确认研究机构的工作按照本规范的要求进行； （五）对检查中发现的任何问题、提出的建议应当跟踪检查并核实整改结果； （六）以书面形式及时向机构负责人或者专题负责人报告检查结果，对于多场所研究，分研究场所的质量保证人员需将检查结果报告给其研究机构内的主要研究者和机构负责人，以及主研究场所的机构负"},{"i":9,"n":"第九条","txt":"专题负责人对研究的执行和总结报告负责，其职责至少应当包括以下方面： （一）以签署姓名和日期的方式批准试验方案和试验方案变更，并确保质量保证人员、试验人员及时获得试验方案和试验方案变更的副本； （二）及时提出修订、补充标准操作规程相关的建议； （三）确保试验人员了解试验方案和试验方案变更、掌握相应标准操作规程的内容，并遵守其要求，确保及时记录研究中发生的任何偏离试验方案或者标准操作规程的情况，并评估这些情况对研究数据的质量和完整性造成的影响，必要时应当采取纠正措施； （四）掌握研究工作的进展，确保及时、准确、完整地记录原始数据； （五）及时处理质量保证部门提出的问题，确保研究工作符合本规范的要求； （六）确保研究中所使用的仪器设备、计算机化系统得到确认或者验证，且处于适用状态； （七）确保研究中给予实验系统的受试物、对照品制剂得到充分的检测，以保证其稳定性、浓度或者均一性符合研究要求；"},{"i":10,"n":"第十条","txt":"研究机构应当根据所从事的非临床安全性评价研究的需要建立相应的设施，并确保设施的环境条件满足工作的需要。各种设施应当布局合理、运转正常，并具有必要的功能划分和区隔，有效地避免可能对研究造成的干扰。"},{"i":11,"n":"第十一条","txt":"具备能够满足研究需要的动物设施，并能根据需要调控温度、湿度、空气洁净度、通风和照明等环境条件。动物设施的条件应当与所使用的实验动物级别相符，其布局应当合理，避免实验系统、受试物、废弃物等之间发生相互污染。 动物设施应当符合以下要求： （一）不同种属实验动物能够得到有效的隔离； （二）同一种属不同研究的实验动物应能够得到有效的隔离，防止不同的受试物、对照品之间可能产生的交叉干扰； （三）具备实验动物的检疫和患病实验动物的隔离、治疗设施； （四）当受试物或者对照品含有挥发性、放射性或者生物危害性等物质时，研究机构应当为此研究提供单独的、有效隔离的动物设施，以避免对其他研究造成不利的影响； （五）具备清洗消毒设施； （六）具备饲料、垫料、笼具及其他实验用品的存放设施，易腐败变质的用品应当有适当的保管措施。"},{"i":12,"n":"第十二条","txt":"与受试物和对照品相关的设施应当符合以下要求： （一）具备受试物和对照品的接收、保管、配制及配制后制剂保管的独立房间或者区域，并采取必要的隔离措施，以避免受试物和对照品发生交叉污染或者相互混淆，相关的设施应当满足不同受试物、对照品对于贮藏温度、湿度、光照等环境条件的要求，以确保受试物和对照品在有效期内保持稳定； （二）受试物和对照品及其制剂的保管区域与实验系统所在的区域应当有效地隔离，以防止其对研究产生不利的影响； （三）受试物和对照品及其制剂的保管区域应当有必要的安全措施，以确保受试物和对照品及其制剂在贮藏保管期间的安全。"},{"i":13,"n":"第十三条","txt":"档案保管的设施应当符合以下要求： （一）防止未经授权批准的人员接触档案； （二）计算机化的档案设施具备阻止未经授权访问和病毒防护等安全措施； （三）根据档案贮藏条件的需要配备必要的设备，有效地控制火、水、虫、鼠、电力中断等危害因素； （四）对于有特定环境条件调控要求的档案保管设施，进行充分的监测。"},{"i":14,"n":"第十四条","txt":"研究机构应当具备收集和处置实验废弃物的设施；对不在研究机构内处置的废弃物，应当具备暂存或者转运的条件。"},{"i":15,"n":"第十五条","txt":"研究机构应当根据研究工作的需要配备相应的仪器设备，其性能应当满足使用目的，放置地点合理，并定期进行清洁、保养、测试、校准、确认或者验证等，以确保其性能符合要求。"},{"i":16,"n":"第十六条","txt":"用于数据采集、传输、储存、处理、归档等的计算机化系统（或者包含有计算机系统的设备）应当进行验证。计算机化系统所产生的电子数据应当有保存完整的稽查轨迹和电子签名，以确保数据的完整性和有效性。"},{"i":17,"n":"第十七条","txt":"对于仪器设备，应当有标准操作规程详细说明各仪器设备的使用与管理要求，对仪器设备的使用、清洁、保养、测试、校准、确认或者验证以及维修等应当予以详细记录并归档保存。"},{"i":18,"n":"第十八条","txt":"受试物和对照品的使用和管理应当符合下列要求： （一）受试物和对照品应当有专人保管，有完善的接收、登记和分发的手续，每一批的受试物和对照品的批号、稳定性、含量或者浓度、纯度及其他理化性质应当有记录，对照品为市售商品时，可使用其标签或者说明书内容； （二）受试物和对照品的贮存保管条件应当符合其特定的要求，贮存的容器在保管、分发、使用时应当有标签，标明品名、缩写名、代号或者化学文摘登记号（CAS）、批号、浓度或者含量、有效期和贮存条件等信息； （三）受试物和对照品在分发过程中应当避免污染或者变质，并记录分发、归还的日期和数量； （四）当受试物和对照品需要与溶媒混合时，应当进行稳定性分析，确保受试物和对照品制剂处于稳定状态，并定期测定混合物制剂中受试物和对照品的浓度、均一性； （五）试验持续时间超过四周的研究，所使用的每一个批号的受试物和对照品均应当留取足够的样本，以备重新分析的需要，并在研究"},{"i":19,"n":"第十九条","txt":"实验室的试剂和溶液等均应当贴有标签，标明品名、浓度、贮存条件、配制日期及有效期等。研究中不得使用变质或者过期的试剂和溶液。"},{"i":20,"n":"第二十条","txt":"实验动物的管理应当符合下列要求： （一）实验动物的使用应当关注动物福利，遵循“减少、替代和优化”的原则，试验方案实施前应当获得动物伦理委员会批准。 （二）详细记录实验动物的来源、到达日期、数量、健康情况等信息；新进入设施的实验动物应当进行隔离和检疫，以确认其健康状况满足研究的要求；研究过程中实验动物如出现患病等情况，应当及时给予隔离、治疗等处理，诊断、治疗等相应的措施应当予以记录。 （三）实验动物在首次给予受试物、对照品前，应当有足够的时间适应试验环境。 （四）实验动物应当有合适的个体识别标识，以避免实验动物的不同个体在移出或者移入时发生混淆。 （五）实验动物所处的环境及相关用具应当定期清洁、消毒以保持卫生。动物饲养室内使用的清洁剂、消毒剂及杀虫剂等，不得影响试验结果，并应当详细记录其名称、浓度、使用方法及使用的时间等。 （六）实验动物的饲料、垫料和饮水应当定期检验，确保其符合营养或者"},{"i":21,"n":"第二十一条","txt":"实验动物以外的其他实验系统的来源、数量（体积）、质量属性、接收日期等应当予以详细记录，并在合适的环境条件下保存和操作使用；使用前应当开展适用性评估，如出现质量问题应当给予适当的处理并重新评估其适用性。"},{"i":22,"n":"第二十二条","txt":"研究机构应当制定与其业务相适应的标准操作规程，以确保数据的可靠性。公开出版的教科书、文献、生产商制定的用户手册等技术资料可以作为标准操作规程的补充说明加以使用。需要制定的标准操作规程通常包括但不限于以下方面： （一）标准操作规程的制定、修订和管理； （二）质量保证程序； （三）受试物和对照品的接收、标识、保存、处理、配制、领用及取样分析； （四）动物房和实验室的准备及环境因素的调控； （五）实验设施和仪器设备的维护、保养、校正、使用和管理等； （六）计算机化系统的安全、验证、使用、管理、变更控制和备份； （七）实验动物的接收、检疫、编号及饲养管理； （八）实验动物的观察记录及试验操作； （九）各种试验样品的采集、各种指标的检查和测定等操作技术； （十）濒死或者死亡实验动物的检查、处理； （十一）实验动物的解剖、组织病理学检查； （十二）标本的采集、编号和检验； （十三）各种试验数据的管"},{"i":23,"n":"第二十三条","txt":"标准操作规程及其修订版应当经过质量保证人员审查、机构负责人批准后方可生效。失效的标准操作规程除其原始文件归档保存之外，其余副本均应当及时销毁。"},{"i":24,"n":"第二十四条","txt":"标准操作规程的制定、修订、批准、生效的日期及分发、销毁的情况均应当予以记录并归档保存。"},{"i":25,"n":"第二十五条","txt":"标准操作规程的分发和存放应当确保工作人员使用方便。"},{"i":26,"n":"第二十六条","txt":"每个试验均应当有名称或者代号，并在研究相关的文件资料及试验记录中统一使用该名称或者代号。试验中所采集的各种样本均应当标明该名称或者代号、样本编号和采集日期。"},{"i":27,"n":"第二十七条","txt":"每项研究开始前，均应当起草一份试验方案，由质量保证部门对其符合本规范要求的情况进行审查并经专题负责人批准之后方可生效，专题负责人批准的日期作为研究的开始日期。接受委托的研究，试验方案应当经委托方认可。"},{"i":28,"n":"第二十八条","txt":"需要修改试验方案时应当进行试验方案变更，并经质量保证部门审查，专题负责人批准。试验方案变更应当包含变更的内容、理由及日期，并与原试验方案一起保存。研究被取消或者终止时，试验方案变更应当说明取消或者终止的原因和终止的方法。"},{"i":29,"n":"第二十九条","txt":"试验方案的主要内容应当包括： （一）研究的名称或者代号，研究目的； （二）所有参与研究的研究机构和委托方的名称、地址和联系方式； （三）专题负责人和参加试验的主要工作人员姓名，多场所研究的情况下应当明确负责各部分试验工作的研究场所、主要研究者姓名及其所承担的工作内容； （四）研究所依据的试验标准、技术指南或者文献以及研究遵守的非临床研究质量管理规范； （五）受试物和对照品的名称、缩写名、代号、批号、稳定性、浓度或者含量、纯度、组分等有关理化性质及生物特性； （六）研究用的溶媒、乳化剂及其他介质的名称、批号、有关的理化性质或者生物特性； （七）实验系统及选择理由； （八）实验系统的种、系、数量、年龄、性别、体重范围、来源、等级以及其他相关信息； （九）实验系统的识别方法； （十）试验的环境条件； （十一）饲料、垫料、饮用水等的名称或者代号、来源、批号以及主要控制指标； （十二）受试物和对"},{"i":30,"n":"第三十条","txt":"参加研究的工作人员应当严格执行试验方案和相应的标准操作规程，记录试验产生的所有数据，并做到及时、直接、准确、清楚和不易消除，同时需注明记录日期、记录者签名。记录的数据需要修改时，应当保持原记录清楚可辨，并注明修改的理由及修改日期、修改者签名。电子数据的生成、修改应当符合以上要求。 研究过程中发生的任何偏离试验方案和标准操作规程的情况，都应当及时记录并报告给专题负责人，在多场所研究的情况下还应当报告给负责相关试验的主要研究者。专题负责人或者主要研究者应当评估对研究数据的可靠性造成的影响，必要时采取纠正措施。"},{"i":31,"n":"第三十一条","txt":"进行病理学同行评议工作时，同行评议的计划、管理、记录和报告应当符合以下要求： （一）病理学同行评议工作应当在试验方案或者试验方案变更中详细描述； （二）病理学同行评议的过程，以及复查的标本和文件应当详细记录并可追溯； （三）制定同行评议病理学家和专题病理学家意见分歧时的处理程序； （四）同行评议后的结果与专题病理学家的诊断结果有重要变化时，应当在总结报告中论述说明； （五）同行评议完成后由同行评议病理学家出具同行评议声明并签字注明日期； （六）总结报告中应当注明同行评议病理学家的姓名、资质和单位。"},{"i":32,"n":"第三十二条","txt":"所有研究均应当有总结报告。总结报告应当经质量保证部门审查，最终由专题负责人签字批准，批准日期作为研究完成的日期。研究被取消或者终止时，专题负责人应当撰写简要试验报告。"},{"i":33,"n":"第三十三条","txt":"总结报告主要内容应当包括： （一）研究的名称、代号及研究目的； （二）所有参与研究的研究机构和委托方的名称、地址和联系方式； （三）研究所依据的试验标准、技术指南或者文献以及研究遵守的非临床研究质量管理规范； （四）研究起止日期； （五）专题负责人、主要研究者以及参加工作的主要人员姓名和承担的工作内容； （六）受试物和对照品的名称、缩写名、代号、批号、稳定性、含量、浓度、纯度、组分及其他质量特性、受试物和对照品制剂的分析结果，研究用的溶媒、乳化剂及其他介质的名称、批号、有关的理化性质或者生物特性； （七）实验系统的种、系、数量、年龄、性别、体重范围、来源、实验动物合格证号、接收日期和饲养条件； （八）受试物和对照品的给药途径、剂量、方法、频率和给药期限； （九）受试物和对照品的剂量设计依据； （十）各种指标的检测方法和频率； （十一）分析数据所采用的统计方法； （十二）结果和结论； （"},{"i":34,"n":"第三十四条","txt":"总结报告被批准后，需要修改或者补充时，应当以修订文件的形式予以修改或者补充，详细说明修改或者补充的内容、理由，并经质量保证部门审查，由专题负责人签署姓名和日期予以批准。为了满足注册申报要求修改总结报告格式的情况不属于总结报告的修订。"},{"i":35,"n":"第三十五条","txt":"研究机构应当确保质量保证工作的独立性。质量保证人员不能参与具体研究的实施，或者承担可能影响其质量保证工作独立性的其他工作。"},{"i":36,"n":"第三十六条","txt":"质量保证部门应当制定书面的质量保证计划，并指定执行人员，以确保研究机构的研究工作符合本规范的要求。"},{"i":37,"n":"第三十七条","txt":"质量保证部门应当对质量保证活动制定相应的标准操作规程，包括质量保证部门的运行、质量保证计划及检查计划的制定、实施、记录和报告，以及相关资料的归档保存等。"},{"i":38,"n":"第三十八条","txt":"质量保证检查可分为三种检查类型： （一）基于研究的检查，该类检查一般基于特定研究项目的进度和关键阶段进行； （二）基于设施的检查，该类检查一般基于研究机构内某个通用设施和活动（安装、支持服务、计算机系统、培训、环境监测、维护和校准等）进行； （三）基于过程的检查，该类检查一般不基于特定研究项目，而是基于某个具有重复性质的程序或者过程来进行。 质量保证检查应当有过程记录和报告，必要时应当提供给监管部门检查。"},{"i":39,"n":"第三十九条","txt":"质量保证部门应当对所有遵照本规范实施的研究项目进行审核并出具质量保证声明。质量保证声明应当包含完整的研究识别信息、相关质量保证检查活动以及报告的日期和阶段。任何对已完成总结报告的修改或者补充应当重新进行审核并签署质量保证声明。"},{"i":40,"n":"第四十条","txt":"质量保证人员在签署质量保证声明前，应当确认试验符合本规范的要求，遵照试验方案和标准操作规程执行，确认总结报告准确、可靠地反映原始数据。"},{"i":41,"n":"第四十一条","txt":"专题负责人应当确保研究所有的资料，包括试验方案的原件、原始数据、标本、相关检测报告、留样受试物和对照品、总结报告的原件以及研究有关的各种文件，在研究实施过程中或者研究完成后及时归档，最长不超过两周，按标准操作规程的要求整理后，作为研究档案予以保存。"},{"i":42,"n":"第四十二条","txt":"研究被取消或者终止时，专题负责人应当将已经生成的上述研究资料作为研究档案予以保存归档。"},{"i":43,"n":"第四十三条","txt":"其他不属于研究档案范畴的资料，包括质量保证部门所有的检查记录及报告、主计划表、工作人员的教育背景、工作经历、培训情况、获准资质、岗位描述的资料、仪器设备及计算机化系统的相关资料、研究机构的人员组织结构文件、所有标准操作规程的历史版本文件、环境条件监测数据等，均应当定期归档保存。应当在标准操作规程中对具体的归档时限、负责人员提出明确要求。"},{"i":44,"n":"第四十四条","txt":"档案应当由机构负责人指定的专人按标准操作规程的要求进行管理，并对其完整性负责，同时应当建立档案索引以便于检索。进入档案设施的人员需获得授权。档案设施中放入或者取出材料应当准确记录。"},{"i":45,"n":"第四十五条","txt":"档案的保存期限应当满足以下要求： （一）用于注册申报材料的研究，其档案保存期应当在药物上市后至少五年； （二）未用于注册申报材料的研究（如终止的研究），其档案保存期为总结报告批准日后至少五年； （三）其他不属于研究档案范畴的资料应当在其生成后保存至少十年。"},{"i":46,"n":"第四十六条","txt":"档案保管期满时，可对档案采取包括销毁在内的必要处理，所采取的处理措施和过程应当按照标准操作规程进行，并有准确的记录。在可能的情况下，研究档案的处理应当得到委托方的同意。"},{"i":47,"n":"第四十七条","txt":"对于质量容易变化的档案，如组织器官、电镜标本、血液涂片、受试物和对照品留样样品等，应当以能够进行有效评价为保存期限。对于电子数据，应当建立数据备份与恢复的标准操作规程，以确保其安全性、完整性和可读性，其保存期限应当符合本规范第四十五条的要求。"},{"i":48,"n":"第四十八条","txt":"研究机构出于停业等原因不再执行本规范的要求、且没有合法的继承者时，其保管的档案应当转移到委托方的档案设施或者委托方指定的档案设施中进行保管，直至档案最终的保管期限。接收转移档案的档案设施应当严格执行本规范的要求，对其接收的档案进行有效的管理并接受监管部门的监督。"},{"i":49,"n":"第四十九条","txt":"委托方作为研究工作的发起者和研究结果的申报者，对用于申报注册的研究资料负责，并承担以下责任： （一）理解本规范的要求，尤其是机构负责人、专题负责人、主要研究者的职责要求； （二）委托非临床安全性评价研究前，通过考察等方式对研究机构进行评估，以确认其能够遵守本规范的要求进行研究； （三）在研究开始之前，试验方案应当得到委托方的认可； （四）告知研究机构受试物和对照品的相关安全信息，以确保研究机构采取必要的防护措施，避免人身健康和环境安全的潜在风险； （五）对受试物和对照品的特性进行检测的工作可由委托方、其委托的研究机构或者实验室完成，委托方应当确保其提供的受试物、对照品的特性信息真实、准确； （六）确保研究按照本规范的要求实施。"},{"i":50,"n":"第五十条","txt":"本规范自2017年9月1日起施行，2003年8月6日发布的《药物非临床研究质量管理规范》（原国家食品药品监督管理局令第2号）同时废止。"}],"danbaitonghuazhijihetaileijisujinchukouguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范蛋白同化制剂、肽类激素的进出口管理，根据《中华人民共和国药品管理法》《中华人民共和国海关法》《反兴奋剂条例》等法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"国家对蛋白同化制剂、肽类激素实行进出口准许证管理。"},{"i":3,"n":"第三条","txt":"进口蛋白同化制剂、肽类激素，进口单位应当向所在地省、自治区、直辖市食品药品监督管理部门提出申请。"},{"i":4,"n":"第四条","txt":"进口供医疗使用的蛋白同化制剂、肽类激素，进口单位应当报送以下资料： （一）药品进口申请表。 （二）购货合同或者订单复印件。 （三）《进口药品注册证》（或者《医药产品注册证》）（正本或者副本）复印件。 （四）进口单位的《药品经营许可证》《企业法人营业执照》《进出口企业资格证书》（或者《对外贸易经营者备案登记表》）复印件；药品生产企业进口本企业所需原料药和制剂中间体（包括境内分包装用制剂），应当报送《药品生产许可证》《企业法人营业执照》复印件。 （五）《进口药品注册证》（或者《医药产品注册证》）持有者如委托其他公司代理出口其药品的，需提供委托出口函。 上述各类复印件应当加盖进口单位公章。"},{"i":5,"n":"第五条","txt":"因教学、科研需要而进口蛋白同化制剂、肽类激素的，进口单位应当报送以下资料： （一）药品进口申请表； （二）购货合同或者订单复印件； （三）国内使用单位合法资质的证明文件、药品使用数量的测算依据以及使用单位出具的合法使用和管理该药品保证函； （四）相应科研项目的批准文件或者相应主管部门的批准文件； （五）接受使用单位委托代理进口的，还需提供委托代理协议复印件和进口单位的《企业法人营业执照》《进出口企业资格证书》（或者《对外贸易经营者备案登记表》）复印件。 上述各类复印件应当加盖进口单位公章。"},{"i":6,"n":"第六条","txt":"境内企业因接受境外企业委托生产而需要进口蛋白同化制剂、肽类激素的，报送本办法第五条第一款第（一）项、第（三）项、第（五）项规定的资料。 上述各类复印件应当加盖进口单位公章。"},{"i":7,"n":"第七条","txt":"省、自治区、直辖市食品药品监督管理部门收到进口申请及有关资料后，应当于15个工作日内作出是否同意进口的决定；对同意进口的，发给药品《进口准许证》；对不同意进口的，应当书面说明理由。"},{"i":8,"n":"第八条","txt":"进口蛋白同化制剂、肽类激素必须经由国务院批准的允许药品进口的口岸进口。进口单位持省、自治区、直辖市食品药品监督管理部门核发的药品《进口准许证》向海关办理报关手续。进口蛋白同化制剂、肽类激素无需办理《进口药品通关单》。"},{"i":9,"n":"第九条","txt":"进口供医疗使用的蛋白同化制剂、肽类激素（包括首次在中国销售的），进口单位应当于进口手续完成后，及时填写《进口药品报验单》，持《进口药品注册证》（或者《医药产品注册证》）原件（正本或者副本）、药品《进口准许证》原件，向进口口岸食品药品监督管理部门报送下列资料一式两份，申请办理《进口药品口岸检验通知书》： （一）《进口药品注册证》（或者《医药产品注册证》）（正本或者副本）和药品《进口准许证》复印件； （二）进口单位的《药品生产许可证》或者《药品经营许可证》复印件，《企业法人营业执照》复印件； （三）原产地证明复印件； （四）购货合同复印件； （五）装箱单、提运单和货运发票复印件； （六）出厂检验报告书复印件； （七）药品说明书及包装、标签的式样（原料药和制剂中间体除外）。 上述各类复印件应当加盖进口单位公章。"},{"i":10,"n":"第十条","txt":"口岸食品药品监督管理部门接到《进口药品报验单》及相关资料，审查无误后，将《进口药品注册证》（或者《医药产品注册证》）（正本或者副本）原件、药品《进口准许证》原件交还进口单位，并应当于当日向负责检验的口岸药品检验所发出《进口药品口岸检验通知书》，附本办法第九条规定的资料1份。 口岸药品检验所接到《进口药品口岸检验通知书》后，应当在2个工作日内与进口单位联系，到存货地点进行抽样，抽样完成后，应当在药品《进口准许证》原件第一联背面注明“已抽样”字样，并加盖抽样单位的公章。"},{"i":11,"n":"第十一条","txt":"因教学、科研需要而进口的蛋白同化制剂、肽类激素以及境内企业接受境外企业委托生产而需要进口的蛋白同化制剂、肽类激素，予以免检。对免检的进口蛋白同化制剂、肽类激素，其收货人不免除持进口准许证向海关办理手续的义务。"},{"i":12,"n":"第十二条","txt":"有下列情形之一的，口岸食品药品监督管理部门应当及时将有关情况通告发证机关： （一）口岸食品药品监督管理部门根据《药品进口管理办法》第十七条规定，不予发放《进口药品口岸检验通知书》的； （二）口岸药品检验所根据《药品进口管理办法》第二十五条规定，不予抽样的。 口岸食品药品监督管理部门对具有前款情形并已进口的全部药品，应当采取查封、扣押的行政强制措施，并于查封、扣押之日起7日内作出责令复运出境决定，通知进口单位按照本办法规定的蛋白同化制剂、肽类激素出口程序办理药品《出口准许证》，将进口药品全部退回原出口国。 进口单位收到责令复运出境决定之日起10日内不答复或者未明确表示复运出境的，已查封、扣押的药品由口岸食品药品监督管理部门监督销毁。"},{"i":13,"n":"第十三条","txt":"进口的蛋白同化制剂、肽类激素经口岸药品检验所检验不符合标准规定的，进口单位应当在收到《进口药品检验报告书》后2日内，将全部进口药品流通、使用的详细情况，报告所在地口岸食品药品监督管理部门。 口岸食品药品监督管理部门收到《进口药品检验报告书》后，应当及时采取对全部药品予以查封、扣押的行政强制措施，并在7日内作出是否立案的决定。 进口单位未在规定时间内提出复验或者经复验仍不符合标准规定的，口岸食品药品监督管理部门应当作出责令复运出境决定，通知进口单位按照本办法规定的蛋白同化制剂、肽类激素出口程序办理药品《出口准许证》，将进口药品全部退回原出口国。进口单位收到责令复运出境决定之日起10日内不答复或者未明确表示复运出境的，由口岸食品药品监督管理部门监督销毁。 经复验符合标准规定的，口岸食品药品监督管理部门应当解除查封、扣押的行政强制措施。 口岸食品药品监督管理部门应当将按照本条第二款、第三款、"},{"i":14,"n":"第十四条","txt":"国内药品生产企业、经营企业以及医疗机构采购进口蛋白同化制剂、肽类激素时，供货单位应当提供《进口药品注册证》（或者《医药产品注册证》）复印件、药品《进口准许证》复印件和《进口药品检验报告书》复印件，并在上述各类复印件上加盖供货单位公章。"},{"i":15,"n":"第十五条","txt":"出口蛋白同化制剂、肽类激素，出口单位应当向所在地省、自治区、直辖市食品药品监督管理部门提出申请，报送下列资料： （一）药品出口申请表。 （二）进口国家或者地区的药品管理机构提供的进口准许证正本（或者复印件及公证文本）。 如进口国家或者地区对蛋白同化制剂、肽类激素进口尚未实行许可证管理制度，需提供进口国家的药品管理机构提供的该类药品进口无需核发进口准许证的证明文件（正本）以及以下文件之一： 1.进口国家或者地区的药品管理机构提供的同意进口该药品的证明文件正本（或者复印件及公证文本）； 2.进口单位合法资质的证明文件和该药品用途合法的证明文件正本（或者复印件及公证文本）。 （三）购货合同或者订单复印件（自营产品出口的生产企业除外）。 （四）外销合同或者订单复印件。 （五）出口药品如为国内药品生产企业经批准生产的品种，须提供该药品生产企业的《药品生产许可证》《企业法人营业执照》及药品的批准证"},{"i":16,"n":"第十六条","txt":"按照本办法第十二条、第十三条规定复运出境的，申请药品《出口准许证》时，应当提供下列资料： （一）出口国原出口单位申请退货的证明材料； （二）药品《进口准许证》。"},{"i":17,"n":"第十七条","txt":"省、自治区、直辖市食品药品监督管理部门收到出口申请及有关资料后，应当于15个工作日内作出是否同意出口的决定；对同意出口的，发给药品《出口准许证》；对不同意出口的，应当书面说明理由。 对根据本办法第十六条规定申请办理药品《出口准许证》的，发证机关应当在药品《出口准许证》上注明“原货退回”字样。"},{"i":18,"n":"第十八条","txt":"出口单位持省、自治区、直辖市食品药品监督管理部门核发的药品《出口准许证》向海关办理报关手续。"},{"i":19,"n":"第十九条","txt":"进出口单位在办理报关手续时，应当多提交一联报关单，并向海关申请签退该联报关单。海关凭药品《进口准许证》《出口准许证》在该联报关单上加盖“验讫章”后退进出口单位。 进出口完成后1个月内，进出口单位应当将药品《进口准许证》《出口准许证》的第一联、海关签章的报关单退回发证机关。 取得药品进出口准许证后未进行相关进出口贸易的，进出口单位应当于准许证有效期满后1个月内将原准许证退回发证机关。"},{"i":20,"n":"第二十条","txt":"药品《进口准许证》有效期1年。药品《出口准许证》有效期不超过3个月（有效期时限不跨年度）。 药品《进口准许证》《出口准许证》实行“一证一关”，只能在有效期内一次性使用，证面内容不得更改。因故延期进出口的，可以持原进出口准许证办理一次延期换证手续。"},{"i":21,"n":"第二十一条","txt":"药品《进口准许证》《出口准许证》如有遗失，进出口单位应当立即向原发证机关书面报告挂失。原发证机关收到挂失报告后，通知口岸海关。原发证机关经核实无不良后果的，予以重新补发。"},{"i":22,"n":"第二十二条","txt":"药品《进口准许证》《出口准许证》由国家食品药品监督管理总局统一印制。"},{"i":23,"n":"第二十三条","txt":"以加工贸易方式进出口蛋白同化制剂、肽类激素的，海关凭药品《进口准许证》《出口准许证》办理验放手续并实施监管。确因特殊情况无法出口的，移交货物所在地食品药品监督管理部门按规定处理，海关凭有关证明材料办理核销手续。"},{"i":24,"n":"第二十四条","txt":"海关特殊监管区域和保税监管场所与境外进出及海关特殊监管区域、保税监管场所之间进出的蛋白同化制剂、肽类激素，免予办理药品《进口准许证》《出口准许证》，由海关实施监管。 从海关特殊监管区域和保税监管场所进入境内区外的蛋白同化制剂、肽类激素，应当办理药品《进口准许证》。 从境内区外进入海关特殊监管区域和保税监管场所的蛋白同化制剂、肽类激素，应当办理药品《出口准许证》。"},{"i":25,"n":"第二十五条","txt":"个人因医疗需要携带或者邮寄进出境自用合理数量范围内的蛋白同化制剂、肽类激素的，海关按照卫生计生部门有关处方的管理规定凭医疗机构处方予以验放。"},{"i":26,"n":"第二十六条","txt":"除本办法另有规定外，供医疗使用的蛋白同化制剂、肽类激素的进口、口岸检验、监督管理等方面，参照《药品进口管理办法》有关药品进口的规定执行。"},{"i":27,"n":"第二十七条","txt":"本办法所称进口供医疗使用的蛋白同化制剂、肽类激素，是指进口的蛋白同化制剂、肽类激素拟用于生产制剂或者拟在中国境内上市销售。 进口单位：是指依照本办法取得的药品《进口准许证》上载明的进口单位。 出口单位：是指依照本办法取得的药品《出口准许证》上载明的出口单位。"},{"i":28,"n":"第二十八条","txt":"本办法自2014年12月1日起施行。2006年7月28日公布的《蛋白同化制剂、肽类激素进出口管理办法（暂行）》（国家食品药品监督管理局、海关总署、国家体育总局令第25号）同时废止。"}],"shipinzhaohuiguanlibanfa-2":[{"i":1,"n":"第一条","txt":"为加强食品生产经营管理，减少和避免不安全食品的危害，保障公众身体健康和生命安全，根据《中华人民共和国食品安全法》及其实施条例等法律法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内，不安全食品的停止生产经营、召回和处置及其监督管理，适用本办法。 不安全食品是指食品安全法律法规规定禁止生产经营的食品以及其他有证据证明可能危害人体健康的食品。"},{"i":3,"n":"第三条","txt":"食品生产经营者应当依法承担食品安全第一责任人的义务，建立健全相关管理制度，收集、分析食品安全信息，依法履行不安全食品的停止生产经营、召回和处置义务。"},{"i":4,"n":"第四条","txt":"国家市场监督管理总局负责指导全国不安全食品停止生产经营、召回和处置的监督管理工作。 县级以上地方市场监督管理部门负责本行政区域的不安全食品停止生产经营、召回和处置的监督管理工作。"},{"i":5,"n":"第五条","txt":"县级以上市场监督管理部门组织建立由医学、毒理、化学、食品、法律等相关领域专家组成的食品安全专家库，为不安全食品的停止生产经营、召回和处置提供专业支持。"},{"i":6,"n":"第六条","txt":"国家市场监督管理总局负责汇总分析全国不安全食品的停止生产经营、召回和处置信息，根据食品安全风险因素，完善食品安全监督管理措施。 县级以上地方市场监督管理部门负责收集、分析和处理本行政区域不安全食品的停止生产经营、召回和处置信息，监督食品生产经营者落实主体责任。"},{"i":7,"n":"第七条","txt":"鼓励和支持食品行业协会加强行业自律，制定行业规范，引导和促进食品生产经营者依法履行不安全食品的停止生产经营、召回和处置义务。 鼓励和支持公众对不安全食品的停止生产经营、召回和处置等活动进行社会监督。"},{"i":8,"n":"第八条","txt":"食品生产经营者发现其生产经营的食品属于不安全食品的，应当立即停止生产经营，采取通知或者公告的方式告知相关食品生产经营者停止生产经营、消费者停止食用，并采取必要的措施防控食品安全风险。 食品生产经营者未依法停止生产经营不安全食品的，县级以上市场监督管理部门可以责令其停止生产经营不安全食品。"},{"i":9,"n":"第九条","txt":"食品集中交易市场的开办者、食品经营柜台的出租者、食品展销会的举办者发现食品经营者经营的食品属于不安全食品的，应当及时采取有效措施，确保相关经营者停止经营不安全食品。"},{"i":10,"n":"第十条","txt":"网络食品交易第三方平台提供者发现网络食品经营者经营的食品属于不安全食品的，应当依法采取停止网络交易平台服务等措施，确保网络食品经营者停止经营不安全食品。"},{"i":11,"n":"第十一条","txt":"食品生产经营者生产经营的不安全食品未销售给消费者，尚处于其他生产经营者控制中的，食品生产经营者应当立即追回不安全食品，并采取必要措施消除风险。"},{"i":12,"n":"第十二条","txt":"食品生产者通过自检自查、公众投诉举报、经营者和监督管理部门告知等方式知悉其生产经营的食品属于不安全食品的，应当主动召回。 食品生产者应当主动召回不安全食品而没有主动召回的，县级以上市场监督管理部门可以责令其召回。"},{"i":13,"n":"第十三条","txt":"根据食品安全风险的严重和紧急程度，食品召回分为三级： （一）一级召回：食用后已经或者可能导致严重健康损害甚至死亡的，食品生产者应当在知悉食品安全风险后24小时内启动召回，并向县级以上地方市场监督管理部门报告召回计划。 （二）二级召回：食用后已经或者可能导致一般健康损害，食品生产者应当在知悉食品安全风险后48小时内启动召回，并向县级以上地方市场监督管理部门报告召回计划。 （三）三级召回：标签、标识存在虚假标注的食品，食品生产者应当在知悉食品安全风险后72小时内启动召回，并向县级以上地方市场监督管理部门报告召回计划。标签、标识存在瑕疵，食用后不会造成健康损害的食品，食品生产者应当改正，可以自愿召回。"},{"i":14,"n":"第十四条","txt":"食品生产者应当按照召回计划召回不安全食品。 县级以上地方市场监督管理部门收到食品生产者的召回计划后，必要时可以组织专家对召回计划进行评估。评估结论认为召回计划应当修改的，食品生产者应当立即修改，并按照修改后的召回计划实施召回。"},{"i":15,"n":"第十五条","txt":"食品召回计划应当包括下列内容： （一）食品生产者的名称、住所、法定代表人、具体负责人、联系方式等基本情况； （二）食品名称、商标、规格、生产日期、批次、数量以及召回的区域范围； （三）召回原因及危害后果； （四）召回等级、流程及时限； （五）召回通知或者公告的内容及发布方式； （六）相关食品生产经营者的义务和责任； （七）召回食品的处置措施、费用承担情况； （八）召回的预期效果。"},{"i":16,"n":"第十六条","txt":"食品召回公告应当包括下列内容： （一）食品生产者的名称、住所、法定代表人、具体负责人、联系电话、电子邮箱等； （二）食品名称、商标、规格、生产日期、批次等； （三）召回原因、等级、起止日期、区域范围； （四）相关食品生产经营者的义务和消费者退货及赔偿的流程。"},{"i":17,"n":"第十七条","txt":"不安全食品在本省、自治区、直辖市销售的，食品召回公告应当在省级市场监督管理部门网站和省级主要媒体上发布。省级市场监督管理部门网站发布的召回公告应当与国家市场监督管理总局网站链接。 不安全食品在两个以上省、自治区、直辖市销售的，食品召回公告应当在国家市场监督管理总局网站和中央主要媒体上发布。"},{"i":18,"n":"第十八条","txt":"实施一级召回的，食品生产者应当自公告发布之日起10个工作日内完成召回工作。 实施二级召回的，食品生产者应当自公告发布之日起20个工作日内完成召回工作。 实施三级召回的，食品生产者应当自公告发布之日起30个工作日内完成召回工作。 情况复杂的，经县级以上地方市场监督管理部门同意，食品生产者可以适当延长召回时间并公布。"},{"i":19,"n":"第十九条","txt":"食品经营者知悉食品生产者召回不安全食品后，应当立即采取停止购进、销售，封存不安全食品，在经营场所醒目位置张贴生产者发布的召回公告等措施，配合食品生产者开展召回工作。"},{"i":20,"n":"第二十条","txt":"食品经营者对因自身原因所导致的不安全食品，应当根据法律法规的规定在其经营的范围内主动召回。 食品经营者召回不安全食品应当告知供货商。供货商应当及时告知生产者。 食品经营者在召回通知或者公告中应当特别注明系因其自身的原因导致食品出现不安全问题。"},{"i":21,"n":"第二十一条","txt":"因生产者无法确定、破产等原因无法召回不安全食品的，食品经营者应当在其经营的范围内主动召回不安全食品。"},{"i":22,"n":"第二十二条","txt":"食品经营者召回不安全食品的程序，参照食品生产者召回不安全食品的相关规定处理。"},{"i":23,"n":"第二十三条","txt":"食品生产经营者应当依据法律法规的规定，对因停止生产经营、召回等原因退出市场的不安全食品采取补救、无害化处理、销毁等处置措施。 食品生产经营者未依法处置不安全食品的，县级以上地方市场监督管理部门可以责令其依法处置不安全食品。"},{"i":24,"n":"第二十四条","txt":"对违法添加非食用物质、腐败变质、病死畜禽等严重危害人体健康和生命安全的不安全食品，食品生产经营者应当立即就地销毁。 不具备就地销毁条件的，可由不安全食品生产经营者集中销毁处理。食品生产经营者在集中销毁处理前，应当向县级以上地方市场监督管理部门报告。"},{"i":25,"n":"第二十五条","txt":"对因标签、标识等不符合食品安全标准而被召回的食品，食品生产者可以在采取补救措施且能保证食品安全的情况下继续销售，销售时应当向消费者明示补救措施。"},{"i":26,"n":"第二十六条","txt":"对不安全食品进行无害化处理，能够实现资源循环利用的，食品生产经营者可以按照国家有关规定进行处理。"},{"i":27,"n":"第二十七条","txt":"食品生产经营者对不安全食品处置方式不能确定的，应当组织相关专家进行评估，并根据评估意见进行处置。"},{"i":28,"n":"第二十八条","txt":"食品生产经营者应当如实记录停止生产经营、召回和处置不安全食品的名称、商标、规格、生产日期、批次、数量等内容。记录保存期限不得少于2年。"},{"i":29,"n":"第二十九条","txt":"县级以上地方市场监督管理部门发现不安全食品的，应当通知相关食品生产经营者停止生产经营或者召回，采取相关措施消除食品安全风险。"},{"i":30,"n":"第三十条","txt":"县级以上地方市场监督管理部门发现食品生产经营者生产经营的食品可能属于不安全食品的，可以开展调查分析，相关食品生产经营者应当积极协助。"},{"i":31,"n":"第三十一条","txt":"县级以上地方市场监督管理部门可以对食品生产经营者停止生产经营、召回和处置不安全食品情况进行现场监督检查。"},{"i":32,"n":"第三十二条","txt":"食品生产经营者停止生产经营、召回和处置的不安全食品存在较大风险的，应当在停止生产经营、召回和处置不安全食品结束后5个工作日内向县级以上地方市场监督管理部门书面报告情况。"},{"i":33,"n":"第三十三条","txt":"县级以上地方市场监督管理部门可以要求食品生产经营者定期或者不定期报告不安全食品停止生产经营、召回和处置情况。"},{"i":34,"n":"第三十四条","txt":"县级以上地方市场监督管理部门可以对食品生产经营者提交的不安全食品停止生产经营、召回和处置报告进行评价。 评价结论认为食品生产经营者采取的措施不足以控制食品安全风险的，县级以上地方市场监督管理部门应当责令食品生产经营者采取更为有效的措施停止生产经营、召回和处置不安全食品。"},{"i":35,"n":"第三十五条","txt":"为预防和控制食品安全风险，县级以上地方市场监督管理部门可以发布预警信息，要求相关食品生产经营者停止生产经营不安全食品，提示消费者停止食用不安全食品。"},{"i":36,"n":"第三十六条","txt":"县级以上地方市场监督管理部门将不安全食品停止生产经营、召回和处置情况记入食品生产经营者信用档案。"},{"i":37,"n":"第三十七条","txt":"食品生产经营者违反本办法有关不安全食品停止生产经营、召回和处置的规定，食品安全法律法规有规定的，依照相关规定处理。"},{"i":38,"n":"第三十八条","txt":"食品生产经营者违反本办法第八条第一款、第十二条第一款、第十三条、第十四条、第二十条第一款、第二十一条、第二十三条第一款、第二十四条第一款的规定，不立即停止生产经营、不主动召回、不按规定时限启动召回、不按照召回计划召回不安全食品或者不按照规定处置不安全食品的，由市场监督管理部门给予警告，并处1万元以上3万元以下罚款。"},{"i":39,"n":"第三十九条","txt":"食品经营者违反本办法第十九条的规定，不配合食品生产者召回不安全食品的，由市场监督管理部门给予警告，并处5000元以上3万元以下罚款。"},{"i":40,"n":"第四十条","txt":"食品生产经营者违反本办法第十三条、第二十四条第二款、第三十二条的规定，未按规定履行相关报告义务的，由市场监督管理部门责令改正，给予警告；拒不改正的，处2000元以上2万元以下罚款。"},{"i":41,"n":"第四十一条","txt":"食品生产经营者违反本办法第二十三条第二款的规定，市场监督管理部门责令食品生产经营者依法处置不安全食品，食品生产经营者拒绝或者拖延履行的，由市场监督管理部门给予警告，并处2万元以上3万元以下罚款。"},{"i":42,"n":"第四十二条","txt":"食品生产经营者违反本办法第二十八条的规定，未按规定记录保存不安全食品停止生产经营、召回和处置情况的，由市场监督管理部门责令改正，给予警告；拒不改正的，处2000元以上2万元以下罚款。"},{"i":43,"n":"第四十三条","txt":"食品生产经营者停止生产经营、召回和处置不安全食品，不免除其依法应当承担的其他法律责任。 食品生产经营者主动采取停止生产经营、召回和处置不安全食品措施，消除或者减轻危害后果的，依法从轻或者减轻处罚；违法情节轻微并及时纠正，没有造成危害后果的，不予行政处罚。"},{"i":44,"n":"第四十四条","txt":"县级以上地方市场监督管理部门不依法履行本办法规定的职责，造成不良后果的，依照《中华人民共和国食品安全法》的有关规定，对直接负责的主管人员和其他直接责任人员给予行政处分。"},{"i":45,"n":"第四十五条","txt":"本办法适用于食品、食品添加剂和保健食品。 食品生产经营者对进入批发、零售市场或者生产加工企业后的食用农产品的停止经营、召回和处置，参照本办法执行。"},{"i":46,"n":"第四十六条","txt":"本办法自2015年9月1日起施行。"}],"shipinjingyingxukeguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范食品经营许可活动，加强食品经营监督管理，保障食品安全，根据《中华人民共和国食品安全法》《中华人民共和国行政许可法》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内，从事食品销售和餐饮服务活动，应当依法取得食品经营许可。 食品经营许可的申请、受理、审查、决定及其监督检查，适用本办法。"},{"i":3,"n":"第三条","txt":"食品经营许可应当遵循依法、公开、公平、公正、便民、高效的原则。"},{"i":4,"n":"第四条","txt":"食品经营许可实行一地一证原则，即食品经营者在一个经营场所从事食品经营活动，应当取得一个食品经营许可证。"},{"i":5,"n":"第五条","txt":"食品药品监督管理部门按照食品经营主体业态和经营项目的风险程度对食品经营实施分类许可。"},{"i":6,"n":"第六条","txt":"国家食品药品监督管理总局负责监督指导全国食品经营许可管理工作。 县级以上地方食品药品监督管理部门负责本行政区域内的食品经营许可管理工作。 省、自治区、直辖市食品药品监督管理部门可以根据食品类别和食品安全风险状况，确定市、县级食品药品监督管理部门的食品经营许可管理权限。"},{"i":7,"n":"第七条","txt":"国家食品药品监督管理总局负责制定食品经营许可审查通则。 县级以上地方食品药品监督管理部门实施食品经营许可审查，应当遵守食品经营许可审查通则。"},{"i":8,"n":"第八条","txt":"县级以上食品药品监督管理部门应当加快信息化建设，在行政机关的网站上公布经营许可事项，方便申请人采取数据电文等方式提出经营许可申请，提高办事效率。"},{"i":9,"n":"第九条","txt":"申请食品经营许可，应当先行取得营业执照等合法主体资格。 企业法人、合伙企业、个人独资企业、个体工商户等，以营业执照载明的主体作为申请人。 机关、事业单位、社会团体、民办非企业单位、企业等申办单位食堂，以机关或者事业单位法人登记证、社会团体登记证或者营业执照等载明的主体作为申请人。"},{"i":10,"n":"第十条","txt":"申请食品经营许可，应当按照食品经营主体业态和经营项目分类提出。 食品经营主体业态分为食品销售经营者、餐饮服务经营者、单位食堂。食品经营者申请通过网络经营、建立中央厨房或者从事集体用餐配送的，应当在主体业态后以括号标注。 食品经营项目分为预包装食品销售（含冷藏冷冻食品、不含冷藏冷冻食品）、散装食品销售（含冷藏冷冻食品、不含冷藏冷冻食品）、特殊食品销售（保健食品、特殊医学用途配方食品、婴幼儿配方乳粉、其他婴幼儿配方食品）、其他类食品销售；热食类食品制售、冷食类食品制售、生食类食品制售、糕点类食品制售、自制饮品制售、其他类食品制售等。 列入其他类食品销售和其他类食品制售的具体品种应当报国家食品药品监督管理总局批准后执行，并明确标注。具有热、冷、生、固态、液态等多种情形，难以明确归类的食品，可以按照食品安全风险等级最高的情形进行归类。 国家食品药品监督管理总局可以根据监督管理工作需要对食品经营"},{"i":11,"n":"第十一条","txt":"申请食品经营许可，应当符合下列条件： （一）具有与经营的食品品种、数量相适应的食品原料处理和食品加工、销售、贮存等场所，保持该场所环境整洁，并与有毒、有害场所以及其他污染源保持规定的距离； （二）具有与经营的食品品种、数量相适应的经营设备或者设施，有相应的消毒、更衣、盥洗、采光、照明、通风、防腐、防尘、防蝇、防鼠、防虫、洗涤以及处理废水、存放垃圾和废弃物的设备或者设施； （三）有专职或者兼职的食品安全管理人员和保证食品安全的规章制度； （四）具有合理的设备布局和工艺流程，防止待加工食品与直接入口食品、原料与成品交叉污染，避免食品接触有毒物、不洁物； （五）法律、法规规定的其他条件。"},{"i":12,"n":"第十二条","txt":"申请食品经营许可，应当向申请人所在地县级以上地方食品药品监督管理部门提交下列材料： （一）食品经营许可申请书； （二）营业执照或者其他主体资格证明文件复印件； （三）与食品经营相适应的主要设备设施布局、操作流程等文件； （四）食品安全自查、从业人员健康管理、进货查验记录、食品安全事故处置等保证食品安全的规章制度。 利用自动售货设备从事食品销售的，申请人还应当提交自动售货设备的产品合格证明、具体放置地点，经营者名称、住所、联系方式、食品经营许可证的公示方法等材料。 申请人委托他人办理食品经营许可申请的，代理人应当提交授权委托书以及代理人的身份证明文件。"},{"i":13,"n":"第十三条","txt":"申请人应当如实向食品药品监督管理部门提交有关材料和反映真实情况，对申请材料的真实性负责，并在申请书等材料上签名或者盖章。"},{"i":14,"n":"第十四条","txt":"县级以上地方食品药品监督管理部门对申请人提出的食品经营许可申请，应当根据下列情况分别作出处理： （一）申请事项依法不需要取得食品经营许可的，应当即时告知申请人不受理。 （二）申请事项依法不属于食品药品监督管理部门职权范围的，应当即时作出不予受理的决定，并告知申请人向有关行政机关申请。 （三）申请材料存在可以当场更正的错误的，应当允许申请人当场更正，由申请人在更正处签名或者盖章，注明更正日期。 （四）申请材料不齐全或者不符合法定形式的，应当当场或者在5个工作日内一次告知申请人需要补正的全部内容。当场告知的，应当将申请材料退回申请人；在5个工作日内告知的，应当收取申请材料并出具收到申请材料的凭据。逾期不告知的，自收到申请材料之日起即为受理。 （五）申请材料齐全、符合法定形式，或者申请人按照要求提交全部补正材料的，应当受理食品经营许可申请。"},{"i":15,"n":"第十五条","txt":"县级以上地方食品药品监督管理部门对申请人提出的申请决定予以受理的，应当出具受理通知书；决定不予受理的，应当出具不予受理通知书，说明不予受理的理由，并告知申请人依法享有申请行政复议或者提起行政诉讼的权利。"},{"i":16,"n":"第十六条","txt":"县级以上地方食品药品监督管理部门应当对申请人提交的许可申请材料进行审查。需要对申请材料的实质内容进行核实的，应当进行现场核查。仅申请预包装食品销售（不含冷藏冷冻食品）的，以及食品经营许可变更不改变设施和布局的，可以不进行现场核查。 现场核查应当由符合要求的核查人员进行。核查人员不得少于2人。核查人员应当出示有效证件，填写食品经营许可现场核查表，制作现场核查记录，经申请人核对无误后，由核查人员和申请人在核查表和记录上签名或者盖章。申请人拒绝签名或者盖章的，核查人员应当注明情况。 食品药品监督管理部门可以委托下级食品药品监督管理部门，对受理的食品经营许可申请进行现场核查。 核查人员应当自接受现场核查任务之日起10个工作日内，完成对经营场所的现场核查。"},{"i":17,"n":"第十七条","txt":"除可以当场作出行政许可决定的外，县级以上地方食品药品监督管理部门应当自受理申请之日起20个工作日内作出是否准予行政许可的决定。因特殊原因需要延长期限的，经本行政机关负责人批准，可以延长10个工作日，并应当将延长期限的理由告知申请人。"},{"i":18,"n":"第十八条","txt":"县级以上地方食品药品监督管理部门应当根据申请材料审查和现场核查等情况，对符合条件的，作出准予经营许可的决定，并自作出决定之日起10个工作日内向申请人颁发食品经营许可证；对不符合条件的，应当及时作出不予许可的书面决定并说明理由，同时告知申请人依法享有申请行政复议或者提起行政诉讼的权利。"},{"i":19,"n":"第十九条","txt":"食品经营许可证发证日期为许可决定作出的日期，有效期为5年。"},{"i":20,"n":"第二十条","txt":"县级以上地方食品药品监督管理部门认为食品经营许可申请涉及公共利益的重大事项，需要听证的，应当向社会公告并举行听证。"},{"i":21,"n":"第二十一条","txt":"食品经营许可直接涉及申请人与他人之间重大利益关系的，县级以上地方食品药品监督管理部门在作出行政许可决定前，应当告知申请人、利害关系人享有要求听证的权利。 申请人、利害关系人在被告知听证权利之日起5个工作日内提出听证申请的，食品药品监督管理部门应当在20个工作日内组织听证。听证期限不计算在行政许可审查期限之内。"},{"i":22,"n":"第二十二条","txt":"食品经营许可证分为正本、副本。正本、副本具有同等法律效力。 国家食品药品监督管理总局负责制定食品经营许可证正本、副本式样。省、自治区、直辖市食品药品监督管理部门负责本行政区域食品经营许可证的印制、发放等管理工作。"},{"i":23,"n":"第二十三条","txt":"食品经营许可证应当载明：经营者名称、社会信用代码（个体经营者为身份证号码）、法定代表人（负责人）、住所、经营场所、主体业态、经营项目、许可证编号、有效期、日常监督管理机构、日常监督管理人员、投诉举报电话、发证机关、签发人、发证日期和二维码。 在经营场所外设置仓库（包括自有和租赁）的，还应当在副本中载明仓库具体地址。"},{"i":24,"n":"第二十四条","txt":"食品经营许可证编号由JY（“经营”的汉语拼音字母缩写）和14位阿拉伯数字组成。数字从左至右依次为：1位主体业态代码、2位省（自治区、直辖市）代码、2位市（地）代码、2位县（区）代码、6位顺序码、1位校验码。"},{"i":25,"n":"第二十五条","txt":"日常监督管理人员为负责对食品经营活动进行日常监督管理的工作人员。日常监督管理人员发生变化的，可以通过签章的方式在许可证上变更。"},{"i":26,"n":"第二十六条","txt":"食品经营者应当妥善保管食品经营许可证，不得伪造、涂改、倒卖、出租、出借、转让。 食品经营者应当在经营场所的显著位置悬挂或者摆放食品经营许可证正本。"},{"i":27,"n":"第二十七条","txt":"食品经营许可证载明的许可事项发生变化的，食品经营者应当在变化后10个工作日内向原发证的食品药品监督管理部门申请变更经营许可。 经营场所发生变化的，应当重新申请食品经营许可。外设仓库地址发生变化的，食品经营者应当在变化后10个工作日内向原发证的食品药品监督管理部门报告。"},{"i":28,"n":"第二十八条","txt":"申请变更食品经营许可的，应当提交下列申请材料： （一）食品经营许可变更申请书； （二）食品经营许可证正本、副本； （三）与变更食品经营许可事项有关的其他材料。"},{"i":29,"n":"第二十九条","txt":"食品经营者需要延续依法取得的食品经营许可的有效期的，应当在该食品经营许可有效期届满30个工作日前，向原发证的食品药品监督管理部门提出申请。"},{"i":30,"n":"第三十条","txt":"食品经营者申请延续食品经营许可，应当提交下列材料： （一）食品经营许可延续申请书； （二）食品经营许可证正本、副本； （三）与延续食品经营许可事项有关的其他材料。"},{"i":31,"n":"第三十一条","txt":"县级以上地方食品药品监督管理部门应当根据被许可人的延续申请，在该食品经营许可有效期届满前作出是否准予延续的决定。"},{"i":32,"n":"第三十二条","txt":"县级以上地方食品药品监督管理部门应当对变更或者延续食品经营许可的申请材料进行审查。 申请人声明经营条件未发生变化的，县级以上地方食品药品监督管理部门可以不再进行现场核查。 申请人的经营条件发生变化，可能影响食品安全的，食品药品监督管理部门应当就变化情况进行现场核查。"},{"i":33,"n":"第三十三条","txt":"原发证的食品药品监督管理部门决定准予变更的，应当向申请人颁发新的食品经营许可证。食品经营许可证编号不变，发证日期为食品药品监督管理部门作出变更许可决定的日期，有效期与原证书一致。"},{"i":34,"n":"第三十四条","txt":"原发证的食品药品监督管理部门决定准予延续的，应当向申请人颁发新的食品经营许可证，许可证编号不变，有效期自食品药品监督管理部门作出延续许可决定之日起计算。 不符合许可条件的，原发证的食品药品监督管理部门应当作出不予延续食品经营许可的书面决定，并说明理由。"},{"i":35,"n":"第三十五条","txt":"食品经营许可证遗失、损坏的，应当向原发证的食品药品监督管理部门申请补办，并提交下列材料： （一）食品经营许可证补办申请书； （二）食品经营许可证遗失的，申请人应当提交在县级以上地方食品药品监督管理部门网站或者其他县级以上主要媒体上刊登遗失公告的材料；食品经营许可证损坏的，应当提交损坏的食品经营许可证原件。 材料符合要求的，县级以上地方食品药品监督管理部门应当在受理后20个工作日内予以补发。 因遗失、损坏补发的食品经营许可证，许可证编号不变，发证日期和有效期与原证书保持一致。"},{"i":36,"n":"第三十六条","txt":"食品经营者终止食品经营，食品经营许可被撤回、撤销或者食品经营许可证被吊销的，应当在30个工作日内向原发证的食品药品监督管理部门申请办理注销手续。 食品经营者申请注销食品经营许可的，应当向原发证的食品药品监督管理部门提交下列材料： （一）食品经营许可注销申请书； （二）食品经营许可证正本、副本； （三）与注销食品经营许可有关的其他材料。"},{"i":37,"n":"第三十七条","txt":"有下列情形之一，食品经营者未按规定申请办理注销手续的，原发证的食品药品监督管理部门应当依法办理食品经营许可注销手续： （一）食品经营许可有效期届满未申请延续的； （二）食品经营者主体资格依法终止的； （三）食品经营许可依法被撤回、撤销或者食品经营许可证依法被吊销的； （四）因不可抗力导致食品经营许可事项无法实施的； （五）法律法规规定的应当注销食品经营许可的其他情形。 食品经营许可被注销的，许可证编号不得再次使用。"},{"i":38,"n":"第三十八条","txt":"食品经营许可证变更、延续、补办与注销的有关程序参照本办法第二章和第三章的有关规定执行。"},{"i":39,"n":"第三十九条","txt":"县级以上地方食品药品监督管理部门应当依据法律法规规定的职责，对食品经营者的许可事项进行监督检查。"},{"i":40,"n":"第四十条","txt":"县级以上地方食品药品监督管理部门应当建立食品许可管理信息平台，便于公民、法人和其他社会组织查询。 县级以上地方食品药品监督管理部门应当将食品经营许可颁发、许可事项检查、日常监督检查、许可违法行为查处等情况记入食品经营者食品安全信用档案，并依法向社会公布；对有不良信用记录的食品经营者应当增加监督检查频次。"},{"i":41,"n":"第四十一条","txt":"县级以上地方食品药品监督管理部门日常监督管理人员负责所管辖食品经营者许可事项的监督检查，必要时，应当依法对相关食品仓储、物流企业进行检查。 日常监督管理人员应当按照规定的频次对所管辖的食品经营者实施全覆盖检查。"},{"i":42,"n":"第四十二条","txt":"县级以上地方食品药品监督管理部门及其工作人员履行食品经营许可管理职责，应当自觉接受食品经营者和社会监督。 接到有关工作人员在食品经营许可管理过程中存在违法行为的举报，食品药品监督管理部门应当及时进行调查核实。情况属实的，应当立即纠正。"},{"i":43,"n":"第四十三条","txt":"县级以上地方食品药品监督管理部门应当建立食品经营许可档案管理制度，将办理食品经营许可的有关材料、发证情况及时归档。"},{"i":44,"n":"第四十四条","txt":"国家食品药品监督管理总局可以定期或者不定期组织对全国食品经营许可工作进行监督检查；省、自治区、直辖市食品药品监督管理部门可以定期或者不定期组织对本行政区域内的食品经营许可工作进行监督检查。"},{"i":45,"n":"第四十五条","txt":"未取得食品经营许可从事食品经营活动的，由县级以上地方食品药品监督管理部门依照《中华人民共和国食品安全法》第一百二十二条的规定给予处罚。"},{"i":46,"n":"第四十六条","txt":"许可申请人隐瞒真实情况或者提供虚假材料申请食品经营许可的，由县级以上地方食品药品监督管理部门给予警告。申请人在1年内不得再次申请食品经营许可。"},{"i":47,"n":"第四十七条","txt":"被许可人以欺骗、贿赂等不正当手段取得食品经营许可的，由原发证的食品药品监督管理部门撤销许可，并处1万元以上3万元以下罚款。被许可人在3年内不得再次申请食品经营许可。"},{"i":48,"n":"第四十八条","txt":"违反本办法第二十六条第一款规定，食品经营者伪造、涂改、倒卖、出租、出借、转让食品经营许可证的，由县级以上地方食品药品监督管理部门责令改正，给予警告，并处1万元以下罚款；情节严重的，处1万元以上3万元以下罚款。 违反本办法第二十六条第二款规定，食品经营者未按规定在经营场所的显著位置悬挂或者摆放食品经营许可证的，由县级以上地方食品药品监督管理部门责令改正；拒不改正的，给予警告。"},{"i":49,"n":"第四十九条","txt":"违反本办法第二十七条第一款规定，食品经营许可证载明的许可事项发生变化，食品经营者未按规定申请变更经营许可的，由原发证的食品药品监督管理部门责令改正，给予警告；拒不改正的，处2000元以上1万元以下罚款。 违反本办法第二十七条第二款规定或者第三十六条第一款规定，食品经营者外设仓库地址发生变化，未按规定报告的，或者食品经营者终止食品经营，食品经营许可被撤回、撤销或者食品经营许可证被吊销，未按规定申请办理注销手续的，由原发证的食品药品监督管理部门责令改正；拒不改正的，给予警告，并处2000元以下罚款。"},{"i":50,"n":"第五十条","txt":"被吊销经营许可证的食品经营者及其法定代表人、直接负责的主管人员和其他直接责任人员自处罚决定作出之日起5年内不得申请食品生产经营许可，或者从事食品生产经营管理工作、担任食品生产经营企业食品安全管理人员。"},{"i":51,"n":"第五十一条","txt":"食品药品监督管理部门对不符合条件的申请人准予许可，或者超越法定职权准予许可的，依照《中华人民共和国食品安全法》第一百四十四条的规定给予处分。"},{"i":52,"n":"第五十二条","txt":"本办法下列用语的含义： （一）单位食堂，指设于机关、事业单位、社会团体、民办非企业单位、企业等，供应内部职工、学生等集中就餐的餐饮服务提供者； （二）预包装食品，指预先定量包装或者制作在包装材料和容器中的食品，包括预先定量包装以及预先定量制作在包装材料和容器中并且在一定量限范围内具有统一的质量或体积标识的食品； （三）散装食品，指无预先定量包装，需称重销售的食品，包括无包装和带非定量包装的食品； （四）热食类食品，指食品原料经粗加工、切配并经过蒸、煮、烹、煎、炒、烤、炸等烹饪工艺制作，在一定热度状态下食用的即食食品，含火锅和烧烤等烹饪方式加工而成的食品等； （五）冷食类食品，指一般无需再加热，在常温或者低温状态下即可食用的食品，含熟食卤味、生食瓜果蔬菜、腌菜等； （六）生食类食品，一般特指生食水产品； （七）糕点类食品，指以粮、糖、油、蛋、奶等为主要原料经焙烤等工艺现场加工而成的食品，"},{"i":53,"n":"第五十三条","txt":"对食品摊贩等的监督管理，按照省、自治区、直辖市制定的具体管理办法执行。"},{"i":54,"n":"第五十四条","txt":"食品经营者在本办法施行前已经取得的许可证在有效期内继续有效。"},{"i":55,"n":"第五十五条","txt":"各省、自治区、直辖市食品药品监督管理部门可以根据本行政区域实际情况，制定有关食品经营许可管理的具体实施办法。"},{"i":56,"n":"第五十六条","txt":"食品药品监督管理部门制作的食品经营许可电子证书与印制的食品经营许可证书具有同等法律效力。"},{"i":57,"n":"第五十七条","txt":"本办法自2015年10月1日起施行。"}],"shiyongnongchanpinshichangxiaoshouzhilianganquanji5e1757":[{"i":1,"n":"第一条","txt":"为规范食用农产品市场销售行为，加强食用农产品市场销售质量安全监督管理，保证食用农产品质量安全，根据《中华人民共和国食品安全法》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"食用农产品市场销售质量安全及其监督管理适用本办法。 　　本办法所称食用农产品市场销售，是指通过集中交易市场、商场、超市、便利店等销售食用农产品的活动。 　　本办法所称集中交易市场，是指销售食用农产品的批发市场和零售市场（含农贸市场）。"},{"i":3,"n":"第三条","txt":"国家食品药品监督管理总局负责监督指导全国食用农产品市场销售质量安全的监督管理工作。 　　省、自治区、直辖市食品药品监督管理部门负责监督指导本行政区域食用农产品市场销售质量安全的监督管理工作。 　　市、县级食品药品监督管理部门负责本行政区域食用农产品市场销售质量安全的监督管理工作。"},{"i":4,"n":"第四条","txt":"食用农产品市场销售质量安全及其监督管理工作坚持预防为主、风险管理原则，推进产地准出与市场准入衔接，保证市场销售的食用农产品可追溯。"},{"i":5,"n":"第五条","txt":"县级以上食品药品监督管理部门应当与相关部门建立健全食用农产品市场销售质量安全监督管理协作机制。"},{"i":6,"n":"第六条","txt":"集中交易市场开办者应当依法对入场销售者履行管理义务，保障市场规范运行。 　　食用农产品销售者（以下简称销售者）应当依照法律法规和食品安全标准从事销售活动，保证食用农产品质量安全。"},{"i":7,"n":"第七条","txt":"县级以上食品药品监督管理部门应当加强信息化建设，汇总分析食用农产品质量安全信息，加强监督管理，防范食品安全风险。 　　集中交易市场开办者和销售者应当按照食品药品监督管理部门的要求提供并公开食用农产品质量安全数据信息。 　　鼓励集中交易市场开办者和销售者建立食品安全追溯体系，利用信息化手段采集和记录所销售的食用农产品信息。"},{"i":8,"n":"第八条","txt":"集中交易市场开办者相关行业协会和食用农产品相关行业协会应当加强行业自律，督促集中交易市场开办者和销售者履行法律义务。"},{"i":9,"n":"第九条","txt":"集中交易市场开办者应当建立健全食品安全管理制度，督促销售者履行义务，加强食用农产品质量安全风险防控。 　　集中交易市场开办者主要负责人应当落实食品安全管理制度，对本市场的食用农产品质量安全工作全面负责。 　　集中交易市场开办者应当配备专职或者兼职食品安全管理人员、专业技术人员，明确入场销售者的食品安全管理责任，组织食品安全知识培训。 　　集中交易市场开办者应当制定食品安全事故处置方案，根据食用农产品风险程度确定检查重点、方式、频次等，定期检查食品安全事故防范措施落实情况，及时消除食用农产品质量安全隐患。"},{"i":10,"n":"第十条","txt":"集中交易市场开办者应当按照食用农产品类别实行分区销售。 　　集中交易市场开办者销售和贮存食用农产品的环境、设施、设备等应当符合食用农产品质量安全的要求。"},{"i":11,"n":"第十一条","txt":"集中交易市场开办者应当建立入场销售者档案，如实记录销售者名称或者姓名、社会信用代码或者身份证号码、联系方式、住所、食用农产品主要品种、进货渠道、产地等信息。 　　销售者档案信息保存期限不少于销售者停止销售后6个月。集中交易市场开办者应当对销售者档案及时更新，保证其准确性、真实性和完整性。 　　集中交易市场开办者应当如实向所在地县级食品药品监督管理部门报告市场名称、住所、类型、法定代表人或者负责人姓名、食品安全管理制度、食用农产品主要种类、摊位数量等信息。"},{"i":12,"n":"第十二条","txt":"集中交易市场开办者应当查验并留存入场销售者的社会信用代码或者身份证复印件，食用农产品产地证明或者购货凭证、合格证明文件。 　　销售者无法提供食用农产品产地证明或者购货凭证、合格证明文件的，集中交易市场开办者应当进行抽样检验或者快速检测；抽样检验或者快速检测合格的，方可进入市场销售。"},{"i":13,"n":"第十三条","txt":"食用农产品生产企业或者农民专业合作经济组织及其成员生产的食用农产品，由本单位出具产地证明；其他食用农产品生产者或者个人生产的食用农产品，由村民委员会、乡镇政府等出具产地证明；无公害农产品、绿色食品、有机农产品以及农产品地理标志等食用农产品标志上所标注的产地信息，可以作为产地证明。"},{"i":14,"n":"第十四条","txt":"供货者提供的销售凭证、销售者与供货者签订的食用农产品采购协议，可以作为食用农产品购货凭证。"},{"i":15,"n":"第十五条","txt":"有关部门出具的食用农产品质量安全合格证明或者销售者自检合格证明等可以作为合格证明文件。 　　销售按照有关规定需要检疫、检验的肉类，应当提供检疫合格证明、肉类检验合格证明等证明文件。 　　销售进口食用农产品，应当提供出入境检验检疫部门出具的入境货物检验检疫证明等证明文件。"},{"i":16,"n":"第十六条","txt":"集中交易市场开办者应当建立食用农产品检查制度，对销售者的销售环境和条件以及食用农产品质量安全状况进行检查。 　　集中交易市场开办者发现存在食用农产品不符合食品安全标准等违法行为的，应当要求销售者立即停止销售，依照集中交易市场管理规定或者与销售者签订的协议进行处理，并向所在地县级食品药品监督管理部门报告。"},{"i":17,"n":"第十七条","txt":"集中交易市场开办者应当在醒目位置及时公布食品安全管理制度、食品安全管理人员、食用农产品抽样检验结果以及不合格食用农产品处理结果、投诉举报电话等信息。"},{"i":18,"n":"第十八条","txt":"批发市场开办者应当与入场销售者签订食用农产品质量安全协议，明确双方食用农产品质量安全权利义务；未签订食用农产品质量安全协议的，不得进入批发市场进行销售。 　　鼓励零售市场开办者与销售者签订食用农产品质量安全协议，明确双方食用农产品质量安全权利义务。"},{"i":19,"n":"第十九条","txt":"批发市场开办者应当配备检验设备和检验人员，或者委托具有资质的食品检验机构，开展食用农产品抽样检验或者快速检测，并根据食用农产品种类和风险等级确定抽样检验或者快速检测频次。 　　鼓励零售市场开办者配备检验设备和检验人员，或者委托具有资质的食品检验机构，开展食用农产品抽样检验或者快速检测。"},{"i":20,"n":"第二十条","txt":"批发市场开办者应当印制统一格式的销售凭证，载明食用农产品名称、产地、数量、销售日期以及销售者名称、地址、联系方式等项目。销售凭证可以作为销售者的销售记录和其他购货者的进货查验记录凭证。 　　销售者应当按照销售凭证的要求如实记录。记录和销售凭证保存期限不得少于6个月。"},{"i":21,"n":"第二十一条","txt":"与屠宰厂（场）、食用农产品种植养殖基地签订协议的批发市场开办者应当对屠宰厂（场）和食用农产品种植养殖基地进行实地考察，了解食用农产品生产过程以及相关信息，查验种植养殖基地食用农产品相关证明材料以及票据等。"},{"i":22,"n":"第二十二条","txt":"鼓励食用农产品批发市场开办者改造升级，更新设施、设备和场所，提高食品安全保障能力和水平。 　　鼓励批发市场开办者与取得无公害农产品、绿色食品、有机农产品、农产品地理标志等认证的食用农产品种植养殖基地或者生产加工企业签订食用农产品质量安全合作协议。"},{"i":23,"n":"第二十三条","txt":"销售者应当具有与其销售的食用农产品品种、数量相适应的销售和贮存场所，保持场所环境整洁，并与有毒、有害场所以及其他污染源保持适当的距离。"},{"i":24,"n":"第二十四条","txt":"销售者应当具有与其销售的食用农产品品种、数量相适应的销售设备或者设施。 　　销售冷藏、冷冻食用农产品的，应当配备与销售品种相适应的冷藏、冷冻设施，并符合保证食用农产品质量安全所需要的温度、湿度和环境等特殊要求。 　　鼓励采用冷链、净菜上市、畜禽产品冷鲜上市等方式销售食用农产品。"},{"i":25,"n":"第二十五条","txt":"禁止销售下列食用农产品： 　　（一）使用国家禁止的兽药和剧毒、高毒农药，或者添加食品添加剂以外的化学物质和其他可能危害人体健康的物质的； 　　（二）致病性微生物、农药残留、兽药残留、生物毒素、重金属等污染物质以及其他危害人体健康的物质含量超过食品安全标准限量的； 　　（三）超范围、超限量使用食品添加剂的； 　　（四）腐败变质、油脂酸败、霉变生虫、污秽不洁、混有异物、掺假掺杂或者感官性状异常的； 　　（五）病死、毒死或者死因不明的禽、畜、兽、水产动物肉类； 　　（六）未按规定进行检疫或者检疫不合格的肉类； 　　（七）未按规定进行检验或者检验不合格的肉类； 　　（八）使用的保鲜剂、防腐剂等食品添加剂和包装材料等食品相关产品不符合食品安全国家标准的； 　　（九）被包装材料、容器、运输工具等污染的； 　　（十）标注虚假生产日期、保质期或者超过保质期的； 　　（十一）国家为防病等特殊需要明令禁止"},{"i":26,"n":"第二十六条","txt":"销售者采购食用农产品，应当按照规定查验相关证明材料，不符合要求的，不得采购和销售。 　　销售者应当建立食用农产品进货查验记录制度，如实记录食用农产品名称、数量、进货日期以及供货者名称、地址、联系方式等内容，并保存相关凭证。记录和凭证保存期限不得少于6个月。 　　实行统一配送销售方式的食用农产品销售企业，可以由企业总部统一建立进货查验记录制度；所属各销售门店应当保存总部的配送清单以及相应的合格证明文件。配送清单和合格证明文件保存期限不得少于6个月。 　　从事食用农产品批发业务的销售企业，应当建立食用农产品销售记录制度，如实记录批发食用农产品名称、数量、销售日期以及购货者名称、地址、联系方式等内容，并保存相关凭证。记录和凭证保存期限不得少于6个月。 　　鼓励和引导有条件的销售企业采用扫描、拍照、数据交换、电子表格等方式，建立食用农产品进货查验记录制度。"},{"i":27,"n":"第二十七条","txt":"销售者贮存食用农产品，应当定期检查库存，及时清理腐败变质、油脂酸败、霉变生虫、污秽不洁或者感官性状异常的食用农产品。 　　销售者贮存食用农产品，应当如实记录食用农产品名称、产地、贮存日期、生产者或者供货者名称或者姓名、联系方式等内容，并在贮存场所保存记录。记录和凭证保存期限不得少于6个月。"},{"i":28,"n":"第二十八条","txt":"销售者租赁仓库的，应当选择能够保障食用农产品质量安全的食用农产品贮存服务提供者。 　　贮存服务提供者应当按照食用农产品质量安全的要求贮存食用农产品，履行下列义务： 　　（一）如实向所在地县级食品药品监督管理部门报告其名称、地址、法定代表人或者负责人姓名、社会信用代码或者身份证号码、联系方式以及所提供服务的销售者名称、贮存的食用农产品品种、数量等信息； 　　（二）查验所提供服务的销售者的营业执照或者身份证明和食用农产品产地或者来源证明、合格证明文件，并建立进出货台账，记录食用农产品名称、产地、贮存日期、出货日期、销售者名称或者姓名、联系方式等。进出货台账和相关证明材料保存期限不得少于6个月； 　　（三）保证贮存食用农产品的容器、工具和设备安全无害，保持清洁，防止污染，保证食用农产品质量安全所需的温度、湿度和环境等特殊要求，不得将食用农产品与有毒、有害物品一同贮存； 　　（四）贮存肉类冻品"},{"i":29,"n":"第二十九条","txt":"销售者自行运输或者委托承运人运输食用农产品的，运输容器、工具和设备应当安全无害，保持清洁，防止污染，并符合保证食用农产品质量安全所需的温度、湿度和环境等特殊要求，不得将食用农产品与有毒、有害物品一同运输。 　　承运人应当按照有关部门的规定履行相关食品安全义务。"},{"i":30,"n":"第三十条","txt":"销售企业应当建立健全食用农产品质量安全管理制度，配备必要的食品安全管理人员，对职工进行食品安全知识培训，制定食品安全事故处置方案，依法从事食用农产品销售活动。 　　鼓励销售企业配备相应的检验设备和检验人员，加强食用农产品检验工作。"},{"i":31,"n":"第三十一条","txt":"销售者应当建立食用农产品质量安全自查制度，定期对食用农产品质量安全情况进行检查，发现不符合食用农产品质量安全要求的，应当立即停止销售并采取整改措施；有发生食品安全事故潜在风险的，应当立即停止销售并向所在地县级食品药品监督管理部门报告。"},{"i":32,"n":"第三十二条","txt":"销售按照规定应当包装或者附加标签的食用农产品，在包装或者附加标签后方可销售。包装或者标签上应当按照规定标注食用农产品名称、产地、生产者、生产日期等内容；对保质期有要求的，应当标注保质期；保质期与贮藏条件有关的，应当予以标明；有分级标准或者使用食品添加剂的，应当标明产品质量等级或者食品添加剂名称。 　　食用农产品标签所用文字应当使用规范的中文，标注的内容应当清楚、明显，不得含有虚假、错误或者其他误导性内容。"},{"i":33,"n":"第三十三条","txt":"销售获得无公害农产品、绿色食品、有机农产品等认证的食用农产品以及省级以上农业行政部门规定的其他需要包装销售的食用农产品应当包装，并标注相应标志和发证机构，鲜活畜、禽、水产品等除外。"},{"i":34,"n":"第三十四条","txt":"销售未包装的食用农产品，应当在摊位（柜台）明显位置如实公布食用农产品名称、产地、生产者或者销售者名称或者姓名等信息。 　　鼓励采取附加标签、标示带、说明书等方式标明食用农产名称、产地、生产者或者销售者名称或者姓名、保存条件以及最佳食用期等内容。"},{"i":35,"n":"第三十五条","txt":"进口食用农产品的包装或者标签应当符合我国法律、行政法规的规定和食品安全国家标准的要求，并载明原产地，境内代理商的名称、地址、联系方式。 　　进口鲜冻肉类产品的包装应当标明产品名称、原产国（地区）、生产企业名称、地址以及企业注册号、生产批号；外包装上应当以中文标明规格、产地、目的地、生产日期、保质期、储存温度等内容。 　　分装销售的进口食用农产品，应当在包装上保留原进口食用农产品全部信息以及分装企业、分装时间、地点、保质期等信息。"},{"i":36,"n":"第三十六条","txt":"销售者发现其销售的食用农产品不符合食品安全标准或者有证据证明可能危害人体健康的，应当立即停止销售，通知相关生产经营者、消费者，并记录停止销售和通知情况。 　　由于销售者的原因造成其销售的食用农产品不符合食品安全标准或者有证据证明可能危害人体健康的，销售者应当召回。 　　对于停止销售的食用农产品，销售者应当按照要求采取无害化处理、销毁等措施，防止其再次流入市场。但是，因标签、标志或者说明书不符合食品安全标准而被召回的食用农产品，在采取补救措施且能保证食用农产品质量安全的情况下可以继续销售；销售时应当向消费者明示补救措施。 　　集中交易市场开办者、销售者应当将食用农产品停止销售、召回和处理情况向所在地县级食品药品监督管理部门报告，配合政府有关部门根据有关法律法规进行处理，并记录相关情况。 　　集中交易市场开办者、销售者未依照本办法停止销售或者召回的，县级以上地方食品药品监督管理部门可以责令"},{"i":37,"n":"第三十七条","txt":"县级以上地方食品药品监督管理部门应当按照当地人民政府制定的本行政区域食品安全年度监督管理计划，开展食用农产品市场销售质量安全监督管理工作。 　　市、县级食品药品监督管理部门应当根据年度监督检查计划、食用农产品风险程度等，确定监督检查的重点、方式和频次，对本行政区域的集中交易市场开办者、销售者、贮存服务提供者进行日常监督检查。"},{"i":38,"n":"第三十八条","txt":"市、县级食品药品监督管理部门按照地方政府属地管理要求，可以依法采取下列措施，对集中交易市场开办者、销售者、贮存服务提供者遵守本办法情况进行日常监督检查： 　　（一）对食用农产品销售、贮存和运输等场所进行现场检查； 　　（二）对食用农产品进行抽样检验； 　　（三）向当事人和其他有关人员调查了解与食用农产品销售活动和质量安全有关的情况； 　　（四）检查食用农产品进货查验记录制度落实情况，查阅、复制与食用农产品质量安全有关的记录、协议、发票以及其他资料； 　　（五）对有证据证明不符合食品安全标准或者有证据证明存在质量安全隐患以及用于违法生产经营的食用农产品，有权查封、扣押、监督销毁； 　　（六）查封违法从事食用农产品销售活动的场所。 　　集中交易市场开办者、销售者、贮存服务提供者对食品药品监督管理部门实施的监督检查应当予以配合，不得拒绝、阻挠、干涉。"},{"i":39,"n":"第三十九条","txt":"市、县级食品药品监督管理部门应当建立本行政区域集中交易市场开办者、销售者、贮存服务提供者食品安全信用档案，如实记录日常监督检查结果、违法行为查处等情况，依法向社会公布并实时更新。对有不良信用记录的集中交易市场开办者、销售者、贮存服务提供者增加监督检查频次；将违法行为情节严重的集中交易市场开办者、销售者、贮存服务提供者及其主要负责人和其他直接责任人的相关信息，列入严重违法者名单，并予以公布。 　　市、县级食品药品监督管理部门应当逐步建立销售者市场准入前信用承诺制度，要求销售者以规范格式向社会作出公开承诺，如存在违法失信销售行为将自愿接受信用惩戒。信用承诺纳入销售者信用档案，接受社会监督，并作为事中事后监督管理的参考。"},{"i":40,"n":"第四十条","txt":"食用农产品在销售过程中存在质量安全隐患，未及时采取有效措施消除的，市、县级食品药品监督管理部门可以对集中交易市场开办者、销售者、贮存服务提供者的法定代表人或者主要负责人进行责任约谈。 　　被约谈者无正当理由拒不按时参加约谈或者未按要求落实整改的，食品药品监督管理部门应当记入集中交易市场开办者、销售者、贮存服务提供者食品安全信用档案。"},{"i":41,"n":"第四十一条","txt":"县级以上地方食品药品监督管理部门应当将食用农产品监督抽检纳入年度检验检测工作计划，对食用农产品进行定期或者不定期抽样检验，并依据有关规定公布检验结果。 　　市、县级食品药品监督管理部门可以采用国家规定的快速检测方法对食用农产品质量安全进行抽查检测，抽查检测结果表明食用农产品可能存在质量安全隐患的，销售者应当暂停销售；抽查检测结果确定食用农产品不符合食品安全标准的，可以作为行政处罚的依据。 　　被抽查人对快速检测结果有异议的，可以自收到检测结果时起4小时内申请复检。复检结论仍不合格的，复检费用由申请人承担。复检不得采用快速检测方法。"},{"i":42,"n":"第四十二条","txt":"市、县级食品药品监督管理部门应当依据职责公布食用农产品监督管理信息。 　　公布食用农产品监督管理信息，应当做到准确、及时、客观，并进行必要的解释说明，避免误导消费者和社会舆论。"},{"i":43,"n":"第四十三条","txt":"市、县级食品药品监督管理部门发现批发市场有本办法禁止销售的食用农产品，在依法处理的同时，应当及时追查食用农产品来源和流向，查明原因、控制风险并报告上级食品药品监督管理部门，同时通报所涉地同级食品药品监督管理部门；涉及种植养殖和进出口环节的，还应当通报相关农业行政部门和出入境检验检疫部门。"},{"i":44,"n":"第四十四条","txt":"市、县级食品药品监督管理部门发现超出其管辖范围的食用农产品质量安全案件线索，应当及时移送有管辖权的食品药品监督管理部门。"},{"i":45,"n":"第四十五条","txt":"县级以上地方食品药品监督管理部门在监督管理中发现食用农产品质量安全事故，或者接到有关食用农产品质量安全事故的举报，应当立即会同相关部门进行调查处理，采取措施防止或者减少社会危害，按照应急预案的规定报告当地人民政府和上级食品药品监督管理部门，并在当地人民政府统一领导下及时开展调查处理。"},{"i":46,"n":"第四十六条","txt":"食用农产品市场销售质量安全的违法行为，食品安全法等法律法规已有规定的，依照其规定。"},{"i":47,"n":"第四十七条","txt":"集中交易市场开办者违反本办法第九条至第十二条、第十六条第二款、第十七条规定，有下列情形之一的，由县级以上食品药品监督管理部门责令改正，给予警告；拒不改正的，处5000元以上3万元以下罚款： 　　（一）未建立或者落实食品安全管理制度的； 　　（二）未按要求配备食品安全管理人员、专业技术人员，或者未组织食品安全知识培训的； 　　（三）未制定食品安全事故处置方案的； 　　（四）未按食用农产品类别实行分区销售的； 　　（五）环境、设施、设备等不符合有关食用农产品质量安全要求的； 　　（六）未按要求建立入场销售者档案，或者未按要求保存和更新销售者档案的； 　　（七）未如实向所在地县级食品药品监督管理部门报告市场基本信息的； 　　（八）未查验并留存入场销售者的社会信用代码或者身份证复印件、食用农产品产地证明或者购货凭证、合格证明文件的； 　　（九）未进行抽样检验或者快速检测，允许无法提供食用农产品"},{"i":48,"n":"第四十八条","txt":"批发市场开办者违反本办法第十八条第一款、第二十条规定，未与入场销售者签订食用农产品质量安全协议，或者未印制统一格式的食用农产品销售凭证的，由县级以上食品药品监督管理部门责令改正，给予警告；拒不改正的，处1万元以上3万元以下罚款。"},{"i":49,"n":"第四十九条","txt":"销售者违反本办法第二十四条第二款规定，未按要求配备与销售品种相适应的冷藏、冷冻设施，或者温度、湿度和环境等不符合特殊要求的，由县级以上食品药品监督管理部门责令改正，给予警告；拒不改正的，处5000元以上3万元以下罚款。"},{"i":50,"n":"第五十条","txt":"销售者违反本办法第二十五条第一项、第五项、第六项、第十一项规定的，由县级以上食品药品监督管理部门依照食品安全法第一百二十三条第一款的规定给予处罚。 　　违反本办法第二十五条第二项、第三项、第四项、第十项规定的，由县级以上食品药品监督管理部门依照食品安全法第一百二十四条第一款的规定给予处罚。 　　违反本办法第二十五条第七项、第十二项规定，销售未按规定进行检验的肉类，或者销售标注虚假的食用农产品产地、生产者名称、生产者地址，标注伪造、冒用的认证标志等质量标志的食用农产品的，由县级以上食品药品监督管理部门责令改正，处1万元以上3万元以下罚款。 　　违反本办法第二十五条第八项、第九项规定的，由县级以上食品药品监督管理部门依照食品安全法第一百二十五条第一款的规定给予处罚。"},{"i":51,"n":"第五十一条","txt":"销售者违反本办法第二十八条第一款规定，未按要求选择贮存服务提供者，或者贮存服务提供者违反本办法第二十八条第二款规定，未履行食用农产品贮存相关义务的，由县级以上食品药品监督管理部门责令改正，给予警告；拒不改正的，处5000元以上3万元以下罚款。"},{"i":52,"n":"第五十二条","txt":"销售者违反本办法第三十二条、第三十三条、第三十五条规定，未按要求进行包装或者附加标签的，由县级以上食品药品监督管理部门责令改正，给予警告；拒不改正的，处5000元以上3万元以下罚款。"},{"i":53,"n":"第五十三条","txt":"销售者违反本办法第三十四条第一款规定，未按要求公布食用农产品相关信息的，由县级以上食品药品监督管理部门责令改正，给予警告；拒不改正的，处5000元以上1万元以下罚款。"},{"i":54,"n":"第五十四条","txt":"销售者履行了本办法规定的食用农产品进货查验等义务，有充分证据证明其不知道所采购的食用农产品不符合食品安全标准，并能如实说明其进货来源的，可以免予处罚，但应当依法没收其不符合食品安全标准的食用农产品；造成人身、财产或者其他损害的，依法承担赔偿责任。"},{"i":55,"n":"第五十五条","txt":"县级以上地方食品药品监督管理部门不履行食用农产品质量安全监督管理职责，或者滥用职权、玩忽职守、徇私舞弊的，依法追究直接负责的主管人员和其他直接责任人员的行政责任。"},{"i":56,"n":"第五十六条","txt":"违法销售食用农产品涉嫌犯罪的，由县级以上地方食品药品监督管理部门依法移交公安机关追究刑事责任。"},{"i":57,"n":"第五十七条","txt":"本办法下列用语的含义： 　　食用农产品，指在农业活动中获得的供人食用的植物、动物、微生物及其产品。农业活动，指传统的种植、养殖、采摘、捕捞等农业活动，以及设施农业、生物工程等现代农业活动。植物、动物、微生物及其产品，指在农业活动中直接获得的，以及经过分拣、去皮、剥壳、干燥、粉碎、清洗、切割、冷冻、打蜡、分级、包装等加工，但未改变其基本自然性状和化学性质的产品。 　　食用农产品集中交易市场开办者，指依法设立、为食用农产品交易提供平台、场地、设施、服务以及日常管理的企业法人或者其他组织。"},{"i":58,"n":"第五十八条","txt":"柜台出租者和展销会举办者销售食用农产品的，参照本办法对集中交易市场开办者的规定执行。"},{"i":59,"n":"第五十九条","txt":"食品摊贩等销售食用农产品的具体管理规定由省、自治区、直辖市制定。"},{"i":60,"n":"第六十条","txt":"本办法自2016年3月1日起施行。"}]};
